def next_number(prefix, table):
    year = datetime.now().year
    row = db.fetchone(
        f"""
        SELECT number FROM {table}
        WHERE number LIKE ?
        ORDER BY id DESC LIMIT 1
        """,
        (f"{prefix}-{year}-%",)
    )

    if not row:
        n = 1
    else:
        try:
            n = int(row["number"].split("-")[-1]) + 1
        except Exception:
            n = 1

    return f"{prefix}-{year}-{n:05d}"


def today():
    return datetime.now().strftime("%Y-%m-%d")


def now_time():
    return datetime.now().strftime("%H:%M")


def safe(value):
    return "" if value is None else str(value)


def xml_safe(value):
    """Remove characters that are illegal in XML/Office Open XML files."""
    text = safe(value)
    return "".join(ch for ch in text if ch in "\t\n\r" or ord(ch) >= 32)


def resolve_attachment_path(stored_path):
    """Resolve attachment paths saved by older app versions and packaged builds."""
    raw = unquote(safe(stored_path).strip().strip('"'))
    if not raw:
        return None
    if raw.lower().startswith("file://"):
        raw = raw[7:]
    if len(raw) >= 3 and raw[0] == "/" and raw[2] == ":":
        raw = raw[1:]
    candidates = []
    try:
        direct = Path(raw).expanduser()
        candidates.append(direct)
        candidates.append(Path(raw.replace("\\", "/")).expanduser())
    except Exception:
        pass
    normalized = raw.replace("\\", "/")
    basename = normalized.rstrip("/").split("/")[-1]
    if basename:
        candidates.extend([ATTACH_DIR / basename, APP_DIR / basename, REPORT_DIR / basename])
    # Relative paths from older versions may have been stored relative to cwd or app root.
    if not Path(normalized).is_absolute():
        candidates.extend([APP_DIR / normalized, ATTACH_DIR / normalized, Path.cwd() / normalized])
    seen = set()
    for candidate in candidates:
        try:
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            if candidate.is_file():
                return candidate
        except Exception:
            continue
    return None


def attachment_image_stream(stored_path):
    """Return a normalized PNG stream for Office/PDF exports, or None if not an image."""
    fp = resolve_attachment_path(stored_path)
    if not fp:
        return None
    try:
        with PILImage.open(fp) as image:
            image.load()
            if image.mode not in ("RGB", "RGBA"):
                image = image.convert("RGBA" if "transparency" in image.info else "RGB")
            stream = io.BytesIO()
            image.save(stream, format="PNG")
            stream.seek(0)
            return stream
    except Exception:
        return None


def observation_all_attachments(record_id):
    """Merge observation and close-out attachments without duplicating the same file."""
    combined = []
    seen = set()
    for item in attachment_rows("observation_attachments", record_id):
        path = safe(item["file_path"])
        key = path.casefold()
        if path and key not in seen:
            seen.add(key)
            combined.append({"file_path": path, "attachment_type": safe(item["attachment_type"])})
    for item in db.fetchall(
        "SELECT file_path, 'Close-out Evidence' AS attachment_type FROM observation_closeout_evidence WHERE observation_id=? ORDER BY id",
        (record_id,)
    ):
        path = safe(item["file_path"])
        key = path.casefold()
        if path and key not in seen:
            seen.add(key)
            combined.append({"file_path": path, "attachment_type": safe(item["attachment_type"])})
    # CAPA corrective-action evidence is also part of the linked observation's
    # evidence gallery and must be available to observation exports.
    for item in db.fetchall(
        """SELECT ca.file_path, COALESCE(NULLIF(ca.attachment_type,''),'CAPA Action Evidence') AS attachment_type
           FROM capa_attachments ca JOIN capa c ON c.id=ca.capa_id
           WHERE c.linked_observation_id=?
              OR c.reference_number=(SELECT number FROM observations WHERE id=?)
           ORDER BY ca.id""",
        (record_id, record_id)
    ):
        path = safe(item["file_path"])
        key = path.casefold()
        if path and key not in seen:
            seen.add(key)
            combined.append({"file_path": path, "attachment_type": safe(item["attachment_type"])})
    return combined


def attachment_names(table_name, record_id):
    return "; ".join(Path(safe(r["file_path"]).replace("\\", "/")).name for r in attachment_rows(table_name, record_id))


def attachment_export_map(table_name):
    return {
        "observations": "observation_attachments",
        "incidents": "incident_attachments",
        "audits": "audit_attachments",
        "capa": "capa_attachments",
    }.get(table_name)


def overdue(target, status):
    if not target or status in ("Closed", "Cancelled"):
        return False
    try:
        return date.fromisoformat(target) < date.today()
    except Exception:
        return False


def parse_corrective_actions(source):
    """Return a clean list of corrective-action strings from JSON, row, or legacy text."""
    if source is None:
        return []
    if isinstance(source, (list, tuple)):
        return [safe(x).strip() for x in source if safe(x).strip()]
    if isinstance(source, dict) or hasattr(source, "keys"):
        try:
            raw = source["corrective_actions_json"] if "corrective_actions_json" in source.keys() else ""
        except Exception:
            raw = ""
        actions = parse_corrective_actions(raw)
        if actions:
            return actions
        try:
            legacy = source["corrective_action"] if "corrective_action" in source.keys() else ""
        except Exception:
            legacy = ""
        return parse_corrective_actions(legacy)
    text_value = safe(source).strip()
    if not text_value:
        return []
    if text_value.startswith("["):
        try:
            data = json.loads(text_value)
            if isinstance(data, list):
                out = []
                for item in data:
                    if isinstance(item, dict):
                        val = safe(item.get("action") or item.get("text") or "").strip()
                    else:
                        val = safe(item).strip()
                    if val:
                        out.append(val)
                if out:
                    return out
        except Exception:
            pass
    lines = []
    for line in text_value.replace("\r", "\n").split("\n"):
        line = line.strip()
        if not line:
            continue
        if len(line) > 2 and line[0].isdigit() and line[1] in ".)":
            line = line[2:].strip()
        elif ". " in line[:4] and line.split(".", 1)[0].isdigit():
            line = line.split(".", 1)[1].strip()
        lines.append(line)
    return lines or ([text_value] if text_value else [])


def format_corrective_actions_display(actions, numbered=False):
    actions = parse_corrective_actions(actions)
    if not actions:
        return ""
    if numbered:
        return "\n".join(f"{i}. {a}" for i, a in enumerate(actions, 1))
    return "\n".join(actions)


def parse_capa_actions(source):
    """CAPA action items: [{action, evidence: [paths], has_evidence: bool}]"""
    if source is None:
        return []
    if isinstance(source, list):
        items = source
    else:
        text_value = safe(source).strip()
        if not text_value:
            return []
        try:
            items = json.loads(text_value)
        except Exception:
            items = [{"action": a, "evidence": [], "has_evidence": False} for a in parse_corrective_actions(text_value)]
    out = []
    for item in items or []:
        if isinstance(item, dict):
            action = safe(item.get("action") or item.get("text") or "").strip()
            evidence = item.get("evidence") or item.get("attachments") or []
            if isinstance(evidence, str):
                evidence = [evidence] if evidence.strip() else []
            evidence = [safe(p) for p in evidence if safe(p).strip()]
            existing_evidence = [p for p in evidence if resolve_attachment_path(p)]
            # Resolve old absolute/relative/gallery paths before deciding whether
            # evidence is genuinely present; file names alone never count.
            has_ev = bool(existing_evidence) or (bool(item.get("has_evidence")) and not evidence)
            if action:
                out.append({"action": action, "evidence": evidence, "has_evidence": has_ev})
        else:
            action = safe(item).strip()
            if action:
                out.append({"action": action, "evidence": [], "has_evidence": False})
    return out


def capa_actions_completion(actions):
    items = parse_capa_actions(actions)
    total = len(items)
    if total == 0:
        return 0, 0, 0, "Open"
    done = sum(1 for x in items if x.get("has_evidence") and (not x.get("evidence") or any(resolve_attachment_path(p) for p in x.get("evidence", []))))
    pct = int(round(100 * done / total))
    if done == 0:
        status = "Open"
    elif done < total:
        status = "Pending"
    else:
        status = "CAPA Action Complete"
    return done, total, pct, status


def sync_observation_from_capa(capa_row):
    """Synchronize a CAPA-linked HSE observation and its close-out approval."""
    ref = safe(capa_row["reference_number"] if "reference_number" in capa_row.keys() else "").strip()
    capa_no = safe(capa_row["number"] if "number" in capa_row.keys() else "").strip()
    linked_id = None
    try:
        linked_id = int(capa_row["linked_observation_id"]) if "linked_observation_id" in capa_row.keys() and capa_row["linked_observation_id"] else None
    except Exception:
        linked_id = None
    obs = db.fetchone("SELECT * FROM observations WHERE id=?", (linked_id,)) if linked_id else None
    if not obs and ref:
        obs = db.fetchone("SELECT * FROM observations WHERE number=?", (ref,))
    if not obs and capa_no:
        obs = db.fetchone("SELECT * FROM observations WHERE capa_number=? ORDER BY id DESC LIMIT 1", (capa_no,))
    if not obs:
        return
    # Backfill the stable relationship for records created by earlier versions.
    if linked_id is None:
        try:
            db.execute("UPDATE capa SET linked_observation_id=? WHERE id=?", (obs["id"], capa_row["id"]))
        except Exception:
            logging.exception("Unable to backfill CAPA-to-observation link")

    actions = capa_row["actions_json"] if "actions_json" in capa_row.keys() else "[]"
    done, total, pct, action_status = capa_actions_completion(actions)
    # Single approval workflow: CAPA action approval controls both registers.
    # Keep legacy close-out fields readable for old records, but do not require a
    # second close-out submission or approval stage.
    approval_key = safe(capa_row["approval_status"] if "approval_status" in capa_row.keys() else "").strip().casefold()
    closeout_status = safe(capa_row["capa_closeout_status"] if "capa_closeout_status" in capa_row.keys() else "").strip()
    closeout_key = closeout_status.casefold()
    capa_status_key = safe(capa_row["status"] if "status" in capa_row.keys() else "").strip().casefold()
    # Treat the CAPA register's final/closed state as the source of truth.
    # Older records may have status=Closed while legacy approval fields still say Pending.
    is_approved = (approval_key in ("approved", "capa approved")
                   or closeout_key in ("approved", "closed", "completed")
                   or capa_status_key in ("closed", "complete", "completed", "approved"))
    is_returned = approval_key in ("rejected", "not approved") or closeout_key in ("returned", "rejected", "not approved")
    submitted_by = safe(capa_row["capa_closeout_submitted_by"] if "capa_closeout_submitted_by" in capa_row.keys() else "")
    approved_by = (safe(capa_row["approved_by"] if "approved_by" in capa_row.keys() else "")
                   or safe(capa_row["capa_closeout_approved_by"] if "capa_closeout_approved_by" in capa_row.keys() else ""))
    approved_at = (safe(capa_row["approved_date"] if "approved_date" in capa_row.keys() else "")
                   or safe(capa_row["capa_closeout_approved_at"] if "capa_closeout_approved_at" in capa_row.keys() else ""))
    if approval_key in ("pending approval", "awaiting approval"):
        closeout_key = "submitted for review"

    # CAPA and Observation use one shared close-out decision. Mirror the review
    # state into the observation evidence ledger so either module shows the same result.
    try:
        if is_approved:
            # The CAPA approval closes the linked observation's entire evidence batch.
            # Include legacy Draft/Pending labels so the register popup cannot keep
            # displaying an obsolete pending state after CAPA is closed.
            db.execute("""UPDATE observation_closeout_evidence
                SET review_status='Approved',reviewed_by=?,reviewed_at=?,review_comments=?
                WHERE observation_id=? AND lower(trim(COALESCE(review_status,''))) NOT IN
                ('deleted','void','cancelled')""",
                (approved_by, approved_at or today(), safe(capa_row["capa_closeout_comments"] if "capa_closeout_comments" in capa_row.keys() else "CAPA close-out approved"), obs["id"]))
        elif is_returned:
            db.execute("""UPDATE observation_closeout_evidence
                SET review_status='Rejected',reviewed_by=?,reviewed_at=?,review_comments=?
                WHERE observation_id=? AND lower(COALESCE(review_status,'')) IN
                ('pending review','submitted for review')""",
                (approved_by, approved_at, safe(capa_row["capa_closeout_comments"] if "capa_closeout_comments" in capa_row.keys() else ""), obs["id"]))
    except Exception:
        logging.exception("Unable to mirror CAPA close-out decision to observation evidence history")

    # The CAPA close-out approver's decision is authoritative for its linked observation.
    # The CAPA reviewer decision is authoritative. Once CAPA is approved,
    # the linked observation must close even when an older record has incomplete
    # or legacy action metadata that cannot be recalculated reliably.
    if is_approved:
        new_status = "Closed"
    elif is_returned:
        new_status = "Close-out Evidence Returned"
    elif closeout_key in ("submitted for review", "pending review"):
        new_status = "Pending Verification"
    elif total == 0 or pct < 100:
        new_status = f"CAPA In Progress ({pct}% complete / {100-pct}% open)"
    else:
        new_status = "Awaiting CAPA Close-out Submission"

    comments = safe(obs["closeout_comments"] if "closeout_comments" in obs.keys() else "")
    note = f"CAPA {capa_no}: {done}/{total} actions evidenced; {pct}% complete; close-out approval: {closeout_status or 'Not Submitted'}"
    lines = [line for line in comments.splitlines() if not line.startswith(f"CAPA {capa_no}:")]
    lines.append(note)
    comments = "\n".join(line for line in lines if line.strip())

    if new_status == "Closed":
        closed_date = approved_at[:10] if approved_at else today()
        db.execute(
            """UPDATE observations SET capa_required=1,capa_number=?,status='Closed',
               closeout_date=COALESCE(NULLIF(closeout_date,''),?),closed_by=?,verified_by=?,
               verification_date=?,verification='CAPA close-out approved in CAPA Tracking Register',
               closeout_comments=? WHERE id=?""",
            (capa_no, closed_date, approved_by, approved_by, closed_date, comments, obs["id"])
        )
    else:
        db.execute(
            """UPDATE observations SET capa_required=1,capa_number=?,status=?,verification=?,
               closeout_comments=? WHERE id=?""",
            (capa_no, new_status, new_status, comments, obs["id"])
        )
    try:
        db.execute("UPDATE capa SET completion_pct=?,action_status=? WHERE id=?", (pct, action_status, capa_row["id"]))
        if new_status == "Closed":
            db.execute("UPDATE capa SET status='Closed' WHERE id=?", (capa_row["id"],))
    except Exception:
        logging.exception("Unable to persist CAPA progress for %s", capa_no)


def ensure_observation_capa_record(obs_row):
    """Return the CAPA record belonging to this observation without cross-linking records."""
    if not obs_row or not int(obs_row["capa_required"] or 0):
        return safe(obs_row["capa_number"]) if obs_row else ""
    obs_id = int(obs_row["id"])
    obs_no = safe(obs_row["number"]).strip()
    capa_no = safe(obs_row["capa_number"]).strip()

    linked = db.fetchone("SELECT * FROM capa WHERE linked_observation_id=? ORDER BY id DESC LIMIT 1", (obs_id,))
    if not linked and obs_no:
        linked = db.fetchone(
            "SELECT * FROM capa WHERE reference_number=? AND lower(COALESCE(source,'')) IN ('hse inspection','observation','hse observation') ORDER BY id DESC LIMIT 1",
            (obs_no,)
        )
    if not linked and capa_no:
        candidate = db.fetchone("SELECT * FROM capa WHERE number=?", (capa_no,))
        if candidate:
            owner = candidate["linked_observation_id"] if "linked_observation_id" in candidate.keys() else None
            if not owner or int(owner) == obs_id:
                linked = candidate
    if linked:
        actual_no = safe(linked["number"])
        db.execute("UPDATE capa SET linked_observation_id=?,reference_number=?,source='HSE Inspection' WHERE id=?",
                   (obs_id, obs_no, linked["id"]))
        if actual_no != capa_no:
            db.execute("UPDATE observations SET capa_number=? WHERE id=?", (actual_no, obs_id))
        return actual_no

    actions = parse_corrective_actions(obs_row)
    action_items = [{"action": a, "evidence": [], "has_evidence": False} for a in actions]
    corrective = format_corrective_actions_display(actions) if actions else "Corrective action to be defined"
    finding = f"Observation {obs_no}\n{safe(obs_row['observation'])}"
    new_no = next_number("HSE-CAPA", "capa")
    db.execute("""INSERT INTO capa(number,source,reference_number,finding,root_cause,corrective_action,preventive_action,responsible,priority,target_date,status,verification,closeout_evidence,created_at,actions_json,approval_status,approved_by,approved_date,completion_pct,action_status,observation_text,linked_observation_id)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (new_no,"HSE Inspection",obs_no,finding,"",corrective,"",safe(obs_row["responsible"]),safe(obs_row["priority"]),safe(obs_row["target_date"]),"Open","","",datetime.now().isoformat(),json.dumps(action_items,ensure_ascii=False),"Pending Approval","","",0,"Open",safe(obs_row["observation"]),obs_id))
    db.execute("UPDATE observations SET capa_number=? WHERE id=?", (new_no, obs_id))
    return new_no


def open_capa_action_evidence_dialog(parent, capa_id, on_saved=None):
    """Single shared evidence workspace for CAPA and its linked observation."""
    row = db.fetchone("SELECT * FROM capa WHERE id=?", (capa_id,))
    if not row:
        QMessageBox.warning(parent, "CAPA Evidence", "The linked CAPA record could not be found.")
        return
    if safe(row["approval_status"] if "approval_status" in row.keys() else "").strip().casefold() in ("approved", "capa approved") or safe(row["capa_closeout_status"] if "capa_closeout_status" in row.keys() else "").strip().casefold() == "approved":
        QMessageBox.information(parent, "CAPA Closed", "This CAPA has already been approved. Its evidence and approval history are read-only.")
        return

    actions = parse_capa_actions(row["actions_json"] if "actions_json" in row.keys() else row["corrective_action"])
    if not actions:
        actions = [{"action": a, "evidence": [], "has_evidence": False} for a in parse_corrective_actions(row["corrective_action"])]
    if not actions:
        QMessageBox.information(parent, "CAPA Evidence", "No corrective actions are listed for this CAPA.")
        return

    dialog = QDialog(parent)
    dialog.setWindowTitle(f"Corrective Action Evidence — {safe(row['number'])}")
    dialog.resize(980, 620)
    fit_dialog_to_desktop(dialog, 0.92, 0.88)
    outer = QVBoxLayout(dialog)
    heading = QLabel(
        f"CAPA: {safe(row['number'])}    |    Observation: {safe(row['reference_number']) or 'Not linked'}\n"
        "Attach evidence against each corrective action. Each action counts as complete when it has at least one readable attachment."
    )
    heading.setWordWrap(True)
    heading.setStyleSheet("font-weight:600;color:#17365D;padding:6px;")
    outer.addWidget(heading)
    progress_label = QLabel()
    progress_label.setStyleSheet("font-weight:700;color:#17365D;padding:7px;background:#E8F1FB;border:1px solid #B7C9D6;border-radius:4px;")
    outer.addWidget(progress_label)
    submitter = QLineEdit(safe(db.setting("current_user", "") or db.setting("username", "")))
    submitter.setPlaceholderText("Submitted by (name / ID)")
    outer.addWidget(submitter)
    grid = QTableWidget(len(actions), 5)
    grid.setHorizontalHeaderLabels(["No.", "Corrective Action", "Evidence Files", "Progress", "Manage Evidence"])
    grid.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
    grid.horizontalHeader().setSectionResizeMode(2, QHeaderView.ResizeMode.Stretch)
    grid.horizontalHeader().setSectionResizeMode(4, QHeaderView.ResizeMode.ResizeToContents)
    grid.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
    grid.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
    grid.setAlternatingRowColors(True)
    outer.addWidget(grid, 1)
    new_files = []

    def progress():
        done, total, pct, _state = capa_actions_completion(actions)
        progress_label.setText(f"Evidence progress: {pct}%  |  {done} of {total} corrective actions complete  |  {total-done} remaining")
        return done, total, pct

    def refresh_grid():
        grid.setRowCount(len(actions))
        for i, action in enumerate(actions):
            evidence = [safe(fp) for fp in (action.get("evidence") or []) if safe(fp).strip()]
            valid = [fp for fp in evidence if resolve_attachment_path(fp)]
            action["has_evidence"] = bool(valid)
            grid.setItem(i, 0, QTableWidgetItem(str(i + 1)))
            grid.setItem(i, 1, QTableWidgetItem(action["action"]))
            grid.setItem(i, 2, QTableWidgetItem("\n".join(Path(fp.replace("\\", "/")).name for fp in valid) or "No evidence attached"))
            grid.setItem(i, 3, QTableWidgetItem(f"{len(valid)} file(s)"))
            cell = QWidget()
            row_layout = QHBoxLayout(cell)
            row_layout.setContentsMargins(2, 2, 2, 2)
            add_edit = QPushButton("Add / Edit")
            view = QPushButton("View")
            delete = QPushButton("Delete")
            for button in (add_edit, view, delete):
                button.setMinimumHeight(28)
            def add_files(index=i):
                existing = list(actions[index].get("evidence") or [])
                replace = False
                if existing:
                    choice = QMessageBox.question(
                        dialog, "Manage Action Evidence",
                        "Choose Yes to replace the existing files, No to add more, or Cancel to keep them.",
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No | QMessageBox.StandardButton.Cancel,
                        QMessageBox.StandardButton.No
                    )
                    if choice == QMessageBox.StandardButton.Cancel:
                        return
                    replace = choice == QMessageBox.StandardButton.Yes
                paths, _ = QFileDialog.getOpenFileNames(
                    dialog, "Attach Evidence to Corrective Action", "",
                    "Evidence Files (*.png *.jpg *.jpeg *.bmp *.gif *.webp *.tif *.tiff *.pdf *.doc *.docx *.xls *.xlsx *.txt *.mp4 *.avi *.mov);;All Files (*)"
                )
                if not paths:
                    return
                saved = []
                for source_name in paths:
                    source = Path(source_name)
                    if not source.is_file():
                        continue
                    dest = ATTACH_DIR / f"{safe(row['number'])}_A{index+1}_{source.name}"
                    counter = 1
                    while dest.exists():
                        dest = ATTACH_DIR / f"{safe(row['number'])}_A{index+1}_{counter}_{source.name}"
                        counter += 1
                    try:
                        shutil.copy2(source, dest)
                        saved.append(str(dest))
                        new_files.append(dest)
                    except Exception:
                        logging.exception("CAPA action evidence copy failed")
                if saved:
                    actions[index]["evidence"] = saved if replace else list(dict.fromkeys(existing + saved))
                    actions[index]["has_evidence"] = True
                    refresh_grid()
            def view_files(index=i):
                available = [fp for fp in (actions[index].get("evidence") or []) if resolve_attachment_path(fp)]
                if not available:
                    return QMessageBox.information(dialog, "Evidence", "No readable evidence is attached to this corrective action.")
                choice, ok = QInputDialog.getItem(dialog, "View Action Evidence", "Select a file to open:", [Path(fp).name for fp in available], 0, False)
                if ok and choice:
                    selected = next((fp for fp in available if Path(fp).name == choice), None)
                    if selected:
                        QDesktopServices.openUrl(QUrl.fromLocalFile(str(resolve_attachment_path(selected))))
            def delete_file(index=i):
                available = [fp for fp in (actions[index].get("evidence") or []) if safe(fp).strip()]
                if not available:
                    return QMessageBox.information(dialog, "Delete Evidence", "There is no evidence to delete.")
                choice, ok = QInputDialog.getItem(dialog, "Delete Action Evidence", "Select the file to remove:", [Path(fp).name for fp in available], 0, False)
                if not ok or not choice:
                    return
                selected = next((fp for fp in available if Path(fp).name == choice), None)
                if selected:
                    actions[index]["evidence"] = [fp for fp in available if fp != selected]
                    actions[index]["has_evidence"] = bool(actions[index]["evidence"])
                    refresh_grid()
            add_edit.clicked.connect(add_files)
            view.clicked.connect(view_files)
            delete.clicked.connect(delete_file)
            row_layout.addWidget(add_edit)
            row_layout.addWidget(view)
            row_layout.addWidget(delete)
            grid.setCellWidget(i, 4, cell)
            grid.setRowHeight(i, 58)
        progress()

    def persist(submit=False):
        done, total, pct = progress()
        if submit and (total == 0 or pct < 100):
            QMessageBox.warning(dialog, "Evidence Incomplete", f"Attach evidence to every corrective action before submitting.\n\nProgress: {pct}% ({done}/{total}).")
            return False
        if submit and not submitter.text().strip():
            QMessageBox.warning(dialog, "Submitter Required", "Enter the name / ID of the person submitting the evidence.")
            return False
        now = datetime.now().isoformat(timespec="seconds")
        action_paths = {safe(fp) for item in actions for fp in (item.get("evidence") or []) if safe(fp).strip()}
        try:
            with db.conn:
                db.conn.execute("""UPDATE capa SET actions_json=?,completion_pct=?,action_status=?,corrective_action=?,
                    status=?,approval_status=?,approved_by='',approved_date='',verification=?,
                    capa_closeout_status=?,capa_closeout_submitted_by=?,capa_closeout_submitted_at=?,
                    capa_closeout_approved_by='',capa_closeout_approved_at='',capa_closeout_comments='',
                    observation_closeout_status=? WHERE id=?""",
                    (json.dumps(actions, ensure_ascii=False), pct,
                     "CAPA Action Complete" if pct == 100 else ("Pending" if pct else "Open"),
                     format_corrective_actions_display([a["action"] for a in actions]),
                     "Awaiting Approval" if submit else ("In Progress" if pct else "Open"),
                     "Pending Approval" if submit else "Draft",
                     f"Manager action evidence {'submitted for approval' if submit else 'saved'} by {submitter.text().strip()} on {now}",
                     "Submitted for Review" if submit else "Draft",
                     submitter.text().strip() if submit else "", now if submit else "",
                     "Submitted for Review" if submit else "Draft", capa_id))
                # Keep the attachment register in step with the action-level list.
                existing_rows = db.conn.execute("SELECT id,file_path FROM capa_attachments WHERE capa_id=? AND lower(COALESCE(attachment_type,'')) LIKE 'action % evidence'", (capa_id,)).fetchall()
                existing_map = {safe(x["file_path"]): int(x["id"]) for x in existing_rows}
                for old_path, old_id in existing_map.items():
                    if old_path not in action_paths:
                        db.conn.execute("DELETE FROM capa_attachments WHERE id=?", (old_id,))
                for item in actions:
                    for fp in item.get("evidence") or []:
                        if safe(fp) and safe(fp) not in existing_map:
                            db.conn.execute("INSERT INTO capa_attachments(capa_id,file_path,attachment_type) VALUES(?,?,?)", (capa_id, safe(fp), f"Action {actions.index(item)+1} Evidence"))
            updated = db.fetchone("SELECT * FROM capa WHERE id=?", (capa_id,))
            if updated:
                sync_observation_from_capa(updated)
            if on_saved:
                try:
                    on_saved()
                except Exception:
                    logging.exception("CAPA evidence refresh callback failed")
            return True
        except Exception as exc:
            logging.exception("CAPA action evidence save failed")
            QMessageBox.critical(dialog, "Save Failed", str(exc))
            return False

    refresh_grid()
    buttons = QHBoxLayout()
    save_exit = QPushButton("Save & Exit")
    submit_button = QPushButton("Submit for Approval")
    cancel_button = QPushButton("Cancel")
    for button in (save_exit, submit_button, cancel_button):
        button.setMinimumHeight(38)
    buttons.addWidget(save_exit)
    buttons.addWidget(submit_button)
    buttons.addStretch(1)
    buttons.addWidget(cancel_button)
    outer.addLayout(buttons)
    save_exit.clicked.connect(lambda: (persist(False) and dialog.accept()))
    submit_button.clicked.connect(lambda: (persist(True) and dialog.accept()))
    def cancel_dialog():
        for fp in new_files:
            try:
                if fp.exists(): fp.unlink()
            except Exception:
                logging.exception("Unable to clean up unsaved CAPA evidence file")
        dialog.reject()
    cancel_button.clicked.connect(cancel_dialog)
    dialog.exec()


