    # --------------------------------------------------------

    def build_ui(self):

        central = QWidget()
        self.setCentralWidget(central)

        layout = QHBoxLayout(central)
        layout.setContentsMargins(0, 0, 0, 0)

        self.nav = QListWidget()

        modules = [
            "Dashboard",
            "HSE Inspection Register",
            "Incident Investigation",
            "Audit Register",
            "CAPA Tracking Register",
            "Permit to Work (PTW)",
            "Training",
            "Manpower Details",
            "Chemical & SDS Register",
            "Reports",
            "Master Data",
            "Settings"
        ]

        self.nav.addItems(modules)
        self.nav.setFixedWidth(245)
        self.nav.currentRowChanged.connect(
            self.navigation_changed
        )

        layout.addWidget(self.nav)

        self.stack = QStackedWidget()
        layout.addWidget(self.stack, 1)

    # --------------------------------------------------------

    def navigation_changed(self, row):
        # Cache each module page so switching is instant and stack widgets do not pile up.
        # Dashboard (row 0) is always rebuilt so KPIs and trends stay live after data changes.
        if not hasattr(self, "_module_cache"):
            self._module_cache = {}

        if row == 0:
            # Drop previous dashboard widget from stack to prevent overlap / stale zeros.
            old = self._module_cache.pop(0, None)
            if old is not None:
                try:
                    idx = self.stack.indexOf(old)
                    if idx >= 0:
                        self.stack.removeWidget(old)
                    old.deleteLater()
                except Exception:
                    logging.exception("Unable to clear previous dashboard page")
            try:
                self.dashboard()
                self._module_cache[0] = self.stack.currentWidget()
            except Exception as exc:
                logging.exception("Navigation failed for Dashboard")
                try:
                    QMessageBox.critical(self, "Module Error", f"Unable to open Dashboard.\n\n{exc}")
                except Exception:
                    pass
            return

        cached = self._module_cache.get(row)
        if cached is not None:
            try:
                self.stack.setCurrentWidget(cached)
                return
            except Exception:
                self._module_cache.pop(row, None)

        try:
            if row == 1:
                self.observations()
            elif row == 2:
                self.incidents()
            elif row == 3:
                self.audits()
            elif row == 4:
                self.capa()
            elif row == 5:
                w, layout = self.page("Permit to Work Management")
                layout.addWidget(PTWModule(self, db), 1)
            elif row == 6:
                self.training()
            elif row == 7:
                self.manpower_details()
            elif row == 8:
                w, layout = self.page("Chemical Register & SDS Management")
                layout.addWidget(ChemicalSDSModule(self, db), 1)
            elif row == 9:
                self.reports()
            elif row == 10:
                self.master_data()
            elif row == 11:
                self.settings_page()
            self._module_cache[row] = self.stack.currentWidget()
        except Exception as exc:
            logging.exception("Navigation failed for row %s", row)
            try:
                QMessageBox.critical(self, "Module Error", f"Unable to open this module.\n\n{exc}")
            except Exception:
                pass

    def page(self, title):

        w = QWidget()
        layout = QVBoxLayout(w)

        title_label = QLabel(title)
        title_label.setStyleSheet("""
            font-size: 24px;
            font-weight: bold;
            color: #17365D;
            padding: 8px;
        """)

        layout.addWidget(title_label)

        self.stack.addWidget(w)
        self.stack.setCurrentWidget(w)

        return w, layout

    # ========================================================
    # DASHBOARD
    # ========================================================



    def selected_id(self, table, title="Record"):
        """Return the integer primary key from column 0 of the selected table row."""
        try:
            row = table.currentRow()
        except Exception:
            row = -1
        if row < 0 or not table.item(row, 0):
            QMessageBox.information(self, title, "Select a row first.")
            return None
        item = table.item(row, 0)
        # Prefer UserRole if set, otherwise plain text
        try:
            data = item.data(Qt.ItemDataRole.UserRole)
            if data is not None:
                return int(data)
        except Exception:
            pass
        try:
            return int(item.text())
        except Exception:
            QMessageBox.warning(self, title, "Could not read the selected record id.")
            return None

    def delete_selected_record(self, table, table_name, attachment_table, label, refresh_cb=None):
        rid = self.selected_id(table, f"Delete {label}")
        if rid is None:
            return
        ans = QMessageBox.question(
            self, f"Delete {label}",
            f"Delete the selected {label.lower()} and its attachments? This cannot be undone.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        if ans != QMessageBox.StandardButton.Yes:
            return
        try:
            if attachment_table:
                col = {
                    "observation_attachments": "observation_id",
                    "incident_attachments": "incident_id",
                    "audit_attachments": "audit_id",
                    "capa_attachments": "capa_id",
                }.get(attachment_table)
                if col:
                    db.execute(f"DELETE FROM {attachment_table} WHERE {col}=?", (rid,))
            db.execute(f"DELETE FROM {table_name} WHERE id=?", (rid,))
            if callable(refresh_cb):
                refresh_cb()
            QMessageBox.information(self, "Deleted", f"{label} deleted.")
        except Exception as exc:
            logging.exception("Delete failed")
            QMessageBox.critical(self, "Delete Failed", str(exc))

    def show_export_success(self, path):
        """Shared success dialog used by STOP Card and other module exports."""
        QMessageBox.information(
            self,
            "Export Successful",
            f"File saved successfully:\n{path}"
        )


    @staticmethod
    def table_data_static(table_name, record_ids=None):
        """Return (columns, rows) for register exports. Observations use dedicated export fields."""
        if table_name == "observations":
            columns, data, _rows = observation_export_rows(record_ids)
            return columns, data
        column_map = {
            "incidents": [
                ("Number", "number"), ("Date", "incident_date"), ("Time", "incident_time"),
                ("Type", "incident_type"), ("Location", "location"), ("Project", "project"),
                ("Company", "company"), ("Department", "department"), ("Method", "investigation_method"),
                ("Status", "status"), ("Person Involved", "person_involved"),
                ("Description", "description"), ("Root Cause", "root_cause"),
                ("Corrective Action", "corrective_action"), ("CAPA No.", "capa_number"),
            ],
            "capa": [
                ("Number", "number"), ("Source", "source"), ("Reference", "reference_number"),
                ("Finding", "finding"), ("Root Cause", "root_cause"),
                ("Corrective Action", "corrective_action"), ("Preventive Action", "preventive_action"),
                ("Responsible", "responsible"), ("Priority", "priority"),
                ("Target Date", "target_date"), ("Status", "status"), ("Verification", "verification"),
            ],
            "audits": [
                ("Number", "number"), ("Date", "audit_date"), ("Type", "audit_type"),
                ("Standard", "standard"), ("Project", "project"), ("Location", "location"),
                ("Auditor", "auditor"), ("Status", "status"),
            ],
        }
        fields = column_map.get(table_name)
        if not fields:
            return [], []
        params = []
        where = ""
        if record_ids:
            placeholders = ",".join("?" for _ in record_ids)
            where = f" WHERE id IN ({placeholders})"
            params = list(record_ids)
        rows = db.fetchall(f"SELECT * FROM {table_name}{where} ORDER BY id DESC", params)
        columns = [c[0] for c in fields]
        data = []
        for row in rows:
            values = []
            for _, key in fields:
                try:
                    values.append(xml_safe(row[key] if key in row.keys() else ""))
                except Exception:
                    values.append("")
            data.append(values)
        return columns, data

    def export_csv(self, table_name):
        columns, data = self.table_data_static(table_name)
        if not columns:
            return QMessageBox.information(self, "Export", "No data to export.")
        path, _ = QFileDialog.getSaveFileName(self, f"Export {table_name} CSV", f"{table_name}.csv", "CSV Files (*.csv)")
        if not path:
            return
        if not path.lower().endswith(".csv"):
            path += ".csv"
        try:
            with open(path, "w", encoding="utf-8-sig", newline="") as f:
                writer = csv.writer(f)
                writer.writerow(columns)
                writer.writerows(data)
            self.show_export_success(path)
        except Exception as exc:
            logging.exception("CSV export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))

    def export_excel(self, table_name):
        columns, data = self.table_data_static(table_name)
        if not columns:
            return QMessageBox.information(self, "Export", "No data to export.")
        path, _ = QFileDialog.getSaveFileName(self, f"Export {table_name} Excel", f"{table_name}.xlsx", "Excel Workbook (*.xlsx)")
        if not path:
            return
        if not path.lower().endswith(".xlsx"):
            path += ".xlsx"
        try:
            wb = Workbook()
            ws = wb.active
            ws.title = table_name[:31]
            title = table_name.replace("_", " ").title() + " Register"
            ws.append([title])
            ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max(1, len(columns)))
            ws["A1"].font = Font(name="Arial", size=14, bold=True, color="FFFFFF")
            ws["A1"].fill = PatternFill("solid", fgColor="17365D")
            ws["A1"].alignment = Alignment(horizontal="center", vertical="center")
            ws.row_dimensions[1].height = 24
            ws.append(columns)
            headfill = PatternFill("solid", fgColor="D9EAF7")
            for cell in ws[2]:
                cell.font = Font(bold=True, color="17365D")
                cell.fill = headfill
                cell.alignment = Alignment(horizontal="center", wrap_text=True)
            for row in data:
                ws.append(list(row))
            for col in ws.columns:
                from openpyxl.utils import get_column_letter
                letter = get_column_letter(col[0].column)
                longest = max((len(str(c.value or "")) for c in col), default=10)
                ws.column_dimensions[letter].width = min(max(longest + 2, 12), 40)
            ws.freeze_panes = "A3"
            if table_name == "observations":
                _obs_rows = db.fetchall("SELECT * FROM observations ORDER BY id DESC")
                add_observation_images_to_workbook(wb, _obs_rows)
            wb.save(path)
            self.show_export_success(path)
        except Exception as exc:
            logging.exception("Excel export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))

    def export_docx(self, table_name):
        path, _ = QFileDialog.getSaveFileName(
            self, f"Export {table_name} Word", f"{table_name}.docx", "Word Documents (*.docx)"
        )
        if not path:
            return
        if not path.lower().endswith(".docx"):
            path += ".docx"
        try:
            generate_table_docx(table_name, path)
            if not Path(path).exists() or Path(path).stat().st_size < 500:
                raise ValueError("The Word report was not created correctly.")
            self.show_export_success(path)
        except Exception as exc:
            logging.exception("Word export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))

    def export_pdf(self, table_name):
        """PDF export via ReportLab simple table for register data."""
        columns, data = self.table_data_static(table_name)
        if not columns:
            return QMessageBox.information(self, "Export", "No data to export.")
        path, _ = QFileDialog.getSaveFileName(self, f"Export {table_name} PDF", f"{table_name}.pdf", "PDF Files (*.pdf)")
        if not path:
            return
        if not path.lower().endswith(".pdf"):
            path += ".pdf"
        try:
            doc = SimpleDocTemplate(path, pagesize=landscape(A4), leftMargin=24, rightMargin=24, topMargin=28, bottomMargin=28)
            styles = getSampleStyleSheet()
            story = [
                Paragraph(xml_safe(f"{table_name.replace('_',' ').title()} Register — {company_name()}"), styles["Title"]),
                Paragraph(xml_safe(f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M')}"), styles["Normal"]),
                Spacer(1, 10),
            ]
            # Export the complete register.  Use equal-width columns so every field
            # is retained; long values wrap within cells instead of being truncated.
            use_cols = list(columns)
            table_data = [use_cols]
            for row in data:
                table_data.append([xml_safe(row[i] if i < len(row) else "") for i in range(len(use_cols))])
            available_width = landscape(A4)[0] - doc.leftMargin - doc.rightMargin
            col_width = available_width / max(len(use_cols), 1)
            t = Table(table_data, colWidths=[col_width] * len(use_cols), repeatRows=1, splitByRow=1)
            t.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#17365D")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("FONTSIZE", (0, 0), (-1, -1), 7),
                ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#B7C9D6")),
                ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F5F9FC")]),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ]))
            story.append(t)
            if table_name == "observations":
                _obs_rows = db.fetchall("SELECT * FROM observations ORDER BY id DESC")
                add_observation_images_to_pdf_story(story, _obs_rows, available_width)
            doc.build(story)
            self.show_export_success(path)
        except Exception as exc:
            logging.exception("PDF export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))


