        # Audit trail for authorized deletion of CAPA-linked observations.
        db.conn.execute("""CREATE TABLE IF NOT EXISTS observation_deletion_approvals (
            id INTEGER PRIMARY KEY AUTOINCREMENT, observation_number TEXT NOT NULL,
            capa_number TEXT DEFAULT '', requested_by TEXT DEFAULT '', approver_name TEXT NOT NULL,
            approver_role TEXT NOT NULL, reason TEXT NOT NULL, approved_at TEXT NOT NULL,
            deleted_observation_id INTEGER, decision TEXT DEFAULT 'Approved')""")
        db.conn.commit()

        def resolve_open_observation_id(row_index):
            """Resolve a visible Open Observations row using its unique observation number first."""
            if row_index is None or row_index < 0 or row_index >= open_table.rowCount():
                return None
            number_item = open_table.item(row_index, 1)
            if number_item:
                number = number_item.text().strip()
                if number:
                    found = db.fetchone("SELECT id FROM observations WHERE number=? ORDER BY id DESC LIMIT 1", (number,))
                    if found:
                        return int(found["id"])
            id_item = open_table.item(row_index, 0)
            if id_item:
                for candidate in (id_item.data(Qt.ItemDataRole.UserRole), id_item.text()):
                    try:
                        oid = int(candidate)
                    except (TypeError, ValueError):
                        continue
                    found = db.fetchone("SELECT id FROM observations WHERE id=?", (oid,))
                    if found:
                        return int(found["id"])
            return None

        def selected_open_row_index():
            row = open_table.currentRow()
            if row >= 0:
                return row
            selection = open_table.selectionModel()
            selected = selection.selectedRows() if selection else []
            if selected:
                return selected[0].row()
            selected_items = open_table.selectedItems()
            return selected_items[0].row() if selected_items else -1

        def selected_open_observation_id():
            row = selected_open_row_index()
            if row < 0:
                QMessageBox.warning(self, "Open Observations", "Select an open observation first.")
                return None
            oid = resolve_open_observation_id(row)
            if oid is None:
                number_item = open_table.item(row, 1)
                shown = number_item.text().strip() if number_item else f"row {row + 1}"
                QMessageBox.warning(self, "Open Observations", f"Observation {shown} is no longer in the register. Refresh the list and select it again.")
            return oid

        def open_simple_observation_evidence_dialog(oid):
            obs = db.fetchone("SELECT * FROM observations WHERE id=?", (oid,))
            if not obs:
                return QMessageBox.warning(self, "Observation", f"Observation ID {oid} could not be found. Refresh the register and try again.")
            dialog = QDialog(self)
            dialog.setWindowTitle(f"Observation Close-out Evidence — {safe(obs['number'])}")
            dialog.resize(820, 560)
            fit_dialog_to_desktop(dialog, 0.90, 0.86)
            outer = QVBoxLayout(dialog)
            title = QLabel(f"<b>{safe(obs['number'])}</b> — {safe(obs['observation'])}")
            title.setWordWrap(True)
            outer.addWidget(title)
            action_text = format_corrective_actions_display(obs)
            action_label = QLabel("Corrective action(s):\n" + (action_text or "No corrective action recorded"))
            action_label.setWordWrap(True)
            outer.addWidget(action_label)
            submitter_box = QLineEdit(safe(db.setting("current_user", "") or db.setting("username", "")))
            submitter_box.setPlaceholderText("Submitted by (name / ID)")
            outer.addWidget(submitter_box)
            evidence_table = QTableWidget(0, 4)
            evidence_table.setHorizontalHeaderLabels(["ID", "Evidence File", "Added / Submitted", "Status"])
            evidence_table.setColumnHidden(0, True)
            evidence_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            evidence_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            evidence_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            outer.addWidget(evidence_table, 1)

            def refresh_files():
                rows = db.fetchall("SELECT * FROM observation_closeout_evidence WHERE observation_id=? ORDER BY id DESC", (oid,))
                evidence_table.setRowCount(len(rows))
                for i, ev in enumerate(rows):
                    evidence_table.setItem(i, 0, QTableWidgetItem(str(ev["id"])))
                    evidence_table.setItem(i, 1, QTableWidgetItem(Path(safe(ev["file_path"]).replace('\\','/')).name))
                    evidence_table.setItem(i, 2, QTableWidgetItem(safe(ev["submitted_at"])))
                    evidence_table.setItem(i, 3, QTableWidgetItem(safe(ev["review_status"]) or "Draft"))

            def add_files():
                paths, _ = QFileDialog.getOpenFileNames(dialog, "Attach Close-out Evidence", "", "Evidence Files (*.png *.jpg *.jpeg *.bmp *.gif *.webp *.pdf *.doc *.docx *.xls *.xlsx *.txt *.mp4 *.avi *.mov);;All Files (*)")
                if not paths:
                    return
                batch = f"OBS-CO-{oid}-{datetime.now().strftime('%Y%m%d%H%M%S%f')}"
                now = datetime.now().isoformat(timespec="seconds")
                saved = []
                try:
                    with db.conn:
                        for src in paths:
                            source = Path(src)
                            if not source.is_file():
                                continue
                            dest = ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{source.name}"
                            n = 1
                            while dest.exists():
                                dest = ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{n}_{source.name}"
                                n += 1
                            shutil.copy2(source, dest)
                            saved.append(dest)
                            db.conn.execute("INSERT INTO observation_closeout_evidence(batch_id,observation_id,file_path,submitted_by,submitted_at,review_status) VALUES(?,?,?,?,?,'Draft')", (batch, oid, str(dest), submitter_box.text().strip(), now))
                            db.conn.execute("INSERT INTO observation_attachments(observation_id,file_path,attachment_type) VALUES(?,?,?)", (oid, str(dest), "Close-out Evidence"))
                    if not saved:
                        raise ValueError("No valid evidence files were selected.")
                    refresh_files()
                except Exception as exc:
                    logging.exception("Simple observation evidence upload failed")
                    QMessageBox.critical(dialog, "Evidence Upload", str(exc))

            def delete_file():
                r = evidence_table.currentRow()
                if r < 0 or not evidence_table.item(r, 0):
                    return QMessageBox.warning(dialog, "Delete Evidence", "Select an evidence file first.")
                evidence_id = int(evidence_table.item(r, 0).text())
                ev = db.fetchone("SELECT * FROM observation_closeout_evidence WHERE id=? AND observation_id=?", (evidence_id, oid))
                if not ev:
                    return QMessageBox.warning(dialog, "Delete Evidence", "The selected evidence record could not be found.")
                if safe(ev["review_status"]).casefold() not in ("draft", "rejected", "returned", "close-out evidence returned"):
                    return QMessageBox.warning(dialog, "Evidence Locked", "Submitted evidence cannot be deleted while it is under review or after approval.")
                fp = safe(ev["file_path"])
                with db.conn:
                    db.conn.execute("DELETE FROM observation_closeout_evidence WHERE id=?", (evidence_id,))
                    db.conn.execute("DELETE FROM observation_attachments WHERE observation_id=? AND file_path=? AND attachment_type='Close-out Evidence'", (oid, fp))
                if fp:
                    try: Path(fp).unlink(missing_ok=True)
                    except Exception: logging.exception("Unable to remove observation close-out file")
                refresh_files()

            def view_file():
                r = evidence_table.currentRow()
                if r < 0 or not evidence_table.item(r, 0):
                    return QMessageBox.warning(dialog, "View Evidence", "Select an evidence file first.")
                ev = db.fetchone("SELECT file_path FROM observation_closeout_evidence WHERE id=?", (int(evidence_table.item(r, 0).text()),))
                path = resolve_attachment_path(safe(ev["file_path"])) if ev else None
                if not path:
                    return QMessageBox.warning(dialog, "View Evidence", "The evidence file could not be found on disk.")
                QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

            def submit_files():
                if not submitter_box.text().strip():
                    return QMessageBox.warning(dialog, "Submitter Required", "Enter the name / ID of the person submitting the evidence.")
                drafts = db.fetchall("SELECT DISTINCT batch_id FROM observation_closeout_evidence WHERE observation_id=? AND lower(COALESCE(review_status,''))='draft'", (oid,))
                if not drafts:
                    return QMessageBox.warning(dialog, "No Draft Evidence", "Attach at least one evidence file before submitting.")
                now = datetime.now().isoformat(timespec="seconds")
                with db.conn:
                    for item in drafts:
                        db.conn.execute("UPDATE observation_closeout_evidence SET review_status='Pending Review',submitted_by=?,submitted_at=? WHERE observation_id=? AND batch_id=? AND lower(COALESCE(review_status,''))='draft'", (submitter_box.text().strip(), now, oid, safe(item["batch_id"])))
                    # A simple observation moves to verification, never to Cancelled on submission.
                    db.conn.execute("UPDATE observations SET status='Pending Verification',verification='Close-out evidence submitted for review' WHERE id=? AND lower(COALESCE(status,'')) NOT IN ('closed')", (oid,))
                refresh_files()
                refresh_closeout_open(); refresh_closeout_evidence(); load()
                QMessageBox.information(dialog, "Submitted", "Evidence submitted for review. The observation status is Pending Verification.")
                dialog.accept()

            controls = QHBoxLayout()
            add_btn = QPushButton("Attach Evidence")
            view_btn = QPushButton("View")
            delete_btn = QPushButton("Delete")
            save_btn = QPushButton("Save & Exit")
            submit_btn = QPushButton("Submit for Approval")
            close_btn = QPushButton("Close")
            for b in (add_btn, view_btn, delete_btn, save_btn, submit_btn, close_btn):
                b.setMinimumHeight(34)
            for b in (add_btn, view_btn, delete_btn): controls.addWidget(b)
            controls.addStretch(1)
            controls.addWidget(save_btn); controls.addWidget(submit_btn); controls.addWidget(close_btn)
            outer.addLayout(controls)
            add_btn.clicked.connect(add_files)
            view_btn.clicked.connect(view_file)
            delete_btn.clicked.connect(delete_file)
            save_btn.clicked.connect(lambda: (refresh_closeout_open(), refresh_closeout_evidence(), load(), dialog.accept()))
            submit_btn.clicked.connect(submit_files)
            close_btn.clicked.connect(dialog.reject)
            refresh_files()
            dialog.exec()

        def edit_open_observation():
            oid = selected_open_observation_id()
            if oid is not None:
                self.observation_form(refresh_both_closeout_sections, oid)

        def open_observation_action_evidence(oid=None):
            if oid is None:
                oid = selected_open_observation_id()
            if oid is None:
                return
            obs = db.fetchone("SELECT * FROM observations WHERE id=?", (oid,))
            if not obs:
                return QMessageBox.warning(self, "Observation", "The selected observation could not be found.")
            if safe(obs["status"]).casefold() == "closed":
                return QMessageBox.information(self, "Observation Closed", "This observation is genuinely Closed. Its evidence and approval history remain available in the registers.")
            if int(obs["capa_required"] or 0):
                capa_no = ensure_observation_capa_record(obs)
                capa_row = db.fetchone("SELECT * FROM capa WHERE number=?", (capa_no,)) if capa_no else None
                if not capa_row:
                    return QMessageBox.warning(self, "CAPA Link Missing", "The linked CAPA record could not be found. Refresh the CAPA Tracking Register and try again.")
                open_capa_action_evidence_dialog(self, capa_row["id"], on_saved=lambda: (refresh_both_closeout_sections(), load()))
            else:
                open_simple_observation_evidence_dialog(int(oid))

        def delete_open_observation():
            oid = selected_open_observation_id()
            if oid is None:
                return
            obs = db.fetchone("SELECT number FROM observations WHERE id=?", (oid,))
            if not obs:
                return
            if QMessageBox.question(self, "Delete Observation", f"Delete {safe(obs['number'])}? This also removes its linked observation evidence. The linked CAPA must be retained separately if already approved.", QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
                return
            linked = db.fetchone("SELECT id,capa_closeout_status FROM capa WHERE linked_observation_id=? OR reference_number=?", (oid, safe(obs["number"])))
            if linked:
                QMessageBox.information(self, "Use Register Approval", "CAPA-linked observations must be deleted through Observation Register → Delete Selected, where an authorized approver name, role and reason are recorded. The CAPA history will be retained.")
                return
            db.execute("UPDATE capa SET linked_observation_id=NULL WHERE linked_observation_id=?", (oid,))
            db.execute("DELETE FROM observation_closeout_evidence WHERE observation_id=?", (oid,))
            db.execute("DELETE FROM observation_attachments WHERE observation_id=?", (oid,))
            db.execute("DELETE FROM observations WHERE id=?", (oid,))
            refresh_both_closeout_sections()
            load()

        open_edit.clicked.connect(edit_open_observation)
        open_delete.clicked.connect(delete_open_observation)

        def open_selected_closeout_workspace(row_index, _column=0):
            oid = resolve_open_observation_id(row_index)
            if oid is None:
                return
            tabs.setCurrentWidget(close_page)
            # Both CAPA and non-CAPA observations open a dedicated evidence workspace.
            open_observation_action_evidence(oid)

        open_table.cellDoubleClicked.connect(open_selected_closeout_workspace)

        def open_register_observation_closeout(row_index, _column=0):
            try:
                _id_item = table.item(row_index, 0)
                _value = _id_item.data(Qt.ItemDataRole.UserRole) if _id_item else None
                oid = int(_value if _value is not None else _id_item.text()) if _id_item else None
                if oid is not None and not db.fetchone("SELECT id FROM observations WHERE id=?", (oid,)):
                    _number_item = table.item(row_index, 2)
                    _recovered = db.fetchone("SELECT id FROM observations WHERE number=?", (_number_item.text(),)) if _number_item else None
                    oid = int(_recovered["id"]) if _recovered else None
            except Exception:
                oid = None
            if oid is None:
                return
            _obs_for_route = db.fetchone("SELECT * FROM observations WHERE id=?", (oid,))
            if _obs_for_route and int(_obs_for_route["capa_required"] or 0):
                _capa_no = ensure_observation_capa_record(_obs_for_route)
                _capa_row = db.fetchone("SELECT * FROM capa WHERE number=?", (_capa_no,)) if _capa_no else None
                if _capa_row:
                    open_capa_action_evidence_dialog(self, _capa_row["id"], on_saved=lambda: (refresh_closeout_open(), refresh_closeout_evidence(), load()))
                else:
                    QMessageBox.warning(self, "CAPA Link Missing", "The linked CAPA record could not be found.")
                return
            # Non-CAPA observations open their own attachment / submit popup as well.
            open_simple_observation_evidence_dialog(int(oid))

        table.cellDoubleClicked.connect(open_register_observation_closeout)

        def refresh_closeout_open():
            # Reconcile every linked CAPA first, then display the same current status
            # and latest close-out decision in section A and section B.
            obs_rows = db.fetchall("SELECT * FROM observations ORDER BY id DESC")
            for obs_row in obs_rows:
                # Repair legacy records accidentally marked Cancelled despite having active close-out evidence.
                _active_evidence = db.fetchone("SELECT 1 FROM observation_closeout_evidence WHERE observation_id=? AND lower(COALESCE(review_status,'')) IN ('draft','pending review','submitted for review','rejected','returned') LIMIT 1", (obs_row["id"],))
                if safe(obs_row["status"]).casefold() == "cancelled" and _active_evidence:
                    db.execute("UPDATE observations SET status='Pending Verification',verification='Close-out evidence is active; status restored from erroneous Cancelled value' WHERE id=?", (obs_row["id"],))
                    obs_row = db.fetchone("SELECT * FROM observations WHERE id=?", (obs_row["id"],))
                if int(obs_row["capa_required"] or 0):
                    capa_no = ensure_observation_capa_record(obs_row)
                    capa_row = db.fetchone("SELECT * FROM capa WHERE number=?", (capa_no,)) if capa_no else None
                    if capa_row:
                        sync_observation_from_capa(capa_row)
                    else:
                        db.execute("UPDATE observations SET status='CAPA Link Missing',verification='CAPA Required is Yes but no linked CAPA record could be created' WHERE id=?", (obs_row["id"],))
                else:
                    latest = db.fetchone("SELECT review_status,reviewed_by,reviewed_at FROM observation_closeout_evidence WHERE observation_id=? ORDER BY id DESC LIMIT 1", (obs_row["id"],))
                    if latest and safe(latest["review_status"]).strip().casefold()=="approved" and safe(obs_row["status"]).casefold()!="closed":
                        db.execute("UPDATE observations SET status='Closed',closeout_date=COALESCE(NULLIF(closeout_date,''),?),closed_by=?,verified_by=?,verification_date=?,verification='Close-out Approved' WHERE id=?", (today(),safe(latest["reviewed_by"]),safe(latest["reviewed_by"]),safe(latest["reviewed_at"])[:10] or today(),obs_row["id"]))

            rows=db.fetchall("SELECT * FROM observations WHERE lower(COALESCE(status,'Open'))<>'closed' AND (lower(COALESCE(status,'Open'))<>'cancelled' OR EXISTS (SELECT 1 FROM observation_closeout_evidence ce WHERE ce.observation_id=observations.id AND lower(COALESCE(ce.review_status,'')) IN ('draft','pending review','submitted for review','rejected','returned'))) ORDER BY id DESC")
            open_table.setRowCount(len(rows))
            for i,r in enumerate(rows):
                latest = db.fetchone("SELECT review_status FROM observation_closeout_evidence WHERE observation_id=? ORDER BY id DESC LIMIT 1", (r["id"],))
                closeout_status = safe(latest["review_status"]) if latest else "Not Submitted"
                capa_row = db.fetchone("SELECT * FROM capa WHERE linked_observation_id=? ORDER BY id DESC LIMIT 1", (r["id"],))
                if not capa_row and safe(r["capa_number"]):
                    capa_row = db.fetchone("SELECT * FROM capa WHERE number=?", (safe(r["capa_number"]),))
                if capa_row:
                    _done,_total,_pct,_action_status = capa_actions_completion(capa_row["actions_json"] if "actions_json" in capa_row.keys() else capa_row["corrective_action"])
                    progress = f"{_pct}% complete / {100-_pct}% open"
                    closeout_status = safe(capa_row["approval_status"]) if safe(capa_row["approval_status"]).strip().casefold() in ("approved", "rejected", "not approved", "pending approval", "awaiting approval") else (safe(capa_row["capa_closeout_status"]) or closeout_status)
                else:
                    progress = "—"
                vals=[r["id"],r["number"],r["obs_date"],r["obs_type"],r["observation"],r["responsible"],r["status"],"Yes" if int(r["capa_required"] or 0) else "No",safe(r["capa_number"]) or "—",progress,closeout_status]
                for j,val in enumerate(vals):
                    _cell = QTableWidgetItem(safe(val))
                    _cell.setData(Qt.ItemDataRole.UserRole, int(r["id"]))
                    open_table.setItem(i,j,_cell)

        def refresh_closeout_evidence():
            """Show every submitted observation close-out, including CAPA submissions awaiting CAPA approval."""
            display_rows = []
            simple_rows = db.fetchall("""SELECT ce.*,o.number,o.capa_number,o.status AS observation_status,o.id AS obs_id
                FROM observation_closeout_evidence ce JOIN observations o ON o.id=ce.observation_id
                WHERE COALESCE(o.capa_required,0)=0
                AND lower(COALESCE(ce.review_status,'')) IN ('pending review','submitted for review','approved','rejected','returned')
                ORDER BY ce.id DESC""")
            for r in simple_rows:
                display_rows.append({"id":r["id"],"batch":safe(r["batch_id"]),"number":safe(r["number"]),
                    "capa":safe(r["capa_number"]),"file":safe(r["file_path"]),"submitted_by":safe(r["submitted_by"]),
                    "submitted_at":safe(r["submitted_at"]),"review":safe(r["review_status"]),"reviewed_by":safe(r["reviewed_by"]),
                    "obs_status":safe(r["observation_status"]),"capa_row":None,"comments":safe(r["review_comments"])} )

            capa_rows = db.fetchall("""SELECT c.*,o.id AS obs_id,o.number AS obs_number,o.status AS observation_status
                FROM capa c JOIN observations o ON (o.id=c.linked_observation_id OR (c.linked_observation_id IS NULL AND o.number=c.reference_number))
                WHERE COALESCE(o.capa_required,0)=1
                AND (lower(COALESCE(c.approval_status,'')) IN ('pending approval','awaiting approval')
                     OR lower(COALESCE(c.capa_closeout_status,'')) IN ('submitted for review','pending review'))
                ORDER BY c.id DESC""")
            for c in capa_rows:
                file_rows = db.fetchall("SELECT file_path FROM capa_attachments WHERE capa_id=? ORDER BY id", (c["id"],))
                names = [Path(safe(x["file_path"]).replace("\\", "/")).name for x in file_rows if safe(x["file_path"])]
                display_rows.append({"id":f"CAPA-{c['id']}","batch":safe(c["number"]),"number":safe(c["obs_number"]),
                    "capa":safe(c["number"]),"file":("CAPA action evidence: " + "; ".join(names)) if names else "CAPA action evidence attached",
                    "submitted_by":safe(c["capa_closeout_submitted_by"]),"submitted_at":safe(c["capa_closeout_submitted_at"]),
                    "review":safe(c["approval_status"]) or safe(c["capa_closeout_status"]) or "Pending Approval",
                    "reviewed_by":safe(c["approved_by"]),"obs_status":safe(c["observation_status"]),"capa_row":c,"comments":safe(c["capa_closeout_comments"])} )

            evidence_table.setRowCount(len(display_rows))
            for i,r in enumerate(display_rows):
                capa_row=r["capa_row"]
                if capa_row:
                    _done,_total,_pct,_action_status=capa_actions_completion(capa_row["actions_json"] if "actions_json" in capa_row.keys() else capa_row["corrective_action"])
                    progress=f"{_pct}% complete / {100-_pct}% open"
                    capa_label="Yes — CAPA approval"
                else:
                    capa_label="No" if not r["capa"] else "Yes"
                    progress="—"
                vals=[r["id"],r["batch"],r["number"],capa_label,r["file"],r["submitted_by"],r["submitted_at"],r["review"],r["reviewed_by"],r["obs_status"],progress]
                for j,val in enumerate(vals):
                    cell=QTableWidgetItem(safe(val))
                    if j==7:
                        cell.setToolTip(f"Review: {r['review']}\nReviewed by: {r['reviewed_by']}\nComments: {r['comments']}")
                    if j==4:
                        cell.setToolTip(r["file"])
                    evidence_table.setItem(i,j,cell)
                if "pending" in r["review"].casefold() or "awaiting" in r["review"].casefold():
                    evidence_table.item(i,7).setForeground(Qt.GlobalColor.darkBlue)
                elif r["review"].casefold() in ("rejected","returned"):
                    evidence_table.item(i,7).setForeground(Qt.GlobalColor.red)
                elif r["review"].casefold()=="approved":
                    evidence_table.item(i,7).setForeground(Qt.GlobalColor.darkGreen)

        def upload_closeout_evidence():
            indexes=open_table.selectionModel().selectedRows(0) if open_table.selectionModel() else []
            selected_rows={ix.row() for ix in indexes}
            if not selected_rows:
                selected_rows={ix.row() for ix in open_table.selectedItems()}
            if not selected_rows and open_table.currentRow() >= 0:
                selected_rows={open_table.currentRow()}
            ids=[]
            for row_index in sorted(selected_rows):
                resolved_id=resolve_open_observation_id(row_index)
                if resolved_id is not None and resolved_id not in ids:
                    ids.append(resolved_id)
            if not ids: return QMessageBox.warning(self,"Close-out Evidence","Select at least one open observation.")
            by=submitter.text().strip()
            if not by: return QMessageBox.warning(self,"Submitter Required","Enter the name / ID of the person submitting the evidence.")
            paths,_=QFileDialog.getOpenFileNames(self,"Select Close-out Evidence","","Evidence Files (*.png *.jpg *.jpeg *.bmp *.pdf *.doc *.docx *.xls *.xlsx *.txt *.mp4 *.avi *.mov);;All Files (*)")
            if not paths: return
            saved_paths=[]
            try:
                with db.conn:
                    for oid in ids:
                        obs=db.conn.execute("SELECT * FROM observations WHERE id=?",(oid,)).fetchone()
                        if not obs or safe(obs["status"]).lower() in ("closed","cancelled"): continue
                        if int(obs["capa_required"] or 0):
                            raise ValueError("This observation is CAPA-linked. Attach evidence once under Manager Action Evidence in CAPA Tracking, then submit and approve there.")
                        batch=f"OBS-CO-{oid}-{datetime.now().strftime('%Y%m%d%H%M%S%f')}"
                        for src_name in paths:
                            source=Path(src_name)
                            if not source.is_file(): continue
                            dest=ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{source.name}"
                            counter=1
                            while dest.exists(): dest=ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{counter}_{source.name}"; counter+=1
                            shutil.copy2(source,dest); saved_paths.append(dest)
                            now=datetime.now().isoformat(timespec="seconds")
                            db.conn.execute("INSERT INTO observation_closeout_evidence(batch_id,observation_id,file_path,submitted_by,submitted_at,review_status) VALUES(?,?,?,?,?,'Draft')",(batch,oid,str(dest),by,now))
                            db.conn.execute("INSERT INTO observation_attachments(observation_id,file_path,attachment_type) VALUES(?,?,?)",(oid,str(dest),"Close-out Evidence"))
                            capa_no=safe(obs["capa_number"])
                            if int(obs["capa_required"] or 0):
                                capa_no=ensure_observation_capa_record(obs)
                            if int(obs["capa_required"] or 0) and capa_no:
                                capa=db.conn.execute("SELECT id,closeout_evidence FROM capa WHERE number=?",(capa_no,)).fetchone()
                                if capa:
                                    db.conn.execute("INSERT INTO capa_attachments(capa_id,file_path,attachment_type) VALUES(?,?,?)",(capa["id"],str(dest),"Observation Close-out Evidence"))
                                    prior=safe(capa["closeout_evidence"])
                                    combined=(prior+";"+str(dest)).strip(";") if str(dest) not in prior.split(";") else prior
                                    db.conn.execute("UPDATE capa SET closeout_evidence=?,capa_closeout_status=CASE WHEN lower(COALESCE(capa_closeout_status,'')) IN ('approved','submitted for review','pending review') THEN capa_closeout_status ELSE 'Draft' END WHERE id=?",(combined,capa["id"]))
                        # Submission is a separate action; the evidence remains Draft until explicitly submitted.
                QMessageBox.information(self,"Evidence Attached","Close-out evidence has been attached as a draft. Select the observation and choose 'Submit Attached Evidence for Review' when ready.")
                refresh_closeout_open(); refresh_closeout_evidence(); load()
            except Exception as e:
                for fp in saved_paths:
                    try: fp.unlink(missing_ok=True)
                    except Exception: pass
                logging.exception("Observation close-out evidence upload failed")
                QMessageBox.critical(self,"Upload Error",str(e))

        def submit_attached_closeout_evidence():
            """Submit the selected observation's saved draft evidence to Observation Approval."""
            oid = selected_open_observation_id()
            if oid is None:
                return
            by = submitter.text().strip()
            if not by:
                return QMessageBox.warning(self, "Submitter Required", "Enter the name / ID of the person submitting the evidence.")
            obs = db.fetchone("SELECT * FROM observations WHERE id=?", (oid,))
            if not obs:
                return QMessageBox.warning(self, "Observation", "The selected observation is no longer available. Refresh the Open Observations list.")
            if safe(obs["status"]).casefold() == "closed":
                return QMessageBox.information(self, "Already Closed", "This observation is already closed.")
            try:
                if int(obs["capa_required"] or 0):
                    linked_no = ensure_observation_capa_record(obs)
                    linked_capa = db.fetchone("SELECT * FROM capa WHERE number=?", (linked_no,)) if linked_no else None
                    if not linked_capa:
                        raise ValueError(f"Observation {safe(obs['number'])} requires CAPA, but its linked CAPA record is missing. Refresh CAPA Tracking and try again.")
                    done, total, pct, action_state = capa_actions_completion(linked_capa["actions_json"] if "actions_json" in linked_capa.keys() else linked_capa["corrective_action"])
                    if total == 0 or pct < 100:
                        raise ValueError(f"Attach evidence to every corrective action before submission. Progress: {pct}% ({done}/{total}).")
                    now = datetime.now().isoformat(timespec="seconds")
                    with db.conn:
                        db.conn.execute("""UPDATE capa SET completion_pct=?,action_status=?,approval_status='Pending Approval',
                            status='Awaiting Approval',approved_by='',approved_date='',capa_closeout_status='Submitted for Review',
                            capa_closeout_submitted_by=?,capa_closeout_submitted_at=?,capa_closeout_approved_by='',
                            capa_closeout_approved_at='',capa_closeout_comments='',observation_closeout_status='Submitted for Review',
                            verification=? WHERE id=?""",
                            (pct, action_state, by, now, f"Manager action evidence submitted by {by} on {now}", linked_capa["id"]))
                    updated = db.fetchone("SELECT * FROM capa WHERE id=?", (linked_capa["id"],))
                    if updated:
                        sync_observation_from_capa(updated)
                    refresh_closeout_open(); refresh_closeout_evidence(); load()
                    return QMessageBox.information(self, "Submitted for Approval", "The CAPA evidence has been submitted. This observation is now listed in Observation Approval for tracking; the final decision is made once in CAPA Tracking → Approve / Reject CAPA.")

                drafts = db.fetchall("SELECT DISTINCT batch_id FROM observation_closeout_evidence WHERE observation_id=? AND lower(trim(COALESCE(review_status,'')))='draft'", (oid,))
                if not drafts:
                    return QMessageBox.warning(self, "No Draft Evidence", "No draft evidence is attached to this observation. Double-click the observation, attach evidence, then submit it from the evidence window.")
                now = datetime.now().isoformat(timespec="seconds")
                with db.conn:
                    for batch_row in drafts:
                        db.conn.execute("UPDATE observation_closeout_evidence SET review_status='Pending Review',submitted_by=?,submitted_at=? WHERE observation_id=? AND batch_id=? AND lower(trim(COALESCE(review_status,'')))='draft'",
                                        (by, now, oid, safe(batch_row["batch_id"])))
                    db.conn.execute("UPDATE observations SET status='Pending Verification',verification='Close-out evidence submitted for approval' WHERE id=? AND lower(COALESCE(status,''))<>'closed'", (oid,))
                refresh_closeout_open(); refresh_closeout_evidence(); load()
                QMessageBox.information(self, "Submitted for Approval", f"Evidence for {safe(obs['number'])} has been submitted and is now visible in Observation Approval.")
            except Exception as exc:
                logging.exception("Observation close-out evidence submission failed")
                QMessageBox.critical(self, "Submission Error", str(exc))

        def selected_evidence_batch():
            row=evidence_table.currentRow()
            if row<0 or not evidence_table.item(row,1):
                QMessageBox.warning(self,"Review","Select a close-out evidence submission first."); return None
            return evidence_table.item(row,1).text()

        def review_closeout(approved):
            batch=selected_evidence_batch()
            if not batch: return
            _selected_review_row=evidence_table.currentRow()
            _selected_capa_cell=evidence_table.item(_selected_review_row,3) if _selected_review_row >= 0 else None
            if _selected_capa_cell and safe(_selected_capa_cell.text()).startswith("Yes — CAPA approval"):
                return QMessageBox.information(self,"CAPA Approval Required","This submitted observation is CAPA-linked. It is now visible here for tracking, but its approval must be completed once in CAPA Tracking → Approve / Reject CAPA. The Observation Register will synchronize automatically.")
            name=reviewer.text().strip()
            if not name: return QMessageBox.warning(self,"Reviewer Required","Enter the reviewer / verifier name and role.")
            comment=reviewer_comments.text().strip()
            if not approved and not comment: return QMessageBox.warning(self,"Review Comment Required","Enter the reason for rejecting / returning the evidence.")
            rows=db.fetchall("SELECT DISTINCT observation_id FROM observation_closeout_evidence WHERE batch_id=?",(batch,))
            if not rows: return QMessageBox.warning(self,"Review","The selected submission could not be found.")
            _linked_review = db.fetchone("SELECT COALESCE(capa_required,0) AS capa_required FROM observations WHERE id=?", (rows[0]["observation_id"],))
            if _linked_review and int(_linked_review["capa_required"] or 0):
                return QMessageBox.information(self,"Single CAPA Approval","This observation is CAPA-linked. Review and approve it once in CAPA Tracking using Approve / Reject CAPA. The Observation Register will update automatically.")
            state_row=db.fetchone("SELECT review_status FROM observation_closeout_evidence WHERE batch_id=? ORDER BY id DESC LIMIT 1",(batch,))
            if not state_row or safe(state_row["review_status"]).casefold() not in ("pending review","submitted for review"):
                return QMessageBox.warning(self,"Not Submitted","Only evidence explicitly submitted for review can be approved or returned.")
            submitters=db.fetchall("SELECT DISTINCT submitted_by FROM observation_closeout_evidence WHERE batch_id=?",(batch,))
            if any(safe(r["submitted_by"]).strip().casefold()==name.casefold() for r in submitters):
                return QMessageBox.warning(self,"Independent Review Required","The reviewer must be a different person from the evidence submitter.")
            decision="Approved" if approved else "Rejected"; now=datetime.now().isoformat(timespec="seconds")
            try:
                with db.conn:
                    db.conn.execute("UPDATE observation_closeout_evidence SET review_status=?,reviewed_by=?,reviewed_at=?,review_comments=? WHERE batch_id=?",(decision,name,now,comment,batch))
                    for item in rows:
                        oid=int(item["observation_id"])
                        obs=db.conn.execute("SELECT * FROM observations WHERE id=?",(oid,)).fetchone()
                        if not obs: continue
                        old=safe(obs["closeout_comments"])
                        note=f"Close-out evidence {decision.lower()} by {name} on {now}. {comment}".strip()
                        comments=(old+"\n"+note).strip() if old else note
                        if not approved:
                            db.conn.execute("UPDATE observations SET status='Close-out Evidence Returned',verification='Close-out evidence returned for correction',closeout_comments=? WHERE id=?",(comments,oid))
                            if int(obs["capa_required"] or 0):
                                capa_no = ensure_observation_capa_record(obs)
                                linked_capa = db.conn.execute("SELECT * FROM capa WHERE number=?", (capa_no,)).fetchone() if capa_no else None
                                if linked_capa:
                                    db.conn.execute("""UPDATE capa SET observation_closeout_status=?,
                                        capa_closeout_status='Returned',capa_closeout_approved_by=?,
                                        capa_closeout_approved_at=?,capa_closeout_comments=?,status='Rework Required' WHERE id=?""",
                                        (f"Returned by {name} on {now[:10]}",name,now,comment,linked_capa["id"]))
                                    sync_observation_from_capa(db.conn.execute("SELECT * FROM capa WHERE id=?", (linked_capa["id"],)).fetchone())
                            continue
                        if not int(obs["capa_required"] or 0):
                            db.conn.execute("UPDATE observations SET status='Closed',closeout_date=?,closed_by=?,verified_by=?,verification_date=?,verification='Close-out Approved',closeout_comments=? WHERE id=?",(now[:10],name,name,now[:10],comments,oid))
                            continue
                        capa_no=ensure_observation_capa_record(obs)
                        linked_capa=db.conn.execute("SELECT * FROM capa WHERE number=?",(capa_no,)).fetchone() if capa_no else None
                        if linked_capa:
                            _done_close,_total_close,_pct_close,_action_close=capa_actions_completion(
                                linked_capa["actions_json"] if "actions_json" in linked_capa.keys() else linked_capa["corrective_action"])
                            if _total_close == 0 or _pct_close < 100:
                                raise ValueError(f"CAPA close-out cannot be approved until all corrective actions have evidence. Current completion: {_pct_close}% ({_done_close}/{_total_close}).")
                        if not linked_capa:
                            db.conn.execute("UPDATE observations SET status='CAPA Link Missing',verified_by=?,verification_date=?,verification='Close-out evidence approved but linked CAPA record was not found',closeout_comments=? WHERE id=?",(name,now[:10],comments,oid))
                            continue
                        db.conn.execute("""UPDATE capa SET observation_closeout_status=?,
                            capa_closeout_status='Approved',capa_closeout_approved_by=?,
                            capa_closeout_approved_at=?,capa_closeout_comments=? WHERE id=?""",
                            (f"Approved by {name} on {now[:10]}",name,now,comment,linked_capa["id"]))
                        db.conn.execute("""UPDATE observation_closeout_evidence SET review_status='Approved',
                            reviewed_by=?,reviewed_at=?,review_comments=? WHERE observation_id=?
                            AND lower(COALESCE(review_status,'')) IN ('pending review','submitted for review')""",
                            (name,now,comment,oid))
                        # Store verifier details before shared sync recalculates status/progress.
                        db.conn.execute("UPDATE observations SET verified_by=?,verification_date=?,closeout_comments=? WHERE id=?",(name,now[:10],comments,oid))
                        refreshed_capa=db.conn.execute("SELECT * FROM capa WHERE id=?",(linked_capa["id"],)).fetchone()
                        sync_observation_from_capa(refreshed_capa)
                QMessageBox.information(self,"Review Saved",f"Submission {batch} marked {decision}. Sections A and B, the Observation Register and the linked CAPA Register have been synchronized.")
                refresh_closeout_open(); refresh_closeout_evidence(); load()
                for evidence_row in range(evidence_table.rowCount()):
                    if evidence_table.item(evidence_row,1) and evidence_table.item(evidence_row,1).text()==batch:
                        evidence_table.selectRow(evidence_row)
                        break
            except Exception as e:
                logging.exception("Observation close-out review failed"); QMessageBox.critical(self,"Review Error",str(e))

        def refresh_both_closeout_sections():
            refresh_closeout_open()
            refresh_closeout_evidence()

        upload_closeout.clicked.connect(lambda: open_observation_action_evidence()); submit_closeout.clicked.connect(submit_attached_closeout_evidence); refresh_open.clicked.connect(refresh_both_closeout_sections)
        refresh_evidence.clicked.connect(refresh_both_closeout_sections); approve_btn.clicked.connect(lambda:review_closeout(True)); reject_btn.clicked.connect(lambda:review_closeout(False))

        def upload_closeout_from_observation_register():
            ids = selected_observation_ids(require_one=True)
            if not ids:
                return
            oid = ids[0]
            obs = db.fetchone("SELECT * FROM observations WHERE id=?", (oid,))
            if not obs:
                return
            if safe(obs["status"]).casefold() in ("closed", "cancelled"):
                return QMessageBox.information(self, "Close-out Evidence", "This observation is already closed. Its evidence and approval history remain available for review.")
            if int(obs["capa_required"] or 0):
                capa_no = ensure_observation_capa_record(obs)
                capa_row = db.fetchone("SELECT * FROM capa WHERE number=?", (capa_no,)) if capa_no else None
                if not capa_row:
                    return QMessageBox.warning(self, "CAPA Link Missing", "The linked CAPA record could not be found.")
                open_capa_action_evidence_dialog(self, capa_row["id"], on_saved=lambda: (refresh_closeout_open(), refresh_closeout_evidence(), load()))
                return
            by, ok = QInputDialog.getText(self, "Upload Observation Close-out Evidence", "Uploaded by:", text=safe(db.setting("current_user", "") or db.setting("username", "")))
            if not ok:
                return
            if not by.strip():
                return QMessageBox.warning(self, "Submitter Required", "Enter the name / ID of the person uploading the evidence.")
            paths, _ = QFileDialog.getOpenFileNames(self, "Select Observation Close-out Evidence", "", "Evidence Files (*.png *.jpg *.jpeg *.bmp *.pdf *.doc *.docx *.xls *.xlsx *.txt *.mp4 *.avi *.mov);;All Files (*)")
            if not paths:
                return
            batch = f"OBS-REG-CO-{oid}-{datetime.now().strftime('%Y%m%d%H%M%S%f')}"
            saved = []
            now = datetime.now().isoformat(timespec="seconds")
            try:
                with db.conn:
                    capa_no = safe(obs["capa_number"])
                    if int(obs["capa_required"] or 0):
                        capa_no = ensure_observation_capa_record(obs)
                    linked = db.conn.execute("SELECT id,closeout_evidence FROM capa WHERE number=?", (capa_no,)).fetchone() if capa_no else None
                    for src in paths:
                        source = Path(src)
                        if not source.is_file():
                            continue
                        dest = ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{source.name}"
                        n = 1
                        while dest.exists():
                            dest = ATTACH_DIR / f"{safe(obs['number'])}_Closeout_{n}_{source.name}"
                            n += 1
                        shutil.copy2(source, dest)
                        saved.append(dest)
                        db.conn.execute("INSERT INTO observation_closeout_evidence(batch_id,observation_id,file_path,submitted_by,submitted_at,review_status) VALUES(?,?,?,?,?,'Draft')", (batch, oid, str(dest), by.strip(), now))
                        db.conn.execute("INSERT INTO observation_attachments(observation_id,file_path,attachment_type) VALUES(?,?,?)", (oid, str(dest), "Close-out Evidence"))
                        if linked:
                            db.conn.execute("INSERT INTO capa_attachments(capa_id,file_path,attachment_type) VALUES(?,?,?)", (linked["id"], str(dest), "CAPA Close-out Evidence"))
                            prior = safe(linked["closeout_evidence"])
                            combined = ";".join(dict.fromkeys([x for x in prior.split(";") + [str(dest)] if x]))
                            db.conn.execute("UPDATE capa SET closeout_evidence=?,capa_closeout_status=CASE WHEN lower(COALESCE(capa_closeout_status,'')) IN ('approved','submitted for review','pending review') THEN capa_closeout_status ELSE 'Draft' END WHERE id=?", (combined, linked["id"]))
                if not saved:
                    raise ValueError("No selected evidence file could be read.")
                load(); refresh_closeout_open(); refresh_closeout_evidence()
                QMessageBox.information(self, "Evidence Attached", "Close-out evidence is saved as Draft and is visible in both the Observation Register and the linked CAPA Tracking Register. Submit it for review from the Open Observations / Observation Approval tab.")
            except Exception as exc:
                for fp in saved:
                    try: fp.unlink(missing_ok=True)
                    except Exception: pass
                logging.exception("Observation-register close-out evidence upload failed")
                QMessageBox.critical(self, "Upload Error", str(exc))

        closeout_evidence_button.clicked.connect(upload_closeout_from_observation_register)

        # ---------------- Specific Inspection Report tab ----------------
        report_page=QWidget(); report_layout=QVBoxLayout(report_page)
        report_page.setStyleSheet("""
            QLabel { color: #17365D; font-weight: 600; }
            QGroupBox { color: #17365D; font-weight: 700; border: 1px solid #8FAAC4; border-radius: 6px; margin-top: 8px; padding-top: 8px; }
            QGroupBox::title { color: #17365D; font-weight: 700; subcontrol-origin: margin; left: 10px; padding: 0 4px; }
            QHeaderView::section { color: #17365D; font-weight: 700; background: #DCEAF6; padding: 5px; }
        """)
        report_intro=QLabel(
            "Choose the observation type and inspection date, load the matching records, "
            "then select only the observations that must appear in the report."
        )
        report_intro.setWordWrap(True)
        report_intro.setStyleSheet("color:#24476b;padding:6px;font-weight:600;")
        report_layout.addWidget(report_intro)

        filters=QGridLayout(); report_layout.addLayout(filters)
        type_filter=QComboBox(); type_filter.addItem("All Observation Types"); type_filter.addItems(OBS_TYPES)
        category_filter=QComboBox(); category_filter.addItem("All Categories"); category_filter.addItems(CATEGORIES)
        project_filter=QLineEdit(); project_filter.setPlaceholderText("All projects / enter project name")
        location_filter=QLineEdit(); location_filter.setPlaceholderText("All locations / enter location")
        use_exact_date=QCheckBox("Filter by exact inspection date")
        use_exact_date.setChecked(True)
