        track_state = {"employees": [], "courses": []}

        def load_tracker():
            """Show every active employee (frozen ID/Name/Trade) + course status columns."""
            try:
                try:
                    load_grid_state()
                except Exception:
                    logging.exception("load_grid_state in tracker failed")
                employees = db.fetchall(
                    "SELECT id, employee_id, name, designation, company FROM employees WHERE COALESCE(active,1)=1 ORDER BY name COLLATE NOCASE"
                ) or []
                needle = track_search.text().strip().lower()
                if needle:
                    employees = [
                        e for e in employees
                        if needle in " ".join(safe(e[k]).lower() for k in ("employee_id", "name", "designation", "company"))
                    ]
                course_needle = track_course_filter.text().strip().lower()
                course_set = list(grid_state.get("courses") or [])
                try:
                    course_set = prioritized_courses(course_set)
                except Exception:
                    pass
                if not course_set:
                    try:
                        course_set = [x[0] for x in READY_COURSES]
                    except Exception:
                        course_set = []
                if course_needle:
                    course_set = [c for c in course_set if course_needle in c.lower()]
                track_state["employees"] = employees
                track_state["courses"] = course_set

                track_frozen.setUpdatesEnabled(False)
                track_table.setUpdatesEnabled(False)
                track_frozen.setRowCount(0)
                track_table.setRowCount(0)
                track_frozen.setColumnCount(6)
                track_frozen.setHorizontalHeaderLabels(["S.No.", "ID", "Name", "Trade", "Company", "Mandatory %"])
                track_frozen.setRowCount(len(employees))
                track_table.setColumnCount(max(1, len(course_set)))
                track_table.setHorizontalHeaderLabels(course_set if course_set else ["(Save Matrix Grid to load courses)"])
                track_table.setRowCount(len(employees))
                try:
                    hdr_h = max(30, track_table.horizontalHeader().height())
                    track_frozen.horizontalHeader().setFixedHeight(hdr_h)
                except Exception:
                    pass

                for r, emp in enumerate(employees):
                    try:
                        reqs = requirements_for_trade(emp["designation"])
                    except Exception:
                        reqs = []
                    mand = [x for x in reqs if x[1] == "Mandatory"]
                    done = 0
                    for cname, req, validity in mand:
                        try:
                            st, _, _ = status_of(latest_record(emp["id"], cname), validity)
                            if st in ("Valid", "Expiring Soon"):
                                done += 1
                        except Exception:
                            pass
                    pct = int(round(100 * done / len(mand))) if mand else None
                    pct_text = "N/A" if pct is None else f"{pct}% ({done}/{len(mand)})"
                    base = [
                        str(r + 1),
                        safe(emp["employee_id"]),
                        safe(emp["name"]),
                        safe(emp["designation"]),
                        safe(emp["company"]),
                        pct_text,
                    ]
                    for c, val in enumerate(base):
                        it = QTableWidgetItem(val)
                        it.setBackground(QBrush(QColor("#EEF4FB")))
                        if c == 2:
                            f = it.font(); f.setBold(True); it.setFont(f)
                        if c == 5 and pct is not None:
                            bg, fg = color_status(
                                "Valid" if pct >= 100 else ("Expiring Soon" if pct >= 50 else "Not Completed")
                            )
                            it.setBackground(QBrush(bg))
                            it.setForeground(QBrush(fg))
                        if c == 1:
                            it.setData(Qt.ItemDataRole.UserRole, int(emp["id"]))
                        track_frozen.setItem(r, c, it)

                    req_map = {x[0]: x for x in reqs}
                    for offset, cname in enumerate(course_set):
                        if cname not in req_map:
                            it = QTableWidgetItem("— / Click to add")
                            it.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                            it.setToolTip("Not required for this trade — double-click or use Edit to log training anyway")
                            it.setData(Qt.ItemDataRole.UserRole, {
                                "emp_id": int(emp["id"]),
                                "course": cname,
                                "validity": int(grid_state.get("validity", {}).get(cname, 0) or 0),
                                "req": "Optional",
                                "record_id": None,
                            })
                            track_table.setItem(r, offset, it)
                            continue
                        req, validity = req_map[cname][1], req_map[cname][2]
                        rec = latest_record(emp["id"], cname)
                        st, train, expiry = status_of(rec, validity)
                        days = None
                        if expiry:
                            try:
                                days = (date.fromisoformat(expiry) - date.today()).days
                            except Exception:
                                days = None
                        days_txt = "" if days is None else (f"{days}d left" if days >= 0 else f"{abs(days)}d overdue")
                        short = {"Mandatory": "M", "Optional": "O", "Before Job": "B"}.get(req, "")
                        lines = [f"{short} · {st}"]
                        if train:
                            lines.append(str(train))
                        if expiry:
                            lines.append("Exp " + str(expiry))
                        if days_txt:
                            lines.append(days_txt)
                        it = QTableWidgetItem("\n".join(lines))
                        it.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                        it.setData(Qt.ItemDataRole.UserRole, {
                            "emp_id": int(emp["id"]),
                            "course": cname,
                            "validity": validity,
                            "req": req,
                            "record_id": int(rec["id"]) if rec else None,
                        })
                        bg, fg = color_status(st)
                        it.setBackground(QBrush(bg))
                        it.setForeground(QBrush(fg))
                        track_table.setItem(r, offset, it)
                    track_frozen.setRowHeight(r, 52)
                    track_table.setRowHeight(r, 52)

                track_frozen.setColumnWidth(0, 50)
                track_frozen.setColumnWidth(1, 90)
                track_frozen.setColumnWidth(2, 150)
                track_frozen.setColumnWidth(3, 120)
                track_frozen.setColumnWidth(4, 100)
                track_frozen.setColumnWidth(5, 150)  # Mandatory % fully visible e.g. 100% (3/3)
                try:
                    track_frozen.horizontalHeader().setSectionResizeMode(5, QHeaderView.ResizeMode.ResizeToContents)
                except Exception:
                    pass
                try:
                    track_frozen.verticalScrollBar().setValue(track_table.verticalScrollBar().value())
                except Exception:
                    pass
                track_status.setText(
                    f"Showing {len(employees)} employee(s) · {len(course_set)} training column(s). "
                    "Double-click a training cell to log / update training."
                )
            except Exception as exc:
                logging.exception("load_tracker failed")
                try:
                    track_status.setText(f"Tracking load error: {exc}")
                except Exception:
                    pass
            finally:
                try:
                    track_frozen.setUpdatesEnabled(True)
                    track_table.setUpdatesEnabled(True)
                except Exception:
                    pass


        def _populate_compliance_filters():
            companies = sorted({safe(r["company"]) for r in db.fetchall("SELECT DISTINCT company FROM employees WHERE COALESCE(active,1)=1") if safe(r["company"])})
            trades = sorted({safe(r["designation"]) for r in db.fetchall("SELECT DISTINCT designation FROM employees WHERE COALESCE(active,1)=1") if safe(r["designation"])})
            cur_c = compliance_filter_company.currentText()
            cur_t = compliance_filter_trade.currentText()
            compliance_filter_company.blockSignals(True)
            compliance_filter_trade.blockSignals(True)
            compliance_filter_company.clear(); compliance_filter_company.addItem("All companies")
            for c in companies:
                compliance_filter_company.addItem(c)
            compliance_filter_trade.clear(); compliance_filter_trade.addItem("All trades")
            for t in trades:
                compliance_filter_trade.addItem(t)
            if cur_c:
                ix = compliance_filter_company.findText(cur_c)
                if ix >= 0:
                    compliance_filter_company.setCurrentIndex(ix)
            if cur_t:
                ix = compliance_filter_trade.findText(cur_t)
                if ix >= 0:
                    compliance_filter_trade.setCurrentIndex(ix)
            compliance_filter_company.blockSignals(False)
            compliance_filter_trade.blockSignals(False)

        def refresh_compliance_dashboard():
            try:
                load_grid_state()
            except Exception:
                logging.exception("compliance load_grid_state failed")
            _populate_compliance_filters()
            all_employees = db.fetchall(
                "SELECT id, employee_id, name, designation, company FROM employees WHERE COALESCE(active,1)=1 ORDER BY name COLLATE NOCASE"
            )
            company_f = compliance_filter_company.currentText().strip()
            trade_f = compliance_filter_trade.currentText().strip()
            search_f = compliance_filter_search.text().strip().lower()
            mode = compliance_filter_mode.currentData() or "overall"

            def _match(emp):
                if company_f and company_f != "All companies" and safe(emp["company"]) != company_f:
                    return False
                if trade_f and trade_f != "All trades" and safe(emp["designation"]) != trade_f:
                    return False
                if search_f and search_f not in " ".join(safe(emp[k]).lower() for k in ("employee_id", "name")):
                    return False
                return True

            filtered = [e for e in all_employees if _match(e)]
            # KPI population set
            if mode == "overall":
                kpi_employees = all_employees
            else:
                kpi_employees = filtered

            total_required = 0
            compliant_required = 0
            expired_count = 0
            expiring_count = 0
            missing_count = 0
            pending_count = 0
            exceptions = []
            for emp in kpi_employees:
                reqs = requirements_for_trade(emp["designation"])
                non_compliant = 0
                emp_expired = 0
                for cname, req, validity in reqs:
                    if req != "Mandatory":
                        continue
                    total_required += 1
                    rec = latest_record(emp["id"], cname)
                    st, _, _ = status_of(rec, validity)
                    if st in ("Valid", "Expiring Soon"):
                        compliant_required += 1
                    else:
                        non_compliant += 1
                        if st == "Expired":
                            expired_count += 1
                            emp_expired += 1
                        elif st == "Pending Verification":
                            pending_count += 1
                        else:
                            missing_count += 1
                    if st == "Expiring Soon":
                        expiring_count += 1
                if non_compliant:
                    exceptions.append((emp, non_compliant, emp_expired))
            compliance_pct = (100.0 * compliant_required / total_required) if total_required else 100.0
            date_clause = ""
            date_params = []
            if compliance_use_dates.isChecked():
                d0 = compliance_date_from.date().toString("yyyy-MM-dd")
                d1 = compliance_date_to.date().toString("yyyy-MM-dd")
                date_clause = " AND tr.training_date >= ? AND tr.training_date <= ?"
                date_params = [d0, d1]
            delivered = db.fetchone(
                f"""SELECT COALESCE(SUM(COALESCE(c.training_hours,0)),0) AS h
                   FROM training_records tr
                   JOIN training_courses c ON c.id=tr.course_id
                   JOIN employees e ON e.id=tr.employee_db_id
                   WHERE COALESCE(e.active,1)=1{date_clause}""",
                tuple(date_params) if date_params else ()
            )
            man_hours = float(delivered["h"] if delivered else 0)
            required_hours = 0.0
            for emp in kpi_employees:
                for cname, req, validity in requirements_for_trade(emp["designation"]):
                    if req != "Mandatory":
                        continue
                    required_hours += float(grid_state["hours"].get(cname, 0) or 0)
            compliance_values["employees"].setText(str(len(kpi_employees)))
            compliance_values["compliance"].setText(f"{compliance_pct:.0f}%")
            compliance_values["expired"].setText(str(expired_count))
            compliance_values["expiring"].setText(str(expiring_count))
            compliance_values["missing"].setText(str(missing_count))
            compliance_values["pending"].setText(str(pending_count))
            compliance_values["man_hours"].setText(f"{man_hours:.0f}")
            compliance_values["required_hours"].setText(f"{required_hours:.0f}")

            # Table rows: filtered set; optional non-compliant only
            table_emps = filtered
            if mode == "noncompliant":
                non_ids = {int(e[0]["id"]) for e in exceptions}
                table_emps = [e for e in filtered if int(e["id"]) in non_ids]
            # Build exception map for table numbers
            exc_map = {int(e[0]["id"]): (e[1], e[2]) for e in exceptions}
            compliance_table.setRowCount(len(table_emps))
            for row_idx, emp in enumerate(table_emps):
                nc, ex = exc_map.get(int(emp["id"]), (0, 0))
                values = [
                    safe(emp["employee_id"]), safe(emp["name"]), safe(emp["company"]),
                    safe(emp["designation"]), str(nc), str(ex)
                ]
                for col_idx, value in enumerate(values):
                    compliance_table.setItem(row_idx, col_idx, QTableWidgetItem(value))
            compliance_table.sortItems(4, Qt.SortOrder.DescendingOrder)

        compliance_refresh.clicked.connect(refresh_compliance_dashboard)

        def log_or_edit_cell(row=None, column=None):
            """Edit any training cell (mandatory or not). Log date, expiry, provider, certificate."""
            if row is None:
                row = track_table.currentRow()
            if column is None:
                column = track_table.currentColumn()
            if row is None or row < 0:
                row = track_frozen.currentRow()
            if row is None or row < 0:
                return QMessageBox.information(
                    self, "Tracking",
                    "Select an employee row, then a training cell on the RIGHT side.\n"
                    "Double-click the cell or click Edit Selected Cell."
                )
            if column is None or column < 0:
                # If only frozen row selected, still allow pick via first visible course if only one? Prefer message.
                return QMessageBox.information(
                    self, "Tracking",
                    "Click a training course cell on the RIGHT (status columns), then Edit or double-click.\n"
                    "Non-mandatory cells show '— / Click to add' and can still be logged."
                )

            # Resolve employee from frozen left table
            if row >= len(track_state.get("employees") or []):
                return QMessageBox.information(self, "Tracking", "Invalid employee row.")
            emp = track_state["employees"][row]
            emp_id = int(emp["id"])

            # Resolve course name
            item = track_table.item(row, column)
            data = item.data(Qt.ItemDataRole.UserRole) if item else None
            if isinstance(data, dict) and data.get("course"):
                cname = data["course"]
                validity = int(data.get("validity") or 0)
                req = data.get("req") or "Optional"
            else:
                courses = track_state.get("courses") or []
                if column >= len(courses):
                    return QMessageBox.information(self, "Tracking", "Select a valid training course column.")
                cname = courses[column]
                validity = int(grid_state.get("validity", {}).get(cname, 0) or 0)
                req = "Optional"
                try:
                    for cn, r, v in requirements_for_trade(emp["designation"]):
                        if cn == cname:
                            req, validity = r, int(v or 0)
                            break
                except Exception:
                    pass

            rec = latest_record(emp_id, cname)
            dlg = QDialog(self)
            dlg.setWindowTitle(f"Log Training — {cname}")
            dlg.setMinimumWidth(420)
            form = QFormLayout(dlg)
            form.addRow(QLabel(f"Employee: {safe(emp['employee_id'])} · {safe(emp['name'])}"))
            form.addRow(QLabel(f"Requirement: {req or 'Optional'} · Validity: {validity} months"))
            d_train = QDateEdit(QDate.currentDate()); d_train.setCalendarPopup(True); d_train.setDisplayFormat("yyyy-MM-dd")
            if rec and safe(rec["training_date"]):
                td = QDate.fromString(safe(rec["training_date"]), "yyyy-MM-dd")
                if td.isValid():
                    d_train.setDate(td)
            d_exp = QDateEdit(QDate.currentDate()); d_exp.setCalendarPopup(True); d_exp.setDisplayFormat("yyyy-MM-dd")
            no_expiry = QCheckBox("No expiry — this course does not expire")
            no_expiry.setChecked(bool(not validity and not (rec and safe(rec["expiry_date"]))))
            d_exp.setEnabled(not no_expiry.isChecked())
            no_expiry.toggled.connect(d_exp.setDisabled)

            def auto_exp(*_):
                if validity and not no_expiry.isChecked():
                    try:
                        base = date(d_train.date().year(), d_train.date().month(), d_train.date().day())
                        exp = add_calendar_months(base, int(validity))
                        d_exp.setDate(QDate(exp.year, exp.month, exp.day))
                    except Exception:
                        pass
            d_train.dateChanged.connect(auto_exp)
            if validity and not (rec and safe(rec["expiry_date"])):
                auto_exp()
            elif rec and safe(rec["expiry_date"]):
                ed = QDate.fromString(safe(rec["expiry_date"]), "yyyy-MM-dd")
                if ed.isValid():
                    d_exp.setDate(ed)

            due_lbl = QLabel("—")
            def update_due(*_):
                if no_expiry.isChecked():
                    due_lbl.setText("No expiry")
                    return
                try:
                    exp_d = date(d_exp.date().year(), d_exp.date().month(), d_exp.date().day())
                    days = (exp_d - date.today()).days
                    if days > 0:
                        due_lbl.setText(f"{days} day(s) remaining")
                    elif days == 0:
                        due_lbl.setText("Expires today")
                    else:
                        due_lbl.setText(f"{abs(days)} day(s) overdue")
                except Exception:
                    due_lbl.setText("—")
            d_exp.dateChanged.connect(update_due)
            no_expiry.toggled.connect(update_due)
            update_due()

            provider = QLineEdit(safe(rec["provider"]) if rec else "")
            cert_no = QLineEdit(safe(rec["certificate_no"]) if rec else "")
            notes = QLineEdit(safe(rec["notes"]) if rec and "notes" in rec.keys() else "")
            verify_status = QComboBox()
            for vs in ("Pending Verification", "Verified", "Rejected"):
                verify_status.addItem(vs)
            if rec and safe(rec["verification_status"]):
                ix = verify_status.findText(safe(rec["verification_status"]))
                if ix >= 0:
                    verify_status.setCurrentIndex(ix)
            assess = QLineEdit(safe(rec["assessment_result"]) if rec and "assessment_result" in rec.keys() else "")
            form.addRow("Training date *", d_train)
            form.addRow("Expiry date", d_exp)
            form.addRow("", no_expiry)
            form.addRow("Due / remaining", due_lbl)
            form.addRow("Provider / Trainer", provider)
            form.addRow("Certificate No.", cert_no)
            form.addRow("Assessment result", assess)
            form.addRow("Verification", verify_status)
            form.addRow("Notes", notes)
            buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
            form.addRow(buttons)

            def save_log():
                tdate = d_train.date().toString("yyyy-MM-dd")
                edate = "" if no_expiry.isChecked() else d_exp.date().toString("yyyy-MM-dd")
                course_id = ensure_course(cname, validity)
                verify_s = verify_status.currentText()
                verified_by = ""
                verified_at = ""
                if verify_s == "Verified":
                    verified_by = db.setting("default_observer", "") or "System"
                    verified_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                if rec:
                    db.execute(
                        """UPDATE training_records SET training_date=?, expiry_date=?, provider=?,
                           certificate_no=?, notes=?, verification_status=?, verified_by=?, verified_at=?,
                           assessment_result=? WHERE id=?""",
                        (tdate, edate, provider.text().strip(), cert_no.text().strip(), notes.text().strip(),
                         verify_s, verified_by, verified_at, assess.text().strip(), rec["id"])
                    )
                    record_id = int(rec["id"])
                    action = "Updated"
                else:
                    cur = db.execute(
                        """INSERT INTO training_records
                           (employee_db_id, course_id, training_date, expiry_date, provider,
                            certificate_no, notes, verification_status, verified_by, verified_at, assessment_result)
                           VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                        (emp_id, course_id, tdate, edate, provider.text().strip(), cert_no.text().strip(),
                         notes.text().strip(), verify_s, verified_by, verified_at, assess.text().strip())
                    )
                    record_id = int(cur.lastrowid)
                    action = "Created"
                try:
                    db.execute(
                        "INSERT INTO training_audit_log (entity_type, entity_id, action, details) VALUES (?,?,?,?)",
                        ("training_record", record_id, action,
                         f"Employee DB ID={emp_id}; course={cname}; training_date={tdate}; verification={verify_s}")
                    )
                except Exception:
                    pass
                dlg.accept()
                load_tracker()
                try:
                    refresh_category_registers()
                except Exception:
                    pass
                try:
                    refresh_master_training_register()
                except Exception:
                    pass

            buttons.accepted.connect(save_log)
            buttons.rejected.connect(dlg.reject)
            dlg.exec()


        def clear_selected_cell():
            row = track_table.currentRow()
            column = track_table.currentColumn()
            if row < 0 or column < 0:
                return QMessageBox.information(self, "Clear", "Select a training course cell on the right side first.")
            item = track_table.item(row, column)
            if not item:
                return
            data = item.data(Qt.ItemDataRole.UserRole)
            if not isinstance(data, dict):
                return
            rec = latest_record(data["emp_id"], data["course"])
            if not rec:
                return QMessageBox.information(self, "Clear", "No training record on this cell.")
            reason, ok = QInputDialog.getText(self, "Archive Training Record", "Reason for removing this record from the active register:")
            if not ok:
                return
            if not reason.strip():
                return QMessageBox.warning(self, "Reason Required", "Enter a reason. The record will be retained in Training History.")
            try:
                db.conn.execute("BEGIN")
                db.conn.execute("""INSERT INTO training_record_history
                    (original_record_id, employee_db_id, course_id, training_date, expiry_date,
                     provider, certificate_no, attachment_path, notes, created_at,
                     archived_by, archive_reason, verification_status, verified_by, verified_at,
                     assessment_result, assessment_score)
                    SELECT id, employee_db_id, course_id, training_date, expiry_date,
                           provider, certificate_no, attachment_path, notes, created_at,
                           'Local User', ?, verification_status, verified_by, verified_at,
                           assessment_result, assessment_score
                    FROM training_records WHERE id=?""", (reason.strip(), rec["id"]))
                db.conn.execute("DELETE FROM training_records WHERE id=?", (rec["id"],))
                db.conn.execute(
                    "INSERT INTO training_audit_log (entity_type, entity_id, action, details) VALUES (?,?,?,?)",
                    ("training_record", int(rec["id"]), "Archived", reason.strip())
                )
                db.conn.commit()
            except Exception as exc:
                db.conn.rollback()
                logging.exception("Training record archive failed")
                QMessageBox.critical(self, "Archive Error", f"The training record was not changed.\n\n{exc}")
                return
            load_tracker()
            refresh_category_registers()
            refresh_master_training_register()

        def export_tracker_excel():
            path, _ = QFileDialog.getSaveFileName(self, "Export Tracking Register", "Training_Tracking_Register.xlsx", "Excel Workbook (*.xlsx)")
            if not path:
                return
            if not path.lower().endswith(".xlsx"):
                path += ".xlsx"
            load_tracker()
            wb = Workbook(); ws = wb.active; ws.title = "Tracking Register"
            left_headers = [track_frozen.horizontalHeaderItem(c).text() if track_frozen.horizontalHeaderItem(c) else "" for c in range(track_frozen.columnCount())]
            right_headers = [track_table.horizontalHeaderItem(c).text() if track_table.horizontalHeaderItem(c) else "" for c in range(track_table.columnCount())]
            headers = left_headers + right_headers
            ws.append(headers)
            for r in range(track_frozen.rowCount()):
                left = [(track_frozen.item(r, c).text() if track_frozen.item(r, c) else "") for c in range(track_frozen.columnCount())]
                right = [(track_table.item(r, c).text() if track_table.item(r, c) else "") for c in range(track_table.columnCount())]
                ws.append(left + right)
            style_training_excel_workbook(wb, ws, "HSE TRAINING TRACKING REGISTER")
            for cell in ws[5]:
                if cell.value is not None:
                    cell.font = Font(bold=True, color="FFFFFF")
                    cell.fill = PatternFill("solid", fgColor="17365D")
                    cell.alignment = Alignment(wrap_text=True, horizontal="center")
            for r in range(6, ws.max_row + 1):
                for c in range(1, ws.max_column + 1):
                    cell = ws.cell(r, c)
                    cell.alignment = Alignment(wrap_text=True, vertical="top")
                    low = safe(cell.value).lower()
                    if "expired" in low or "not completed" in low or "overdue" in low:
                        cell.fill = PatternFill("solid", fgColor="FDE2E2")
                    elif "expiring" in low:
                        cell.fill = PatternFill("solid", fgColor="FFF4CE")
                    elif low == "valid":
                        cell.fill = PatternFill("solid", fgColor="DDF5E5")
            ws.freeze_panes = "A6"
            from openpyxl.utils import get_column_letter
            for col in ws.columns:
                letter = get_column_letter(col[0].column)
                longest = max((len(str(c.value or "").split("\n")[0]) for c in col), default=10)
                ws.column_dimensions[letter].width = min(max(longest + 2, 12), 28)
            wb.save(path)
            QMessageBox.information(self, "Export", f"Exported:\n{path}")

        def export_tracker_word():
            path, _ = QFileDialog.getSaveFileName(self, "Export Tracking Register", "Training_Tracking_Register.docx", "Word Document (*.docx)")
            if not path:
                return
            if not path.lower().endswith(".docx"):
                path += ".docx"
            load_tracker()
            doc = Document()
            set_docx_landscape(doc)
            add_docx_report_header(doc, "HSE TRAINING TRACKING REGISTER", "TRN", f"{document_prefix()}-TRN-{datetime.now().strftime('%Y%m%d%H%M%S')}")
            table = doc.add_table(rows=1, cols=6)
            for i, h in enumerate(["S.No.", "ID", "Name", "Trade", "Company", "Mandatory %"]):
                table.rows[0].cells[i].text = h
            for r in range(track_frozen.rowCount()):
                cells = table.add_row().cells
                for c in range(6):
                    it = track_frozen.item(r, c)
                    cells[c].text = xml_safe(it.text() if it else "")
            style_docx_table(table, header=True, font_size=8)
            doc.add_paragraph("Full course-level status is available in the Excel export and on-screen register.")
            add_docx_footer(doc)
            save_docx_validated(doc, path)
            QMessageBox.information(self, "Export", f"Exported:\\n{path}")

        # =====================================================================
        # ADDITIONAL TRAINING REGISTERS — I / E / C and employee-wise master
        # =====================================================================
        def training_record_status(rec, validity):
            st, _, exp = status_of(rec, validity)
            return st, exp or ""

        category_pages = {}
        category_tables = {}
        def refresh_category_registers():
            # Internal: training_type I
            # External: training_type E or C (client / TPI / certification merged into External)
            for code, table in category_tables.items():
                if code == "I":
                    rows = db.fetchall("""SELECT tr.id,e.employee_id,e.name,e.designation,e.company,c.course_name,
                        COALESCE(c.training_type,'I') AS training_type,tr.provider,tr.training_date,tr.expiry_date,tr.certificate_no,tr.verification_status
                        FROM training_records tr JOIN employees e ON e.id=tr.employee_db_id
                        JOIN training_courses c ON c.id=tr.course_id
                        WHERE COALESCE(c.training_type,'I')='I' AND COALESCE(e.active,1)=1
                        ORDER BY e.name COLLATE NOCASE,tr.training_date DESC""")
                else:
                    rows = db.fetchall("""SELECT tr.id,e.employee_id,e.name,e.designation,e.company,c.course_name,
                        COALESCE(c.training_type,'E') AS training_type,tr.provider,tr.training_date,tr.expiry_date,tr.certificate_no,tr.verification_status
                        FROM training_records tr JOIN employees e ON e.id=tr.employee_db_id
                        JOIN training_courses c ON c.id=tr.course_id
                        WHERE COALESCE(c.training_type,'I') IN ('E','C') AND COALESCE(e.active,1)=1
                        ORDER BY e.name COLLATE NOCASE,tr.training_date DESC""")
                headers = 11 if code != "I" else 10
                table.setRowCount(len(rows))
                for ri, row in enumerate(rows):
                    ttype = safe(row["training_type"] if "training_type" in row.keys() else "I")
                    type_label = {"I":"Internal","E":"External","C":"Client"}.get(ttype, ttype)
                    if code == "I":
                        vals = [row["employee_id"],row["name"],row["designation"],row["company"],row["course_name"],row["provider"],row["training_date"],row["expiry_date"],row["certificate_no"],row["verification_status"]]
                    else:
                        vals = [row["employee_id"],row["name"],row["designation"],row["company"],row["course_name"],type_label,row["provider"],row["training_date"],row["expiry_date"],row["certificate_no"],row["verification_status"]]
                    for ci, val in enumerate(vals):
                        it = QTableWidgetItem(safe(val)); table.setItem(ri,ci,it)
                    table.item(ri,0).setData(Qt.ItemDataRole.UserRole,int(row["id"]))


        def style_training_excel_workbook(wb, ws, title, headers_row=2):
            """Apply company logo, document number and professional header to training exports."""
            report_no = f"{document_prefix()}-TRN-{datetime.now().strftime('%Y%m%d%H%M%S')}"
            company = company_name()
            project = db.setting("project_name", "")
            # Title block
            ws.insert_rows(1, 4)
            ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max(6, ws.max_column))
            ws["A1"] = title
            ws["A1"].font = Font(name="Arial", size=16, bold=True, color="FFFFFF")
            ws["A1"].fill = PatternFill("solid", fgColor="17365D")
            ws["A1"].alignment = Alignment(horizontal="center", vertical="center")
            ws.row_dimensions[1].height = 28
            ws["A2"] = f"Company: {company}"
            ws["A3"] = f"Project: {project}"
            ws["A4"] = f"Document / Report No.: {report_no}    Generated: {datetime.now().strftime('%Y-%m-%d %H:%M')}"
            for r in (2, 3, 4):
                ws.cell(r, 1).font = Font(name="Arial", size=9, bold=True, color="17365D")
            # Logo if available
            logo = report_logo_path()
            if logo and Path(logo).exists():
                try:
                    img = XLImage(str(logo))
                    img.width = 90
                    img.height = 45
                    ws.add_image(img, "F2")
                except Exception:
                    logging.exception("Training export logo failed")
            return report_no

        def export_category_register(code, table, title):
            path_xlsx, _ = QFileDialog.getSaveFileName(self, f"Export {title}", f"{title.replace(' ','_')}.xlsx", "Excel Workbook (*.xlsx)")
            if not path_xlsx:
                return
            if not path_xlsx.lower().endswith(".xlsx"):
                path_xlsx += ".xlsx"
            refresh_category_registers()
            wb = Workbook(); ws = wb.active; ws.title = title[:31]
            headers = [table.horizontalHeaderItem(c).text() for c in range(table.columnCount())]
            ws.append(headers)
            for r in range(table.rowCount()):
                ws.append([table.item(r,c).text() if table.item(r,c) else "" for c in range(table.columnCount())])
            style_training_excel_workbook(wb, ws, title.upper())
            # Header row is now row 5 after branding insert
            for cell in ws[5]:
                if cell.value is not None:
                    cell.font = Font(bold=True, color="FFFFFF"); cell.fill = PatternFill("solid", fgColor="17365D")
                    cell.alignment = Alignment(wrap_text=True, horizontal="center")
            ws.freeze_panes = "A6"
            try:
                ws.auto_filter.ref = f"A5:{ws.cell(ws.max_row, ws.max_column).coordinate}"
            except Exception:
                pass
            from openpyxl.utils import get_column_letter
            for col in ws.columns:
                letter = get_column_letter(col[0].column)
                ws.column_dimensions[letter].width = min(max(max(len(str(c.value or "")) for c in col)+2, 12), 36)
            wb.save(path_xlsx)
            # Word export companion
            path_docx = path_xlsx[:-5] + ".docx"
            try:
                doc = Document()
                set_docx_landscape(doc)
                add_docx_report_header(doc, title.upper(), "TRN", f"{document_prefix()}-TRN-{datetime.now().strftime('%Y%m%d%H%M%S')}")
                t = doc.add_table(rows=1, cols=len(headers))
                for i,h in enumerate(headers): t.rows[0].cells[i].text = h
                for r in range(table.rowCount()):
                    cells = t.add_row().cells
                    for c in range(table.columnCount()):
                        cells[c].text = xml_safe(table.item(r,c).text() if table.item(r,c) else "")
                style_docx_table(t, header=True, font_size=7)
                add_docx_footer(doc)
                save_docx_validated(doc, path_docx)
                QMessageBox.information(self, "Export", f"Excel and Word registers saved:\n{path_xlsx}\n{path_docx}")
            except Exception as exc:
                logging.exception("Category Word export failed")
                QMessageBox.information(self, "Export", f"Excel saved:\n{path_xlsx}\n\nWord export skipped: {exc}")

        def open_category_registration(category_code, parent_page):
            # category_code I = Internal; E = External (subtype Client/TPI/Certification/Vendor)
            dlg = QDialog(self)
            dlg.setWindowTitle("Register Internal Training" if category_code == "I" else "Register External Training")
            dlg.setMinimumWidth(540)
            form = QFormLayout(dlg)
            employee_combo = QComboBox()
            employee_rows = db.fetchall("SELECT id,employee_id,name,designation FROM employees WHERE COALESCE(active,1)=1 ORDER BY name COLLATE NOCASE")
            for e in employee_rows:
                employee_combo.addItem(f"{safe(e['employee_id'])} — {safe(e['name'])} ({safe(e['designation'])})", int(e["id"]))
            course_combo = QComboBox()
            if category_code == "I":
                courses = db.fetchall("SELECT id,course_name,validity_months FROM training_courses WHERE COALESCE(active,1)=1 AND COALESCE(training_type,'I')='I' ORDER BY course_name COLLATE NOCASE")
            else:
                courses = db.fetchall("SELECT id,course_name,validity_months FROM training_courses WHERE COALESCE(active,1)=1 AND COALESCE(training_type,'I') IN ('E','C') ORDER BY course_name COLLATE NOCASE")
            for c in courses:
                course_combo.addItem(safe(c["course_name"]), (int(c["id"]), int(c["validity_months"] or 0)))
            subtype = QComboBox()
            if category_code != "I":
                subtype.addItems(["External — General", "Client Training", "TPI / Third Party", "Certification Body", "Vendor / Supplier", "Regulatory / Authority"])
            provider = QLineEdit(); provider.setPlaceholderText("Training provider / trainer / certifying body")
            cert = QLineEdit(); cert.setPlaceholderText("Certificate / reference number")
            training_date = QDateEdit(QDate.currentDate()); training_date.setCalendarPopup(True); training_date.setDisplayFormat("yyyy-MM-dd")
            expiry_date = QDateEdit(QDate.currentDate().addMonths(24)); expiry_date.setCalendarPopup(True); expiry_date.setDisplayFormat("yyyy-MM-dd")
            no_expiry = QCheckBox("No expiry")
            notes = QLineEdit()
            form.addRow("Employee *", employee_combo)
            form.addRow("Training course *", course_combo)
            if category_code != "I":
                form.addRow("External type", subtype)
            form.addRow("Provider", provider); form.addRow("Completion date *", training_date)
            form.addRow("Expiry date", expiry_date); form.addRow("No expiry", no_expiry)
            form.addRow("Certificate / reference", cert); form.addRow("Notes", notes)
            buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel); form.addRow(buttons)

            def save_reg():
                if employee_combo.currentData() is None or course_combo.currentData() is None:
                    return QMessageBox.warning(dlg, "Required", "Select employee and training course.")
                emp_id = int(employee_combo.currentData())
                course_id, months = course_combo.currentData()
                exp = "" if no_expiry.isChecked() else expiry_date.date().toString("yyyy-MM-dd")
                note_text = notes.text().strip()
                if category_code != "I":
                    note_text = (subtype.currentText() + ("; " + note_text if note_text else "")).strip()
                # Map Client subtype to training_type C on course if needed is already set on course
                db.execute(
                    "INSERT INTO training_records (employee_db_id, course_id, training_date, expiry_date, provider, certificate_no, notes, verification_status) VALUES (?,?,?,?,?,?,?,?)",
                    (emp_id, course_id, training_date.date().toString("yyyy-MM-dd"), exp, provider.text().strip(), cert.text().strip(), note_text, "Verified")
                )
                try:
                    db.execute("INSERT INTO training_audit_log (entity_type, entity_id, action, details) VALUES (?,?,?,?)",
                               ("training_record", course_id, "Registered", f"Employee {emp_id} course {course_id}"))
                except Exception:
                    pass
                dlg.accept(); refresh_category_registers(); refresh_master_training_register()
            buttons.accepted.connect(save_reg); buttons.rejected.connect(dlg.reject)
            dlg.exec()


        def delete_category_record(table):
            row = table.currentRow()
            if row < 0 or not table.item(row, 0):
                return QMessageBox.information(self, "Select Record", "Select a training record row first.")
            rid = table.item(row, 0).data(Qt.ItemDataRole.UserRole)
            if not rid:
                return QMessageBox.warning(self, "Delete", "Could not identify the selected record.")
            if QMessageBox.question(self, "Delete Training Record",
                    "Permanently delete this training record from the register?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
                return
            try:
                db.execute("DELETE FROM training_records WHERE id=?", (int(rid),))
                try:
                    db.execute("INSERT INTO training_audit_log (entity_type, entity_id, action, details) VALUES (?,?,?,?)",
                               ("training_record", int(rid), "Deleted", "Deleted from category register"))
                except Exception:
                    pass
                refresh_category_registers()
                refresh_master_training_register()
                try:
                    load_tracker()
                except Exception:
                    pass
                QMessageBox.information(self, "Deleted", "Training record deleted.")
            except Exception as exc:
                logging.exception("Delete training record failed")
                QMessageBox.critical(self, "Delete Failed", str(exc))

        # Internal register
        page_i = QWidget(); pl_i = QVBoxLayout(page_i); tools_i = QHBoxLayout()
        add_i = QPushButton("Register Internal Training"); ref_i = QPushButton("Refresh"); del_i = QPushButton("Delete Selected"); exp_i = QPushButton("Export Word / Excel")
        tools_i.addWidget(add_i); tools_i.addWidget(ref_i); tools_i.addWidget(del_i); tools_i.addWidget(exp_i); tools_i.addStretch(); pl_i.addLayout(tools_i)
