        # External register (merged External + Client + TPI + Certification)
        page_e = QWidget(); pl_e = QVBoxLayout(page_e); tools_e = QHBoxLayout()
        add_e = QPushButton("Register External Training"); ref_e = QPushButton("Refresh"); del_e = QPushButton("Delete Selected"); exp_e = QPushButton("Export Word / Excel")
        tools_e.addWidget(add_e); tools_e.addWidget(ref_e); tools_e.addWidget(del_e); tools_e.addWidget(exp_e); tools_e.addStretch(); pl_e.addLayout(tools_e)
        hint_e = QLabel("External Training Register includes Client training, TPI, Certification body, Vendor and Regulatory external courses.")
        hint_e.setWordWrap(True); hint_e.setStyleSheet("color:#17365D;padding:4px;"); pl_e.addWidget(hint_e)
        table_e = QTableWidget(0,11)
        table_e.setHorizontalHeaderLabels(["Employee ID","Name","Trade / Designation","Company","Training Name","Type (External/Client/TPI/…)","Provider","Completion Date","Expiry Date","Certificate / Ref.","Status"])
        table_e.setAlternatingRowColors(True); table_e.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table_e.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.ResizeToContents); table_e.horizontalHeader().setStretchLastSection(True)
        pl_e.addWidget(table_e,1)
        category_pages["E"] = page_e; category_tables["E"] = table_e
        add_e.clicked.connect(lambda _=False: open_category_registration("E", page_e))
        ref_e.clicked.connect(refresh_category_registers)
        del_e.clicked.connect(lambda: delete_category_record(table_e))
        exp_e.clicked.connect(lambda: export_category_register("E", table_e, "External Training Register"))

        # Master Training Register: one employee per row; click a row for the full record.
        master_page = QWidget(); master_layout = QVBoxLayout(master_page)
        master_tools = QHBoxLayout(); master_search = QLineEdit(); master_search.setPlaceholderText("Search ID, name, designation or company…"); master_search.setClearButtonEnabled(True)
        master_refresh = QPushButton("Refresh"); master_export = QPushButton("Export Register (Excel)")
        master_tools.addWidget(master_search,1); master_tools.addWidget(master_refresh); master_tools.addWidget(master_export); master_layout.addLayout(master_tools)
        master_table = QTableWidget(0,10); master_table.setHorizontalHeaderLabels(["S.No.","ID","Name","Designation","Company","External Attended / Required","Internal Attended / Required","Mandatory Training Completed %","Due in 1 Month","Due in 2 Months"]); master_table.setAlternatingRowColors(True); master_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers); master_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows); master_table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection); master_table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.ResizeToContents); master_table.horizontalHeader().setStretchLastSection(True); master_layout.addWidget(master_table,1)

        master_employees = []
        def refresh_master_training_register(*_):
            sync_all_training_assignments()
            needle = master_search.text().strip().casefold()
            employees = db.fetchall("SELECT id,employee_id,name,designation,company FROM employees WHERE COALESCE(active,1)=1 ORDER BY name COLLATE NOCASE")
            employees = [e for e in employees if not needle or needle in " ".join(safe(e[k]).casefold() for k in ("employee_id","name","designation","company"))]
            master_employees[:] = employees
            master_table.setRowCount(len(employees))
            today_date = date.today()
            for ri, emp in enumerate(employees):
                reqs = requirements_for_trade(emp["designation"])
                ext_req = [(cname,req,val) for cname,req,val in reqs if grid_state["types"].get(cname,"I")=="E"]
                int_req = [(cname,req,val) for cname,req,val in reqs if grid_state["types"].get(cname,"I")!="E"]
                def _attended(items):
                    att = 0
                    for cname, req, validity in items:
                        st, _, _ = status_of(latest_record(emp["id"], cname), validity)
                        if st in ("Valid", "Expiring Soon"):
                            att += 1
                    return att
                ext_att = _attended(ext_req)
                int_att = _attended(int_req)
                ext_txt = f"{ext_att}/{len(ext_req)}"
                int_txt = f"{int_att}/{len(int_req)}"
                mandatory = [(cname,req,val) for cname,req,val in reqs if req in ("Mandatory","Before Job")]
                done = 0; due30 = 0; due60 = 0
                for cname, req, validity in mandatory:
                    rec = latest_record(emp["id"], cname); st, _, exp = status_of(rec, validity)
                    if st in ("Valid","Expiring Soon"): done += 1
                    if exp:
                        try:
                            days = (date.fromisoformat(exp) - today_date).days
                            if 0 <= days <= 30: due30 += 1
                            elif 31 <= days <= 60: due60 += 1
                        except Exception: pass
                pct = "N/A" if not mandatory else f"{int(round(done*100/len(mandatory)))}%"
                vals = [ri+1,safe(emp["employee_id"]),safe(emp["name"]),safe(emp["designation"]),safe(emp["company"]),ext_txt,int_txt,pct,due30,due60]
                for ci,val in enumerate(vals):
                    it=QTableWidgetItem(str(val)); master_table.setItem(ri,ci,it)
                master_table.item(ri,1).setData(Qt.ItemDataRole.UserRole,int(emp["id"]))

        def show_employee_training_detail(row, _column=0):
            if row < 0 or row >= len(master_employees): return
            emp = master_employees[row]
            emp_full = db.fetchone("SELECT * FROM employees WHERE id=?", (int(emp["id"]),)) or emp
            dlg = QDialog(self)
            dlg.setWindowTitle(f"Personal Training Register — {safe(emp_full['name'])}")
            dlg.resize(1180, 720)
            dl = QVBoxLayout(dlg)

            # ---- Compact profile: row1 ID/Name/Trade/Company | row2 Contact/Join/Induction | photo right ----
            profile_box = QGroupBox("Employee Profile")
            profile_outer = QHBoxLayout(profile_box)
            form_w = QWidget()
            form = QGridLayout(form_w)
            form.setHorizontalSpacing(10)
            form.setVerticalSpacing(6)
            def _ro(val):
                le = QLineEdit(safe(val)); le.setReadOnly(True); le.setMinimumWidth(120); return le
            join_date = safe(emp_full["date_joining"]) if "date_joining" in emp_full.keys() else ""
            induction = safe(emp_full["safety_induction_date"]) if "safety_induction_date" in emp_full.keys() else ""
            contact = safe(emp_full["contact"]) if "contact" in emp_full.keys() else ""
            form.addWidget(QLabel("ID"), 0, 0); form.addWidget(_ro(emp_full["employee_id"]), 0, 1)
            form.addWidget(QLabel("Name"), 0, 2); form.addWidget(_ro(emp_full["name"]), 0, 3)
            form.addWidget(QLabel("Designation"), 0, 4); form.addWidget(_ro(emp_full["designation"]), 0, 5)
            form.addWidget(QLabel("Company"), 0, 6); form.addWidget(_ro(emp_full["company"]), 0, 7)
            form.addWidget(QLabel("Contact"), 1, 0); form.addWidget(_ro(contact), 1, 1)
            form.addWidget(QLabel("Date of Joining"), 1, 2); form.addWidget(_ro(join_date), 1, 3)
            form.addWidget(QLabel("Induction Date"), 1, 4); form.addWidget(_ro(induction), 1, 5)
            profile_outer.addWidget(form_w, 1)
            photo_label = QLabel()
            photo_label.setFixedSize(100, 120)
            photo_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            photo_label.setStyleSheet("border:1px solid #C8D5E3; background:#F7FAFC;")
            photo_path = ""
            try:
                photo_path = safe(emp_full["photo_path"]) if "photo_path" in emp_full.keys() else ""
            except Exception:
                photo_path = ""
            if photo_path and Path(photo_path).exists():
                try:
                    pix = QPixmap(photo_path)
                    photo_label.setPixmap(pix.scaled(96, 116, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation))
                except Exception:
                    photo_label.setText("No photo")
            else:
                photo_label.setText("No photo")
            profile_outer.addWidget(photo_label, 0, Qt.AlignmentFlag.AlignTop)
            dl.addWidget(profile_box)

            # ---- Personal training register (Internal + External combined) ----
            reg_box = QGroupBox("Personal Training Register (Internal + External / Client / TPI / Certification)")
            reg_layout = QVBoxLayout(reg_box)
            detail = QTableWidget(0, 10)
            detail.setHorizontalHeaderLabels([
                "S.No.", "Training Name", "Type (Internal / External)", "Provider",
                "Completion Date", "Expiry Date", "Certificate / Ref.", "Status", "Requirement", "Notes"
            ])
            detail.setAlternatingRowColors(True)
            detail.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            detail.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.ResizeToContents)
            detail.horizontalHeader().setStretchLastSection(True)
            reg_layout.addWidget(detail, 1)
            dl.addWidget(reg_box, 1)

            detail_rows = []
            assigned_names = set()
            for cname, requirement, validity in requirements_for_trade(emp_full["designation"]):
                rec = latest_record(emp_full["id"], cname)
                course_meta = db.fetchone(
                    "SELECT training_type FROM training_courses WHERE lower(course_name)=lower(?) ORDER BY active DESC,id DESC LIMIT 1",
                    (cname,)
                )
                ttype = safe(course_meta["training_type"] if course_meta else "I")
                type_label = {"I": "Internal", "E": "External", "C": "Client / External"}.get(ttype, ttype)
                st, _, exp = status_of(rec, validity)
                detail_rows.append([
                    cname, type_label,
                    safe(rec["provider"]) if rec else "",
                    safe(rec["training_date"]) if rec else "",
                    safe(rec["expiry_date"]) if rec else "",
                    safe(rec["certificate_no"]) if rec else "",
                    st, safe(requirement),
                    safe(rec["notes"]) if rec and "notes" in rec.keys() else ""
                ])
                assigned_names.add(cname.casefold())
            records = db.fetchall("""SELECT tr.id AS id,tr.course_id AS course_id,c.course_name,c.training_type,c.validity_months,
                tr.provider,tr.training_date,tr.expiry_date,tr.certificate_no,tr.verification_status,tr.assessment_result,tr.notes
                FROM training_records tr JOIN training_courses c ON c.id=tr.course_id WHERE tr.employee_db_id=?
                ORDER BY tr.training_date DESC,tr.id DESC""", (emp_full["id"],))
            for rec in records:
                if safe(rec["course_name"]).casefold() in assigned_names:
                    continue
                ttype = safe(rec["training_type"] or "I")
                type_label = {"I": "Internal", "E": "External", "C": "Client / External"}.get(ttype, ttype)
                st, _, exp = status_of(rec, int(rec["validity_months"] or 0))
                detail_rows.append([
                    safe(rec["course_name"]), type_label, safe(rec["provider"]),
                    safe(rec["training_date"]), safe(rec["expiry_date"]), safe(rec["certificate_no"]),
                    st, "Recorded", safe(rec["notes"]) if "notes" in rec.keys() else ""
                ])
            detail.setRowCount(len(detail_rows))
            for ri, vals in enumerate(detail_rows):
                detail.setItem(ri, 0, QTableWidgetItem(str(ri + 1)))
                for ci, val in enumerate(vals):
                    detail.setItem(ri, ci + 1, QTableWidgetItem(safe(val)))
                # colour status column
                st_item = detail.item(ri, 7)
                if st_item:
                    bg, fg = color_status(vals[6])
                    st_item.setBackground(QBrush(bg)); st_item.setForeground(QBrush(fg))

            btn_row = QHBoxLayout()
            export_btn = QPushButton("Export Personal Register (Excel)")
            close_btn = QPushButton("Close")
            def export_personal():
                out, _ = QFileDialog.getSaveFileName(dlg, "Export Personal Training Register", f"Personal_Training_{safe(emp_full['employee_id'])}.xlsx", "Excel Workbook (*.xlsx)")
                if not out:
                    return
                if not out.lower().endswith(".xlsx"):
                    out += ".xlsx"
                wb = Workbook(); ws = wb.active; ws.title = "Personal Training"
                report_no = f"{document_prefix()}-TRN-PR-{datetime.now().strftime('%Y%m%d%H%M%S')}"
                form_no = f"{document_prefix()}-TRN-F02"
                # Header block
                ws.merge_cells("A1:H1")
                ws["A1"] = "PERSONAL TRAINING REGISTER"
                ws["A1"].font = Font(name="Arial", size=16, bold=True, color="FFFFFF")
                ws["A1"].fill = PatternFill("solid", fgColor="17365D")
                ws["A1"].alignment = Alignment(horizontal="center", vertical="center")
                ws.row_dimensions[1].height = 28
                ws.merge_cells("A2:D2"); ws["A2"] = f"Company: {company_name()}"
                ws.merge_cells("E2:H2"); ws["E2"] = f"Document No.: {report_no}"
                ws["E2"].alignment = Alignment(horizontal="right")
                ws.merge_cells("A3:D3"); ws["A3"] = f"Project: {db.setting('project_name','')}"
                ws.merge_cells("E3:H3"); ws["E3"] = f"Form No.: {form_no}    Date: {datetime.now().strftime('%Y-%m-%d')}"
                ws["E3"].alignment = Alignment(horizontal="right")
                for r in (2, 3):
                    for c in range(1, 9):
                        ws.cell(r, c).font = Font(name="Arial", size=9, bold=True, color="17365D")
                logo = report_logo_path()
                if logo and Path(logo).exists():
                    try:
                        img = XLImage(str(logo)); img.width = 90; img.height = 45
                        ws.add_image(img, "A1")
                    except Exception:
                        pass
                ws.append([])
                ws.append(["Employee ID", safe(emp_full["employee_id"]), "Name", safe(emp_full["name"]), "Designation", safe(emp_full["designation"]), "Company", safe(emp_full["company"])])
                for cell in ws[ws.max_row]:
                    cell.font = Font(bold=True)
                headers = [detail.horizontalHeaderItem(c).text() for c in range(detail.columnCount())]
                ws.append(headers)
                hdr_row = ws.max_row
                for cell in ws[hdr_row]:
                    cell.font = Font(bold=True, color="FFFFFF"); cell.fill = PatternFill("solid", fgColor="17365D")
                    cell.alignment = Alignment(wrap_text=True, horizontal="center")
                for r in range(detail.rowCount()):
                    ws.append([detail.item(r, c).text() if detail.item(r, c) else "" for c in range(detail.columnCount())])
                from openpyxl.utils import get_column_letter
                for col in ws.columns:
                    letter = get_column_letter(col[0].column)
                    ws.column_dimensions[letter].width = min(max(12, max(len(str(c.value or "")) for c in col) + 2), 28)
                wb.save(out)
                QMessageBox.information(dlg, "Export", f"Personal training register exported:\n{out}")

            export_btn.clicked.connect(export_personal)
            close_btn.clicked.connect(dlg.accept)
            btn_row.addWidget(export_btn); btn_row.addStretch(); btn_row.addWidget(close_btn)
            dl.addLayout(btn_row)
            dlg.exec()

        def export_master_training_register():
            path,_=QFileDialog.getSaveFileName(self,"Export Master Training Register","Master_Training_Register.xlsx","Excel Workbook (*.xlsx)")
            if not path:return
            if not path.lower().endswith(".xlsx"): path += ".xlsx"
            refresh_master_training_register()
            wb=Workbook(); ws=wb.active; ws.title="Master Register"
            ws.append([master_table.horizontalHeaderItem(c).text() for c in range(master_table.columnCount())])
            for r in range(master_table.rowCount()): ws.append([master_table.item(r,c).text() if master_table.item(r,c) else "" for c in range(master_table.columnCount())])
            for cell in ws[1]: cell.font=Font(bold=True,color="FFFFFF"); cell.fill=PatternFill("solid",fgColor="17365D"); cell.alignment=Alignment(wrap_text=True)
            ws.freeze_panes="A2"; ws.auto_filter.ref=ws.dimensions
            from openpyxl.utils import get_column_letter
            for col in ws.columns:
                letter=get_column_letter(col[0].column); ws.column_dimensions[letter].width=min(max(max(len(str(c.value or "")) for c in col)+2,12),32)
            wb.save(path); QMessageBox.information(self,"Export",f"Master Training Register exported:\n{path}")

        master_table.cellClicked.connect(show_employee_training_detail)
