        self.app_returned_permit.setSizePolicy(self.app_returned_permit.sizePolicy().horizontalPolicy(), self.app_returned_permit.sizePolicy().verticalPolicy())
        load_returned_btn = QPushButton("Retrieve / Edit Permit")
