CHEM_STORAGE_GROUPS = [
    "Flammable Liquid", "Flammable Gas", "Flammable Solid", "Oxidizer", "Corrosive - Acid", "Corrosive - Base",
    "Toxic / Poison", "Compressed Gas (Inert)", "Water-Reactive", "Peroxide / Self-Reactive",
    "Environmental Hazard", "Non-Hazardous / Other",
]
CHEM_GHS = ["Flammable", "Oxidizing", "Explosive", "Compressed Gas", "Corrosive",
            "Acute Toxic", "Health Hazard", "Irritant", "Environmental Hazard"]
CHEM_INCOMPAT = {
    frozenset(["Flammable Liquid", "Oxidizer"]): "Fire/explosion risk - oxidizer feeds flammable fire",
    frozenset(["Flammable Solid", "Oxidizer"]): "Fire/explosion risk - oxidizer feeds flammable solid fire",
    frozenset(["Flammable Gas", "Oxidizer"]): "Fire/explosion risk - oxidizer feeds flammable gas fire",
    frozenset(["Flammable Liquid", "Corrosive - Acid"]): "Strong acids can ignite or react with flammables",
    frozenset(["Corrosive - Acid", "Corrosive - Base"]): "Violent exothermic neutralisation if mixed",
    frozenset(["Corrosive - Acid", "Toxic / Poison"]): "Acids can release toxic gas (e.g. cyanide, sulphide)",
    frozenset(["Oxidizer", "Corrosive - Acid"]): "Acid + oxidizer can release toxic/oxidizing gas",
    frozenset(["Water-Reactive", "Corrosive - Acid"]): "Water-reactive material reacts with aqueous acid",
    frozenset(["Water-Reactive", "Corrosive - Base"]): "Water-reactive material reacts with aqueous base",
    frozenset(["Water-Reactive", "Oxidizer"]): "Water-reactive material + oxidizer: fire risk",
    frozenset(["Peroxide / Self-Reactive", "Flammable Liquid"]): "Peroxide decomposition can ignite flammables",
    frozenset(["Peroxide / Self-Reactive", "Corrosive - Acid"]): "Acid can trigger peroxide decomposition",
}
CHEM_SDS_REVIEW_YEARS = 5      # default review interval - align with site/client rule
CHEM_DUE_SOON_DAYS = 90


def chem_conflicts(items):
    """items: dicts with name, storage_location, storage_group. Returns co-location conflicts."""
    out, by_loc = [], {}
    for it in items:
        loc = (it.get("storage_location") or "").strip().lower()
        if loc:
            by_loc.setdefault(loc, []).append(it)
    for loc, group in by_loc.items():
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                a, b = group[i], group[j]
                reason = CHEM_INCOMPAT.get(frozenset([a.get("storage_group", ""), b.get("storage_group", "")]))
                if reason:
                    out.append((a["storage_location"], a["name"], a["storage_group"], b["name"], b["storage_group"], reason))
    return out


def chem_sds_state(sds_row, today_iso):
    """Return Missing / Expired / Due Soon / Current for a chemical's latest current SDS."""
    if not sds_row:
        return "Missing"
    due = (sds_row["review_due_date"] or "").strip()
    if not due:
        return "Current"
    if due < today_iso:
        return "Expired"
    soon = (datetime.strptime(today_iso, "%Y-%m-%d") + timedelta(days=CHEM_DUE_SOON_DAYS)).strftime("%Y-%m-%d")
    return "Due Soon" if due <= soon else "Current"


# ---------------- SDS auto-reader (PDF / DOCX -> register fields) ----------------
_CHEM_SEC_KEYS = {
    1: ("identification", "product identifier"), 2: ("hazard",), 3: ("composition", "ingredient"),
    4: ("first",), 5: ("fire",), 6: ("accidental", "release"), 7: ("handling", "storage"),
    8: ("exposure", "protection"), 9: ("physical",), 10: ("stability", "reactivity"),
    11: ("toxicolog",), 12: ("ecolog",), 13: ("disposal",), 14: ("transport",),
    15: ("regulat",), 16: ("other",),
}
_CHEM_H_GROUPS = [
    ("Explosive", {"H200", "H201", "H202", "H203", "H204", "H205", "H240", "H241"}),
    ("Flammable", {"H220", "H221", "H222", "H223", "H224", "H225", "H226", "H228", "H229", "H242", "H250", "H260", "H261"}),
    ("Oxidizing", {"H270", "H271", "H272"}),
    ("Compressed Gas", {"H280", "H281"}),
    ("Corrosive", {"H290", "H314", "H318"}),
    ("Acute Toxic", {"H300", "H301", "H310", "H311", "H330", "H331"}),
    ("Health Hazard", {"H304", "H334", "H340", "H341", "H350", "H351", "H360", "H361", "H362", "H370", "H371", "H372", "H373"}),
    ("Irritant", {"H302", "H312", "H315", "H317", "H319", "H332", "H335", "H336"}),
    ("Environmental Hazard", {"H400", "H410", "H411"}),
]


def chem_file_text(path):
    """Extract selectable text from SDS PDF/DOCX files using installed readers."""
    path = Path(path)
    ext = path.suffix.lower()
    if ext == ".pdf":
        if not path.is_file():
            raise RuntimeError(f"PDF file not found: {path}")
        try:
            with path.open("rb") as stream:
                signature = stream.read(8)
            if b"%PDF-" not in signature:
                raise RuntimeError("The selected file does not have a valid PDF header. Re-save it as a PDF and try again.")
        except OSError as exc:
            raise RuntimeError(f"Cannot read the PDF file: {exc}")

        errors = []
        # Try pypdf first. It is the reader the user has installed and is
        # independent of optional Qt PDF modules bundled with the application.
        try:
            from pypdf import PdfReader
            reader = PdfReader(str(path), strict=False)
            if reader.is_encrypted and not reader.decrypt(""):
                raise RuntimeError("This PDF is password-protected. Remove the password and try again.")
            page_text = []
            for page in reader.pages:
                try:
                    page_text.append(page.extract_text() or "")
                except Exception as page_exc:
                    errors.append(f"pypdf page extraction: {type(page_exc).__name__}: {page_exc}")
                    page_text.append("")
            extracted = "\n".join(page_text).strip()
            if extracted:
                return extracted
            errors.append("pypdf opened the PDF but found no selectable text; it may be scanned/image-only.")
        except Exception as exc:
            errors.append(f"pypdf: {type(exc).__name__}: {exc}")

        # Compatibility fallbacks for systems where the app runtime has a
        # different set of installed PDF packages.
        try:
            from PyPDF2 import PdfReader
            reader = PdfReader(str(path), strict=False)
            if reader.is_encrypted and not reader.decrypt(""):
                raise RuntimeError("This PDF is password-protected. Remove the password and try again.")
            extracted = "\n".join((page.extract_text() or "") for page in reader.pages).strip()
            if extracted:
                return extracted
            errors.append("PyPDF2 opened the PDF but found no selectable text.")
        except Exception as exc:
            errors.append(f"PyPDF2: {type(exc).__name__}: {exc}")
        try:
            import fitz
            with fitz.open(str(path)) as pdf:
                if getattr(pdf, "needs_pass", False) and not pdf.authenticate(""):
                    raise RuntimeError("This PDF is password-protected. Remove the password and try again.")
                extracted = "\n".join(page.get_text("text") or "" for page in pdf).strip()
            if extracted:
                return extracted
            errors.append("PyMuPDF opened the PDF but found no selectable text.")
        except Exception as exc:
            errors.append(f"PyMuPDF: {type(exc).__name__}: {exc}")
        try:
            import pdfplumber
            with pdfplumber.open(str(path)) as pdf:
                extracted = "\n".join(page.extract_text() or "" for page in pdf.pages).strip()
            if extracted:
                return extracted
            errors.append("pdfplumber opened the PDF but found no selectable text.")
        except Exception as exc:
            errors.append(f"pdfplumber: {type(exc).__name__}: {exc}")
        try:
            from pdfminer.high_level import extract_text
            extracted = (extract_text(str(path)) or "").strip()
            if extracted:
                return extracted
            errors.append("pdfminer opened the PDF but found no selectable text.")
        except Exception as exc:
            errors.append(f"pdfminer: {type(exc).__name__}: {exc}")

        # QtPdf is a final fallback for deployments that bundle QtPdf.
        try:
            from PySide6.QtPdf import QPdfDocument
            pdf = QPdfDocument()
            pdf.load(str(path))
            if int(pdf.pageCount()) <= 0:
                raise RuntimeError("QtPdf reports that the PDF has no pages.")
            # QtPdf versions differ in their text API; use it only if the
            # installed binding exposes a supported whole-page text method.
            page_text = []
            for page_no in range(int(pdf.pageCount())):
                if hasattr(pdf, "getPageText"):
                    selection = pdf.getPageText(page_no)
                    page_text.append(selection.text() if hasattr(selection, "text") else str(selection or ""))
                elif hasattr(pdf, "getSelection"):
                    # PySide6 QPdfDocument.getSelection requires THREE
                    # arguments: page number, start QPointF and end QPointF.
                    # The previous QRectF/two-argument call raised:
                    # "getSelection expected 3 arguments, got 2".
                    from PySide6.QtCore import QPointF
                    page_size = pdf.pagePointSize(page_no)
                    if page_size is None:
                        raise RuntimeError(f"QtPdf could not determine the size of page {page_no + 1}.")
                    start_point = QPointF(0.0, 0.0)
                    end_point = QPointF(float(page_size.width()), float(page_size.height()))
                    selection = pdf.getSelection(page_no, start_point, end_point)
                    page_text.append(selection.text() if hasattr(selection, "text") else "")
                else:
                    raise RuntimeError("This QtPdf version does not expose PDF text extraction.")
            extracted = "\n".join(page_text).strip()
            if extracted:
                return extracted
            errors.append("QtPdf opened the PDF but found no selectable text.")
        except Exception as exc:
            errors.append(f"QtPdf: {type(exc).__name__}: {exc}")

        details = " | ".join(errors)
        if any("no selectable text" in e.lower() or "scanned/image-only" in e.lower() for e in errors):
            raise RuntimeError(
                "The PDF reader opened the file, but no selectable text was found. This SDS is likely a scanned/image-only PDF; "
                "it requires OCR before automatic field extraction. Reader diagnostics: " + details
            )
        if getattr(sys, "frozen", False):
            runtime_help = (
                "This is a packaged HSE EXE. Installing pypdf with pip into another Python installation "
                "does not add it to this EXE. Rebuild the HSE application from this updated main.py using "
                "the same project build configuration, with pypdf installed in the build Python and "
                "PyInstaller options --collect-all pypdf --hidden-import pypdf. "
                "If this message still reports the old QtPdf getSelection argument error, the EXE being "
                "launched was built from an older main.py; close it and rebuild/redeploy the EXE. "
            )
        else:
            runtime_help = (
                "Install pypdf into this exact Python environment with: "
                f'"{sys.executable}" -m pip install --upgrade pypdf. '
            )
        raise RuntimeError(
            "No PDF reader in the HSE application's running Python environment could extract this file. "
            f"Python executable: {sys.executable}; Python version: {sys.version.split()[0]}. "
            + runtime_help + "Reader diagnostics: " + details
        )

    if ext == ".docx":
        try:
            d = Document(str(path))
        except Exception as exc:
            raise RuntimeError(f"Could not open this Word document: {exc}")
        parts = []
        def append_table(table):
            for row in table.rows:
                cells = []
                for cell in row.cells:
                    value = " ".join(x.strip() for x in cell.text.splitlines() if x.strip())
                    if value and value not in cells:
                        cells.append(value)
                if cells:
                    parts.append(" | ".join(cells))
        for paragraph in d.paragraphs:
            value = paragraph.text.strip()
            if value:
                parts.append(value)
        for table in d.tables:
            append_table(table)
        for section in d.sections:
            for part in (section.header, section.footer):
                for paragraph in part.paragraphs:
                    value = paragraph.text.strip()
                    if value:
                        parts.append(value)
                for table in part.tables:
                    append_table(table)
        return "\n".join(parts)
    raise RuntimeError("Unsupported SDS file type. Please select a PDF or DOCX file.")


def chem_split_sections(text):
    lines = text.splitlines(); marks = []
    for i, ln in enumerate(lines):
        m = re.match(r"^\s*(?:section|sec\.?)?\s*(\d{1,2})\s*[:.\-–—)]?\s+([A-Za-z][^\n]{2,90})$", ln, re.I)
        if m:
            n = int(m.group(1)); title = m.group(2).lower()
            if 1 <= n <= 16 and any(k in title for k in _CHEM_SEC_KEYS[n]):
                marks.append((i, n))
    bodies = {}
    for idx, (i, n) in enumerate(marks):
        end = marks[idx + 1][0] if idx + 1 < len(marks) else len(lines)
        body = "\n".join(lines[i + 1:end])
        if len(body) > len(bodies.get(n, "")):
            bodies[n] = body
    return bodies


def chem_label_value(text, labels, maxlen=140):
    """Find 'Label : value' (same line first, then value on the next line), label by label in priority order."""
    lines = text.splitlines()
    clean = lambda v: v.lstrip(" :.-–—\t").rstrip(" :-–—\t")
    for lab in labels:
        pat = re.compile(r"^[ \t]*(?:%s)\b[ \t]*[:\-–—]?[ \t]*(.*)$" % lab, re.I)
        for ln in lines:
            m = pat.match(ln)
            if m:
                v = clean(m.group(1))
                if v and not v.endswith(":"):
                    return v[:maxlen]
        for i, ln in enumerate(lines):
            m = pat.match(ln)
            if m and not clean(m.group(1)):
                for nxt in lines[i + 1:i + 3]:
                    nv = nxt.strip()
                    if nv and not nv.endswith(":"):
                        return nv[:maxlen]
    return ""


def chem_parse_date(s):
    """Return ISO yyyy-mm-dd or ''. Numeric dd/mm/yyyy is read day-first unless impossible."""
    s = s or ""
    months = {m: i for i, m in enumerate(["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"], 1)}

    def ok(y, mo, d):
        try:
            return datetime(int(y), int(mo), int(d)).strftime("%Y-%m-%d")
        except Exception:
            return ""
    m = re.search(r"\b(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\b", s)
    if m and ok(*m.groups()):
        return ok(*m.groups())
    m = re.search(r"\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b", s)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), m.group(3)
        if b > 12 and a <= 12:
            a, b = b, a
        if ok(y, b, a):
            return ok(y, b, a)
    m = re.search(r"\b(\d{1,2})(?:st|nd|rd|th)?[\s\-]+([A-Za-z]{3,9})\.?,?[\s\-]+(\d{4})\b", s)
    if m and m.group(2)[:3].lower() in months and ok(m.group(3), months[m.group(2)[:3].lower()], m.group(1)):
        return ok(m.group(3), months[m.group(2)[:3].lower()], m.group(1))
    m = re.search(r"\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b", s)
    if m and m.group(1)[:3].lower() in months and ok(m.group(3), months[m.group(1)[:3].lower()], m.group(2)):
        return ok(m.group(3), months[m.group(1)[:3].lower()], m.group(2))
    return ""


def _chem_cas_valid(cas):
    digits = cas.replace("-", "")
    body, check = digits[:-1], int(digits[-1])
    return sum(int(d) * (i + 1) for i, d in enumerate(reversed(body))) % 10 == check


def _chem_clean(body, maxlen):
    out = []
    for ln in (body or "").splitlines():
        ln = re.sub(r"^\s*\d{1,2}\.\d{1,2}(?:\.\d{1,2})?\s*", "", ln).strip()
        if ln:
            out.append(ln)
    t = " ".join(out)
    return t if len(t) <= maxlen else t[:maxlen].rsplit(" ", 1)[0] + " …"


def chem_ghs_from_h(codes):
    base = {re.match(r"H\d{3}", c).group(0) for c in codes if re.match(r"H\d{3}", c)}
    return [name for name, group in _CHEM_H_GROUPS if base & group]


def chem_infer_group(codes, blob):
    base = {re.match(r"H\d{3}", c).group(0) for c in codes if re.match(r"H\d{3}", c)}
    b = blob.lower()
    if base & {"H260", "H261"}: return "Water-Reactive"
    if base & {"H240", "H241", "H242"} or "organic peroxide" in b: return "Peroxide / Self-Reactive"
    if base & {"H270", "H271", "H272"}: return "Oxidizer"
    if base & {"H220", "H221", "H222", "H223"}: return "Flammable Gas"
    if base & {"H224", "H225", "H226"}: return "Flammable Liquid"
    if "H228" in base: return "Flammable Solid"
    if base & {"H314", "H290"}:
        acid = re.search(r"\bacid\b|acidic|hydrochloric|sulphuric|sulfuric|nitric|phosphoric", b)
        basek = re.search(r"hydroxide|caustic|\bammonia|\bamine|alkali|potash", b)
        if acid and not basek: return "Corrosive - Acid"
        if basek and not acid: return "Corrosive - Base"
        return ""
    if base & {"H300", "H301", "H310", "H311", "H330", "H331"}: return "Toxic / Poison"
    if base & {"H280", "H281"}: return "Compressed Gas (Inert)"
    if base & {"H400", "H410", "H411"}: return "Environmental Hazard"
    if base or "not classified" in b or "not a hazardous" in b or "non-hazardous" in b: return "Non-Hazardous / Other"
    return ""


def chem_parse_sds(text):
    """Best-effort read of a 16-section SDS. Returns dict of register fields (+ sds_* fields).
    Always verified by the user in the review dialog before saving."""
    text = text or ""
    sec = chem_split_sections(text)
    S = lambda n: sec.get(n, text)            # fall back to whole text if section not located
    out = {}
    s1 = S(1)
    name = chem_label_value(s1, [r"product\s*name", r"product\s*identifier", r"trade\s*name", r"substance\s*name", r"material\s*name"])
    if not name:
        for ln in text.splitlines():
            t = ln.strip()
            if t and not re.search(r"safety\s*data\s*sheet|msds|\bsds\b|page\s*\d|section\s*1", t, re.I):
                name = t[:120]; break
    out["product_name"] = name
    out["supplier"] = chem_label_value(s1, [r"manufacturer(?:\s*/\s*supplier)?", r"supplier", r"company(?:\s*name)?", r"distributor", r"registered\s*company"])
    out["supplier_contact"] = chem_label_value(s1, [r"emergency\s*(?:telephone|phone|tel\.?|contact|number)(?:\s*number)?", r"24[\s\-]*h(?:ou)?r\s*emergency[^:\n]*"])
    out["product_use"] = chem_label_value(s1, [r"recommended\s*use", r"relevant\s*identified\s*uses?", r"identified\s*uses?", r"product\s*use", r"use\s*of\s*the\s*(?:substance|mixture)(?:/mixture)?"])
    # hazards
    s2 = S(2)
    codes, hlines = [], []
    for m in re.finditer(r"\b(EUH\d{3}|H\d{3}[A-Z]{0,2})\b\s*[:\-–—]?\s*([^\n]{0,110})", s2):
        code = m.group(1)
        if code in codes: continue
        codes.append(code)
        desc = re.split(r"\b(?:EUH\d{3}|H\d{3}[A-Z]{0,2}|P\d{3})\b", m.group(2))[0].strip(" ,;.")
        hlines.append(f"{code} {desc}".strip() if desc and re.match(r"[A-Za-z]", desc) else code)
    out["h_statements"] = "\n".join(hlines)
    plines, pseen = [], set()
    for m in re.finditer(r"\b(P\d{3}(?:\s*\+\s*P\d{3})*)\b\s*[:\-–—]?\s*([^\n]{0,110})", s2):
        code = re.sub(r"\s+", "", m.group(1))
        if code in pseen: continue
        pseen.add(code)
        desc = re.split(r"\b(?:EUH\d{3}|H\d{3}[A-Z]{0,2}|P\d{3})\b", m.group(2))[0].strip(" ,;.")
        plines.append(f"{code} {desc}".strip() if desc and re.match(r"[A-Za-z]", desc) else code)
    out["p_statements"] = _chem_clean("\n".join(plines), 1500)
    m = re.search(r"signal\s*word\s*[:\-–—]?\s*(danger|warning)", s2, re.I)
    out["signal_word"] = m.group(1).capitalize() if m else ("None" if re.search(r"signal\s*word\s*[:\-–—]?\s*(none|no signal)", s2, re.I) else "")
    out["ghs_classes"] = ", ".join(chem_ghs_from_h(codes))
    out["storage_group"] = chem_infer_group(codes, " ".join([name, S(1), s2, S(3)])[:6000])
    # identifiers
    cas = []
    for c in re.findall(r"\b(\d{2,7}-\d{2}-\d)\b", S(3)) or re.findall(r"\b(\d{2,7}-\d{2}-\d)\b", text):
        if _chem_cas_valid(c) and c not in cas: cas.append(c)
    out["cas_number"] = ", ".join(cas[:4])
    m = re.search(r"\bUN[\s\-]*(?:number|no\.?)?[\s:\-]*(\d{4})\b", S(14), re.I)
    out["un_number"] = m.group(1) if m else ""
    ph = chem_label_value(S(9), [r"physical\s*state", r"appearance", r"form"], 80).lower()
    for kw, label in [("aerosol", "Aerosol"), ("gas", "Gas"), ("powder", "Powder"), ("paste", "Paste/Gel"), ("gel", "Paste/Gel"),
                      ("solid", "Solid"), ("liquid", "Liquid")]:
        if kw in ph:
            out["physical_state"] = label; break
    # response information
    out["first_aid"] = _chem_clean(sec.get(4, ""), 700)
    out["fire_fighting"] = _chem_clean(sec.get(5, ""), 600)
    out["spill_response"] = _chem_clean(sec.get(6, ""), 600)
    s8 = sec.get(8, ""); lines8 = s8.splitlines(); start = 0
    for i, ln in enumerate(lines8):
        if re.search(r"personal\s*protective|individual\s*protection|protective\s*equipment|eye/face|hand\s*protection", ln, re.I):
            start = i; break
    out["ppe_required"] = _chem_clean("\n".join(lines8[start:]), 700)
    out["disposal"] = _chem_clean(sec.get(13, ""), 500)
    stor = _chem_clean(sec.get(7, ""), 450)
    out["remarks"] = f"SDS s.7 storage: {stor}" if stor else ""
    # SDS document details
    out["sds_number"] = chem_label_value(text, [r"sds\s*(?:no\.?|number|id|code)", r"msds\s*(?:no\.?|number)", r"document\s*(?:no\.?|number)"], 60)
    out["sds_revision"] = chem_label_value(text, [r"revision\s*(?:no\.?|number)", r"version(?:\s*(?:no\.?|number))?(?!\s*date)", r"revision(?!\s*date)"], 30)
    for lab in [r"revision\s*date", r"date\s*of\s*(?:revision|issue|preparation|last\s*revision)", r"issue\s*date", r"date\s*issued",
                r"version\s*date", r"date\s*prepared", r"prepared\s*on"]:
        d = chem_parse_date(chem_label_value(text, [lab], 60))
        if d:
            out["sds_issue"] = d; break
    out.setdefault("sds_issue", "")
    out["sds_language"] = "English"
    return {k: (v if v is not None else "") for k, v in out.items()}


def chem_missing_fields(parsed):
    keys = [("product_name", "Product name"), ("supplier", "Supplier"), ("supplier_contact", "Emergency contact"),
            ("cas_number", "CAS"), ("signal_word", "Signal word"), ("h_statements", "H-statements"),
            ("storage_group", "Storage group"), ("sds_issue", "Issue date"), ("sds_revision", "Revision")]
    return [lab for k, lab in keys if not parsed.get(k)]


def chem_extract_sds_sections(text):
    """Return standard SDS sections 1-16 from selectable SDS text; retain source wording."""
    raw = (text or "").replace("\r", "\n")
    # Section headings normally begin with a numbered heading (e.g. 1. Identification).
    matches = list(re.finditer(r"(?im)^\s*(?:SECTION\s*)?(1[0-6]|[1-9])\s*(?:[.):\-]|\|)\s*([^\n]{2,150})", raw))
    out = []
    for i, m in enumerate(matches):
        n = int(m.group(1))
        if n < 1 or n > 16: continue
        end = matches[i+1].start() if i+1 < len(matches) else len(raw)
        content = raw[m.end():end].strip()
        title = m.group(2).strip()
        out.append((n, title, content[:30000]))
    # De-duplicate repeated page headers by keeping the longest captured block per section.
    best = {}
    for n,t,c in out:
        if n not in best or len(c) > len(best[n][1]): best[n] = (t,c)
    return [(n,best[n][0],best[n][1]) for n in range(1,17) if n in best]


class ChemicalSDSModule(QWidget):
    """Chemical Register + SDS Library + compatibility/alerts, mounted in the main stack."""

    def __init__(self, parent_window, db):
        super().__init__(parent_window)
        self.host = parent_window
        self.db = db
        self._ensure_schema()
        self._build_ui()
        self.refresh_all()

    # ---------- schema ----------
    def _ensure_schema(self):
        self.db.conn.executescript("""
        CREATE TABLE IF NOT EXISTS chem_products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_name TEXT NOT NULL,
            supplier TEXT DEFAULT '', supplier_contact TEXT DEFAULT '',
            cas_number TEXT DEFAULT '', un_number TEXT DEFAULT '',
            product_use TEXT DEFAULT '', physical_state TEXT DEFAULT '',
            storage_group TEXT DEFAULT '', storage_location TEXT DEFAULT '',
            ghs_classes TEXT DEFAULT '', signal_word TEXT DEFAULT '',
            h_statements TEXT DEFAULT '', p_statements TEXT DEFAULT '',
            quantity REAL DEFAULT 0, unit TEXT DEFAULT 'L',
            project TEXT DEFAULT '', department TEXT DEFAULT '',
            ppe_required TEXT DEFAULT '', first_aid TEXT DEFAULT '',
            spill_response TEXT DEFAULT '', fire_fighting TEXT DEFAULT '', disposal TEXT DEFAULT '',
            status TEXT DEFAULT 'Active',
            approved_by TEXT DEFAULT '', approval_date TEXT DEFAULT '', remarks TEXT DEFAULT '',
            created_at TEXT DEFAULT '', updated_at TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS chem_sds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            sds_number TEXT DEFAULT '', revision TEXT DEFAULT '',
            issue_date TEXT DEFAULT '', review_due_date TEXT DEFAULT '',
            language TEXT DEFAULT 'English', file_path TEXT DEFAULT '',
            status TEXT DEFAULT 'Current',
            uploaded_by TEXT DEFAULT '', uploaded_at TEXT DEFAULT '',
            FOREIGN KEY(product_id) REFERENCES chem_products(id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS chem_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER, event_type TEXT, details TEXT DEFAULT '',
            actor TEXT DEFAULT '', created_at TEXT DEFAULT ''
        );
        CREATE INDEX IF NOT EXISTS idx_chem_sds_product ON chem_sds(product_id);
        CREATE INDEX IF NOT EXISTS idx_chem_events_product ON chem_events(product_id);
        CREATE TABLE IF NOT EXISTS chem_sds_sections (
            id INTEGER PRIMARY KEY AUTOINCREMENT, sds_id INTEGER NOT NULL, section_no INTEGER NOT NULL,
            section_title TEXT DEFAULT '', section_content TEXT DEFAULT '',
            UNIQUE(sds_id, section_no),
            FOREIGN KEY(sds_id) REFERENCES chem_sds(id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS coshh_assessments (
            id INTEGER PRIMARY KEY AUTOINCREMENT, assessment_ref TEXT UNIQUE, product_id INTEGER NOT NULL,
            sds_id INTEGER, assessment_date TEXT DEFAULT '', revision TEXT DEFAULT '1',
            assessment_json TEXT NOT NULL DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT '',
            FOREIGN KEY(product_id) REFERENCES chem_products(id) ON DELETE CASCADE,
            FOREIGN KEY(sds_id) REFERENCES chem_sds(id) ON DELETE SET NULL
        );
        CREATE INDEX IF NOT EXISTS idx_coshh_product ON coshh_assessments(product_id);
        """)

        # Older builds may have created chem_sds with a foreign key to a legacy
        # parent table. CREATE TABLE IF NOT EXISTS does not repair that schema.
        # Rebuild only this SDS table, retaining all rows that have a valid parent.
        conn = self.db.conn
        fk_rows = conn.execute("PRAGMA foreign_key_list(chem_sds)").fetchall()
        wrong_parent = any(_s(row[2]).lower() != "chem_products" for row in fk_rows)
        if wrong_parent:
            conn.commit()
            conn.execute("PRAGMA foreign_keys=OFF")
            try:
                conn.execute("BEGIN IMMEDIATE")
                conn.execute("""CREATE TABLE chem_sds_rebuild (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    product_id INTEGER NOT NULL,
                    sds_number TEXT DEFAULT '', revision TEXT DEFAULT '',
                    issue_date TEXT DEFAULT '', review_due_date TEXT DEFAULT '',
                    language TEXT DEFAULT 'English', file_path TEXT DEFAULT '',
                    status TEXT DEFAULT 'Current', uploaded_by TEXT DEFAULT '', uploaded_at TEXT DEFAULT '',
                    FOREIGN KEY(product_id) REFERENCES chem_products(id) ON DELETE CASCADE
                )""")
                old_cols = {row[1] for row in conn.execute("PRAGMA table_info(chem_sds)").fetchall()}
                new_cols = ["id", "product_id", "sds_number", "revision", "issue_date", "review_due_date",
                            "language", "file_path", "status", "uploaded_by", "uploaded_at"]
                copy_cols = [c for c in new_cols if c in old_cols]
                cols_sql = ",".join('"' + c + '"' for c in copy_cols)
                conn.execute(
                    f"INSERT INTO chem_sds_rebuild({cols_sql}) SELECT {cols_sql} FROM chem_sds "
                    "WHERE product_id IN (SELECT id FROM chem_products)"
                )
                # Keep orphaned legacy SDS metadata in a separate archive instead of
                # silently deleting records that cannot be linked to a current chemical.
                orphan_count = conn.execute(
                    "SELECT COUNT(*) FROM chem_sds WHERE product_id NOT IN (SELECT id FROM chem_products)"
                ).fetchone()[0]
                if orphan_count:
                    conn.execute("""CREATE TABLE IF NOT EXISTS chem_sds_orphan_archive (
                        id INTEGER, product_id INTEGER, sds_number TEXT, revision TEXT,
                        issue_date TEXT, review_due_date TEXT, language TEXT, file_path TEXT,
                        status TEXT, uploaded_by TEXT, uploaded_at TEXT, archived_at TEXT DEFAULT CURRENT_TIMESTAMP
                    )""")
                    archive_cols = [c for c in new_cols if c in old_cols]
                    archive_sql = ",".join('"' + c + '"' for c in archive_cols)
                    conn.execute(
                        f"INSERT INTO chem_sds_orphan_archive({archive_sql}) SELECT {archive_sql} FROM chem_sds "
                        "WHERE product_id NOT IN (SELECT id FROM chem_products)"
                    )
                conn.execute("DROP TABLE chem_sds")
                conn.execute("ALTER TABLE chem_sds_rebuild RENAME TO chem_sds")
                conn.execute("CREATE INDEX IF NOT EXISTS idx_chem_sds_product ON chem_sds(product_id)")
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.execute("PRAGMA foreign_keys=ON")
        conn.commit()

    def _actor(self):
        return os.environ.get("USERNAME") or os.environ.get("USER") or "User"

    def _event(self, pid, etype, details=""):
        self.db.execute("INSERT INTO chem_events(product_id,event_type,details,actor,created_at) VALUES(?,?,?,?,?)",
                        (pid, etype, details, self._actor(), _now()))

    # ---------- SDS 16-section register and COSHH assessment ----------
    def _build_sds_sections_tab(self):
        w = QWidget(); self.tabs.addTab(w, "3. SDS 16-Section Register")
        lay = QVBoxLayout(w)
        bar = QHBoxLayout()
        self.sds_section_filter = QComboBox(); self.sds_section_filter.setMinimumWidth(260)
        self.sds_section_filter.currentIndexChanged.connect(self.refresh_sds_sections)
        bar.addWidget(QLabel("SDS / Chemical:")); bar.addWidget(self.sds_section_filter, 1)
        lay.addLayout(bar)
        self.sds_sections_table = self._mk_table(["Section", "SDS Heading", "Extracted SDS Content"])
        self.sds_sections_table.setWordWrap(True)
        lay.addWidget(self.sds_sections_table, 1)
        note = QLabel("The register stores all 16 standard SDS sections from the uploaded file. Missing or scanned/non-selectable sections remain blank and must be checked against the original SDS.")
        note.setWordWrap(True); lay.addWidget(note)

    def refresh_sds_sections(self, *_):
        if not hasattr(self, "sds_section_filter"):
            return
        keep = self.sds_section_filter.currentData()
        self.sds_section_filter.blockSignals(True); self.sds_section_filter.clear()
        rows = self.db.fetchall("SELECT s.id, p.product_name, s.revision, s.issue_date FROM chem_sds s JOIN chem_products p ON p.id=s.product_id ORDER BY p.product_name, s.issue_date DESC, s.id DESC")
        for r in rows:
            self.sds_section_filter.addItem(f"{r['product_name']} | Rev {r['revision']} | {r['issue_date']}", int(r['id']))
        idx = self.sds_section_filter.findData(keep)
        if idx >= 0: self.sds_section_filter.setCurrentIndex(idx)
        self.sds_section_filter.blockSignals(False)
        self.sds_sections_table.setRowCount(0)
        sid = self.sds_section_filter.currentData()
        if sid is None: return
        # Backfill section extraction for SDS records uploaded by earlier app versions.
        existing_sections = self.db.fetchone("SELECT COUNT(*) AS n FROM chem_sds_sections WHERE sds_id=?", (sid,))
        if not existing_sections or int(existing_sections['n'] or 0) == 0:
            source = self.db.fetchone("SELECT file_path FROM chem_sds WHERE id=?", (sid,))
            if source and source['file_path'] and Path(source['file_path']).is_file():
                try:
                    extracted = chem_extract_sds_sections(chem_file_text(source['file_path']))
                    for sec_no, sec_title, sec_text in extracted:
                        self.db.execute("INSERT OR REPLACE INTO chem_sds_sections(sds_id,section_no,section_title,section_content) VALUES(?,?,?,?)",
                                        (sid, sec_no, sec_title, sec_text))
                except Exception:
                    logging.exception("Could not backfill SDS sections for SDS record %s", sid)
        stored = {int(x['section_no']): x for x in self.db.fetchall("SELECT * FROM chem_sds_sections WHERE sds_id=? ORDER BY section_no", (sid,))}
        for n in range(1, 17):
            x = stored.get(n)
            rr = self.sds_sections_table.rowCount(); self.sds_sections_table.insertRow(rr)
            vals = [f"Section {n}", x['section_title'] if x else "Not identified in uploaded SDS", x['section_content'] if x else ""]
            for c, v in enumerate(vals): self.sds_sections_table.setItem(rr, c, QTableWidgetItem(_s(v)))
        self.sds_sections_table.resizeRowsToContents()

    def _build_coshh_tab(self):
        w = QWidget(); self.tabs.addTab(w, "4. COSHH Assessment")
        lay = QVBoxLayout(w)
        bar = QHBoxLayout()
        b = QPushButton("New COSHH Assessment for Chemical")
        b.clicked.connect(self._new_coshh_assessment); bar.addWidget(b)
        x = QPushButton("Export Selected (Word)"); x.clicked.connect(lambda: self._export_coshh("docx")); bar.addWidget(x)
        pdf = QPushButton("Export Selected (PDF)"); pdf.clicked.connect(lambda: self._export_coshh("pdf")); bar.addWidget(pdf)
        bar.addStretch(1); lay.addLayout(bar)
        self.coshh_table = self._mk_table(["ID", "Assessment Ref.", "Chemical", "Assessment Date", "SDS Revision", "Residual Risk", "Conclusion"])
        lay.addWidget(self.coshh_table, 1)
        tip = QLabel("Automatic draft uses SDS Sections 1, 2, 3, 6 and 8 for identification, hazards, composition, spill response and exposure controls. Complete and verify all site/task-specific fields before approval; this is not an automatic substitute for competent assessment.")
        tip.setWordWrap(True); lay.addWidget(tip)

    def refresh_coshh(self):
        rows = []
        for r in self.db.fetchall("SELECT c.*, p.product_name, s.revision AS sds_revision FROM coshh_assessments c JOIN chem_products p ON p.id=c.product_id LEFT JOIN chem_sds s ON s.id=c.sds_id ORDER BY c.id DESC"):
            try: d = json.loads(r['assessment_json'] or '{}')
            except Exception: d = {}
            rows.append((r['id'], [r['id'], r['assessment_ref'], r['product_name'], r['assessment_date'], r['sds_revision'] or '', d.get('residual_score',''), d.get('Conclusion','Draft / review required')]))
        self._fill(self.coshh_table, rows)

    def _selected_coshh_id(self):
        return self._sel_id(self.coshh_table, "COSHH assessment")

    def _new_coshh_assessment(self):
        pid = self._sel_id(self.reg_table, "chemical in Chemical Register tab")
        if pid is None:
            QMessageBox.information(self, "Select Chemical", "Select a chemical in the Chemical Register tab first.")
            return
        product = self.db.fetchone("SELECT * FROM chem_products WHERE id=?", (pid,))
        sds = self.db.fetchone("SELECT * FROM chem_sds WHERE product_id=? AND status='Current' ORDER BY issue_date DESC,id DESC LIMIT 1", (pid,))
        if not sds:
            QMessageBox.warning(self, "Current SDS Required", "Upload a current SDS before creating the COSHH assessment.")
            return
        sections = {int(r['section_no']): r for r in self.db.fetchall("SELECT * FROM chem_sds_sections WHERE sds_id=?", (sds['id'],))}
        def sec(n):
            r = sections.get(n); return (r['section_title'] + "\n" + r['section_content']).strip() if r else "Not extracted from this SDS. Verify against original SDS."
        auto = {
            "1. Assessment details": f"Chemical: {product['product_name']}\nSupplier: {product['supplier']}\nEmergency contact: {product['supplier_contact']}\nProject: {product['project']}\nDepartment: {product['department']}\nLocation: {product['storage_location']}\nSDS reference: {sds['sds_number']} | Revision: {sds['revision']} | Issue: {sds['issue_date']}",
            "2. Substance identification & classification": f"SDS Section 1:\n{sec(1)}\n\nSDS Section 2:\n{sec(2)}\n\nSDS Section 3:\n{sec(3)}",
            "3. CLP / GHS pictograms": f"SDS Section 2:\n{sec(2)}\n\nGHS classes recorded: {product['ghs_classes']}\nSignal word: {product['signal_word']}\nH-statements: {product['h_statements']}\nP-statements: {product['p_statements']}",
            "4. Routes of exposure & health effects": f"Potential hazards / health effects from the requested SDS source sections 2 and 3:\n{sec(2)}\n\nComposition:\n{sec(3)}\n\nConfirm actual exposure routes and task-specific effects with the competent assessor.",
            "8. Control measures / exposure controls": f"SDS Section 8 – exposure controls / PPE:\n{sec(8)}",
            "13. Emergency arrangements / first aid": f"SDS Section 6 – accidental release / spill response:\n{sec(6)}\n\nFirst-aid, fire-fighting and site emergency arrangements must be completed by the assessor from approved site information; SDS sections outside 1, 2, 3, 6 and 8 are intentionally not imported.",
        }
        dlg = QDialog(self); dlg.setWindowTitle("COSHH Assessment – " + _s(product['product_name']))
        dlg.resize(980, 850); outer = QVBoxLayout(dlg)
        scroll = QScrollArea(); scroll.setWidgetResizable(True); body = QWidget(); form = QFormLayout(body); scroll.setWidget(body); outer.addWidget(scroll)
        widgets = {}
        def line(k, value="", placeholder=""):
            w = QLineEdit(_s(value)); w.setPlaceholderText(placeholder); widgets[k] = w; form.addRow(k, w)
        def memo(k, value="", h=100):
            w = QTextEdit(_s(value)); w.setMinimumHeight(h); widgets[k] = w; form.addRow(k, w)
        ref = f"COSHH-{datetime.now().strftime('%Y%m%d-%H%M%S')}"
        line("Assessment Ref. No.", ref); line("Date of Assessment", date.today().isoformat())
        line("Company / Employer", ""); line("Project / Contract", product['project']); line("Site / Location / Work Area", product['storage_location'])
        line("Department / Section", product['department']); line("Task / Process / Activity"); memo("Description of Work & Method", "", 80)
        line("Assessor Name & Designation"); line("Assessor Competency / Qualification"); line("Reviewed / Approved By")
        line("Next Review Due Date", (date.today()+timedelta(days=365)).isoformat()); line("Frequency / Duration / Quantity / Persons Exposed")
        line("SDS Available at Point of Use?", "Yes"); line("SDS Language", sds['language'])
        for title, value in auto.items(): memo(title, value, 135)
        memo("5. Persons at risk / number / job roles / special considerations", "Employees / contractors / maintenance personnel – confirm actual persons and job roles.")
        memo("6. Matters considered in assessment (Yes / No / N/A and evidence)", "Confirm CLP hazards, SDS review, exposure duration, task conditions, maintenance/spill exposure, WEL/BMGV, existing controls, monitoring, health surveillance and combined exposure.")
        line("Likelihood Before Controls (1-5)", "3"); line("Severity Before Controls (1-5)", "3")
        line("Likelihood After Controls (1-5)", "2"); line("Severity After Controls (1-5)", "2")
        memo("7. Risk rating comments / acceptability", "Risk score = likelihood × severity. 1–4 Low; 5–9 Medium; 10–16 High; 17–25 Extreme. Verify scoring with competent assessor.")
        memo("8. Hierarchy of controls – existing / additional / responsible / target date", "Eliminate; substitute; enclose/isolate; engineering controls; reduce exposure; safe systems of work; hygiene/welfare; PPE/RPE as last resort.")
        memo("9. PPE / RPE requirements and specifications", sec(8))
        memo("10. Maintenance, examination & testing of controls", "Specify LEV / enclosure / ventilation examination, competent person, last and next test dates, records and defects.")
        memo("11. Exposure monitoring & health surveillance", "State whether monitoring and health surveillance are required, method, frequency, results versus WEL and record retention.")
        memo("12. Information, instruction & training", "Record training topics, attendees, dates and trainer.")
        memo("13. Emergency arrangements / first aid", auto["13. Emergency arrangements / first aid"] + "\nAdd site first-aid, eyewash, shower, emergency contacts and spill/fire response arrangements.")
        memo("14. Storage, handling, waste & environment", f"Storage: {product['storage_location']}\nUN No.: {product['un_number']}\nDisposal information recorded in Chemical Register: {product['disposal']}\nComplete site-specific handling, segregation, bunding, waste and environmental controls. SDS sections outside 1, 2, 3, 6 and 8 are intentionally not imported.")
        memo("15. Conclusion / action plan / review triggers", "Select: adequately controlled / further actions required / work must not proceed. Record actions, owners, due dates and review triggers.")
        line("Conclusion", "Draft – competent review required")
        line("Assessor Name / Signature / Date", "")
        line("HSE Reviewer Name / Signature / Date", "")
        line("Approver Name / Signature / Date", "")
        memo("Employee acknowledgement / signatures", "Record employee name, ID/badge, company/trade, signature and date.", 70)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel); outer.addWidget(bb)
        bb.accepted.connect(dlg.accept); bb.rejected.connect(dlg.reject)
        if dlg.exec() != QDialog.DialogCode.Accepted: return
        data = {k: (v.toPlainText() if isinstance(v, QTextEdit) else v.text()).strip() for k,v in widgets.items()}
        try:
            lb = int(data.get("Likelihood Before Controls (1-5)",3)); sb = int(data.get("Severity Before Controls (1-5)",3))
            la = int(data.get("Likelihood After Controls (1-5)",2)); sa = int(data.get("Severity After Controls (1-5)",2))
            if any(v < 1 or v > 5 for v in (lb, sb, la, sa)): raise ValueError()
            before = lb * sb; after = la * sa
        except Exception:
            QMessageBox.warning(self, "Risk Score", "Likelihood and severity must each be whole numbers from 1 to 5."); return
        data['inherent_score'] = before; data['residual_score'] = after
        data['inherent_band'] = self._risk_band(before); data['residual_band'] = self._risk_band(after)
        self.db.execute("INSERT INTO coshh_assessments(assessment_ref,product_id,sds_id,assessment_date,assessment_json) VALUES(?,?,?,?,?)",
                        (data.get('Assessment Ref. No.') or ref, pid, int(sds['id']), data.get('Date of Assessment',''), json.dumps(data, ensure_ascii=False)))
        self.refresh_coshh()

    @staticmethod
    def _risk_band(score):
        return "Low" if score <= 4 else "Medium" if score <= 9 else "High" if score <= 16 else "Extreme"

    def _edit_coshh_assessment(self):
        aid = self._selected_coshh_id()
        if aid is None: return
        QMessageBox.information(self, "COSHH Assessment", "To preserve the original SDS-derived assessment and sign-off trail, create a new assessment revision by selecting the chemical and choosing New COSHH Assessment. Existing assessment remains available for export.")

    def _export_coshh(self, fmt="docx"):
        """Export a structured, approval-ready COSHH report. Changes are confined to COSHH export."""
        aid = self._selected_coshh_id()
        if aid is None:
            return
        r = self.db.fetchone(
            "SELECT c.*,p.product_name,p.supplier,p.cas_number,p.un_number,p.ghs_classes,p.signal_word,"
            "s.revision AS sds_revision,s.sds_number FROM coshh_assessments c "
            "JOIN chem_products p ON p.id=c.product_id LEFT JOIN chem_sds s ON s.id=c.sds_id WHERE c.id=?", (aid,)
        )
        if not r:
            return
        try:
            d = json.loads(r['assessment_json'] or '{}')
        except Exception:
            d = {}
        default = f"{r['assessment_ref']}.{fmt}"
        path, _ = QFileDialog.getSaveFileName(
            self, "Export COSHH Assessment", default,
            "Word Document (*.docx)" if fmt == "docx" else "PDF (*.pdf)"
        )
        if not path:
            return

        order = [
            "1. Assessment details", "2. Substance identification & classification",
            "3. CLP / GHS pictograms", "4. Routes of exposure & health effects",
            "5. Persons at risk / number / job roles / special considerations",
            "6. Matters considered in assessment (Yes / No / N/A and evidence)",
            "7. Risk rating comments / acceptability",
            "8. Hierarchy of controls – existing / additional / responsible / target date",
            "9. PPE / RPE requirements and specifications",
            "10. Maintenance, examination & testing of controls",
            "11. Exposure monitoring & health surveillance",
            "12. Information, instruction & training",
            "13. Emergency arrangements / first aid",
            "14. Storage, handling, waste & environment",
            "15. Conclusion / action plan / review triggers"
        ]
        ghs_names = {
            "GHS01": "Exploding bomb – explosive / self-reactive hazard",
            "GHS02": "Flame – flammable / pyrophoric hazard",
            "GHS03": "Flame over circle – oxidising hazard",
            "GHS04": "Gas cylinder – gas under pressure",
            "GHS05": "Corrosion – corrosive to metals / skin / eyes",
            "GHS06": "Skull and crossbones – acute toxicity",
            "GHS07": "Exclamation mark – irritant / harmful effects",
            "GHS08": "Health hazard – serious / chronic health effects",
            "GHS09": "Environment – aquatic toxicity"
        }
        pictogram_source = " ".join([
            _s(r['ghs_classes']), _s(d.get("3. CLP / GHS pictograms", "")),
            _s(d.get("2. Substance identification & classification", ""))
        ]).upper()
        ghs_codes = [re.sub(r"\s+", "", x) for x in re.findall(r"GHS\s*0[1-9]", pictogram_source)]
        # The chemical register stores hazard classes as names; map those classes to
        # their standard GHS pictogram identifiers without inventing unrecorded hazards.
        class_to_ghs = {
            "EXPLOSIVE": "GHS01", "FLAMMABLE": "GHS02", "OXIDIZING": "GHS03",
            "OXIDISING": "GHS03", "COMPRESSED GAS": "GHS04", "GAS UNDER PRESSURE": "GHS04",
            "CORROSIVE": "GHS05", "ACUTE TOXIC": "GHS06", "ACUTE TOXICITY": "GHS06",
            "IRRITANT": "GHS07", "HEALTH HAZARD": "GHS08", "ENVIRONMENTAL HAZARD": "GHS09"
        }
        for hazard_class, pictogram_id in class_to_ghs.items():
            if hazard_class in pictogram_source and pictogram_id not in ghs_codes:
                ghs_codes.append(pictogram_id)

        def clean_lines(value):
            return [x.strip(" \t•-*\u2022") for x in _s(value).replace("\r", "\n").split("\n") if x.strip()]

        def section_rows(key):
            value = _s(d.get(key, "Not completed")).strip() or "Not completed"
            lines = clean_lines(value)
            # Preserve all source text while presenting each item as a numbered register row.
            return [(f"{i:02d}", line) for i, line in enumerate(lines, 1)]

        before = d.get('inherent_score', '')
        after = d.get('residual_score', '')
        before_band = d.get('inherent_band', '')
        after_band = d.get('residual_band', '')

        try:
            if fmt == "docx":
                from docx.enum.section import WD_SECTION
                from docx.enum.table import WD_ROW_HEIGHT_RULE
                from docx.oxml import parse_xml
                from docx.oxml.ns import nsdecls
                from docx.shared import RGBColor

                doc = Document()
                sec = doc.sections[0]
                sec.page_width = Inches(8.27); sec.page_height = Inches(11.69)
                sec.top_margin = Inches(.55); sec.bottom_margin = Inches(.55)
                sec.left_margin = Inches(.58); sec.right_margin = Inches(.58)
                styles = doc.styles
                styles['Normal'].font.name = 'Arial'; styles['Normal'].font.size = Pt(8.5)
                styles['Normal'].font.color.rgb = RGBColor(45, 55, 65)
                for stylename in ('Heading 1', 'Heading 2'):
                    styles[stylename].font.name = 'Arial'
                    styles[stylename].font.color.rgb = RGBColor(23, 54, 93)
                styles['Heading 1'].font.size = Pt(11)
                styles['Heading 1'].font.bold = True
                styles['Heading 2'].font.size = Pt(9.5)

                header = sec.header.paragraphs[0]
                header.text = "HSE MANAGEMENT SYSTEM  |  CONTROLLED COSHH ASSESSMENT"
                header.alignment = WD_ALIGN_PARAGRAPH.RIGHT
                for run in header.runs:
                    run.font.name = 'Arial'; run.font.size = Pt(7); run.font.color.rgb = RGBColor(100, 110, 120)
                footer = sec.footer.paragraphs[0]
                footer.text = f"{r['assessment_ref']}  |  Uncontrolled when printed  |  Page "
                for run in footer.runs:
                    run.font.size = Pt(7)
                fld = OxmlElement('w:fldSimple'); fld.set(qn('w:instr'), 'PAGE'); footer._p.append(fld)

                title = doc.add_heading("COSHH ASSESSMENT", 0)
                title.alignment = WD_ALIGN_PARAGRAPH.CENTER
                sub = doc.add_paragraph("CONTROL OF SUBSTANCES HAZARDOUS TO HEALTH")
                sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
                for run in sub.runs:
                    run.bold = True; run.font.size = Pt(9); run.font.color.rgb = RGBColor(80, 90, 105)

                def shade(cell, fill):
                    tcPr = cell._tc.get_or_add_tcPr()
                    tcPr.append(parse_xml(r'<w:shd {} w:fill="{}"/>'.format(nsdecls('w'), fill)))
                def set_cell(cell, value, bold=False, color=None, size=8):
                    cell.text = _s(value)
                    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
                    for para in cell.paragraphs:
                        para.paragraph_format.space_after = Pt(1)
                        for run in para.runs:
                            run.font.name = 'Arial'; run.font.size = Pt(size); run.bold = bold
                            if color: run.font.color.rgb = RGBColor(*color)
                def table(headers, rows, widths=None):
                    t = doc.add_table(rows=1, cols=len(headers)); t.style = 'Table Grid'
                    t.alignment = WD_TABLE_ALIGNMENT.CENTER
                    for i, h in enumerate(headers):
                        set_cell(t.rows[0].cells[i], h, True, (255,255,255), 8)
                        shade(t.rows[0].cells[i], '17365D')
                    for row in rows:
                        cells = t.add_row().cells
                        for i, val in enumerate(row):
                            set_cell(cells[i], val, False, None, 8)
                    if widths:
                        for row in t.rows:
                            for i, width in enumerate(widths): row.cells[i].width = Inches(width)
                    doc.add_paragraph().paragraph_format.space_after = Pt(1)
                    return t
                def heading(text):
                    p = doc.add_paragraph()
                    p.paragraph_format.space_before = Pt(6); p.paragraph_format.space_after = Pt(3)
                    run = p.add_run(text); run.bold = True; run.font.name = 'Arial'; run.font.size = Pt(10)
                    run.font.color.rgb = RGBColor(23,54,93)
                    pPr = p._p.get_or_add_pPr(); pPr.append(parse_xml(r'<w:shd {} w:fill="E8EFF7"/>'.format(nsdecls('w'))))
                table(["Assessment Reference", "Assessment Date", "Chemical / Product", "SDS Revision"], [[
                    r['assessment_ref'], r['assessment_date'], r['product_name'], r['sds_revision'] or "Not recorded"
                ]])
                table(["SDS No.", "Supplier", "CAS No.", "UN No.", "Signal Word"], [[
                    r['sds_number'] or "", r['supplier'] or "", r['cas_number'] or "", r['un_number'] or "", r['signal_word'] or ""
                ]])
                heading("RISK RATING SUMMARY")
                table(["Initial Likelihood", "Initial Severity", "Initial Score", "Initial Rating", "Residual Likelihood", "Residual Severity", "Residual Score", "Residual Rating"], [[
                    d.get("Likelihood Before Controls (1-5)", ""), d.get("Severity Before Controls (1-5)", ""), before, before_band,
                    d.get("Likelihood After Controls (1-5)", ""), d.get("Severity After Controls (1-5)", ""), after, after_band
                ]])
                heading("GHS / CLP HAZARD PICTOGRAMS")
                if ghs_codes:
                    table(["Pictogram ID", "Hazard pictogram / meaning"], [[c, "◇  " + ghs_names.get(c, "Refer to SDS classification")] for c in ghs_codes])
                else:
                    table(["Pictogram status", "Assessment record"], [["Not identified in saved assessment", "Verify pictograms directly against SDS Section 2. No pictogram has been assumed."]])
                for key in order:
                    heading(key.upper())
                    val = _s(d.get(key, "Not completed")).strip() or "Not completed"
                    if key.startswith("8.") or key.startswith("9."):
                        rows = section_rows(key)
                        table(["Item ID", "Control / PPE requirement and specification"], rows)
                    elif key.startswith("6."):
                        table(["Check ID", "Assessment consideration / evidence"], section_rows(key))
                    else:
                        table(["Assessment information / evidence"], [[val]])
                heading("APPROVAL AND SIGNATURE RECORD")
                t = doc.add_table(rows=2, cols=3); t.style = 'Table Grid'
                labels = ["PREPARED BY – ASSESSOR", "REVIEWED BY – HSE", "APPROVED BY – MANAGEMENT"]
                names = [d.get("Assessor Name / Signature / Date", d.get("Assessor Name & Designation", "")),
                         d.get("HSE Reviewer Name / Signature / Date", ""), d.get("Approver Name / Signature / Date", d.get("Reviewed / Approved By", ""))]
                for i in range(3):
                    set_cell(t.rows[0].cells[i], labels[i], True, (255,255,255), 8); shade(t.rows[0].cells[i], '17365D')
                    set_cell(t.rows[1].cells[i], "Name: " + _s(names[i]) + "\n\nSignature: ____________________\n\nDate: ____________________", False, None, 8)
                heading("EMPLOYEE / WORKER ACKNOWLEDGEMENT")
                table(["Acknowledgement / Names / IDs / Signatures / Dates"], [[_s(d.get("Employee acknowledgement / signatures", "To be completed by affected personnel."))]])
                note = doc.add_paragraph("This assessment must be verified against the actual task, work location, SDS and site conditions. Work must not proceed until required controls are implemented and competent review / approval is complete.")
                for run in note.runs:
                    run.italic = True; run.font.size = Pt(7.5); run.font.color.rgb = RGBColor(90,90,90)
                doc.save(path)
            else:
                from reportlab.lib.styles import ParagraphStyle
                from reportlab.lib.enums import TA_CENTER
                from reportlab.lib.units import mm
                from reportlab.platypus import KeepTogether, PageBreak
                styles = getSampleStyleSheet()
                styles.add(ParagraphStyle(name='COSHHHead', parent=styles['Title'], fontName='Helvetica-Bold', fontSize=17, leading=20, textColor=colors.HexColor('#17365D'), alignment=TA_CENTER, spaceAfter=4))
                styles.add(ParagraphStyle(name='COSHHSub', parent=styles['Normal'], fontName='Helvetica-Bold', fontSize=8, leading=10, alignment=TA_CENTER, textColor=colors.HexColor('#566579'), spaceAfter=8))
                styles.add(ParagraphStyle(name='COSHHSection', parent=styles['Heading2'], fontName='Helvetica-Bold', fontSize=9, leading=11, textColor=colors.white, backColor=colors.HexColor('#17365D'), borderPadding=5, spaceBefore=7, spaceAfter=4))
                styles.add(ParagraphStyle(name='COSHHBody', parent=styles['BodyText'], fontName='Helvetica', fontSize=7.5, leading=10, spaceAfter=1, wordWrap='CJK'))
                styles.add(ParagraphStyle(name='COSHHCell', parent=styles['BodyText'], fontName='Helvetica', fontSize=7, leading=9, wordWrap='CJK'))
                def para(v): return Paragraph(html.escape(_s(v)).replace('\n','<br/>'), styles['COSHHCell'])
                def pdf_table(headers, rows, widths=None):
                    data = [[Paragraph(f'<b>{html.escape(_s(x))}</b>', styles['COSHHCell']) for x in headers]]
                    data += [[para(x) for x in row] for row in rows]
                    t = Table(data, colWidths=widths, repeatRows=1, hAlign='LEFT')
                    t.setStyle(TableStyle([
                        ('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17365D')),
                        ('TEXTCOLOR',(0,0),(-1,0),colors.white), ('GRID',(0,0),(-1,-1),.4,colors.HexColor('#AAB7C4')),
                        ('VALIGN',(0,0),(-1,-1),'TOP'), ('LEFTPADDING',(0,0),(-1,-1),5),
                        ('RIGHTPADDING',(0,0),(-1,-1),5), ('TOPPADDING',(0,0),(-1,-1),4),
                        ('BOTTOMPADDING',(0,0),(-1,-1),4), ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F6F9')])
                    ]))
                    return t
                story = [Paragraph("COSHH ASSESSMENT", styles['COSHHHead']),
                         Paragraph("CONTROL OF SUBSTANCES HAZARDOUS TO HEALTH", styles['COSHHSub'])]
                story += [pdf_table(["Assessment Reference", "Assessment Date", "Chemical / Product", "SDS Revision"], [[r['assessment_ref'], r['assessment_date'], r['product_name'], r['sds_revision'] or "Not recorded"]], [38*mm,30*mm,75*mm,35*mm]), Spacer(1,5)]
                story += [pdf_table(["SDS No.","Supplier","CAS No.","UN No.","Signal Word"], [[r['sds_number'] or "",r['supplier'] or "",r['cas_number'] or "",r['un_number'] or "",r['signal_word'] or ""]], [28*mm,55*mm,35*mm,25*mm,35*mm]), Spacer(1,5)]
                story.append(Paragraph("RISK RATING SUMMARY", styles['COSHHSection']))
                story.append(pdf_table(["Initial L","Initial S","Score","Rating","Residual L","Residual S","Score","Rating"], [[d.get("Likelihood Before Controls (1-5)",""),d.get("Severity Before Controls (1-5)",""),before,before_band,d.get("Likelihood After Controls (1-5)",""),d.get("Severity After Controls (1-5)",""),after,after_band]], [21*mm]*8))
                story.append(Paragraph("GHS / CLP HAZARD PICTOGRAMS", styles['COSHHSection']))
                if ghs_codes:
                    story.append(pdf_table(["Pictogram ID","Hazard pictogram / meaning"], [[c,"◇  "+ghs_names.get(c,"Refer to SDS classification")] for c in ghs_codes], [30*mm,138*mm]))
                else:
                    story.append(pdf_table(["Pictogram status","Assessment record"], [["Not identified in saved assessment","Verify directly against SDS Section 2. No pictogram has been assumed."]], [38*mm,130*mm]))
                for key in order:
                    story.append(Paragraph(html.escape(key.upper()), styles['COSHHSection']))
                    val = _s(d.get(key,"Not completed")).strip() or "Not completed"
                    if key.startswith(("8.","9.","6.")):
                        heading = "Check ID" if key.startswith("6.") else "Item ID"
                        label = "Assessment consideration / evidence" if key.startswith("6.") else ("Control / PPE requirement and specification" if key.startswith("9.") else "Control measure / action")
                        story.append(pdf_table([heading,label], section_rows(key), [22*mm,146*mm]))
                    else:
                        story.append(pdf_table(["Assessment information / evidence"], [[val]], [168*mm]))
                    story.append(Spacer(1,3))
                story.append(Paragraph("APPROVAL AND SIGNATURE RECORD", styles['COSHHSection']))
                sig_rows = [["PREPARED BY – ASSESSOR","REVIEWED BY – HSE","APPROVED BY – MANAGEMENT"],
                            ["Name: "+_s(d.get("Assessor Name / Signature / Date",d.get("Assessor Name & Designation","")))+"\n\nSignature: __________________\n\nDate: ______________",
                             "Name: "+_s(d.get("HSE Reviewer Name / Signature / Date",""))+"\n\nSignature: __________________\n\nDate: ______________",
                             "Name: "+_s(d.get("Approver Name / Signature / Date",d.get("Reviewed / Approved By","")))+"\n\nSignature: __________________\n\nDate: ______________"]]
                story.append(pdf_table(sig_rows[0], [sig_rows[1]], [56*mm,56*mm,56*mm]))
                story.append(Paragraph("EMPLOYEE / WORKER ACKNOWLEDGEMENT", styles['COSHHSection']))
                story.append(pdf_table(["Acknowledgement / Names / IDs / Signatures / Dates"], [[d.get("Employee acknowledgement / signatures","To be completed by affected personnel.")]], [168*mm]))
                story.append(Spacer(1,6))
                story.append(Paragraph("This assessment must be verified against the actual task, work location, SDS and site conditions. Work must not proceed until required controls are implemented and competent review / approval is complete.", styles['COSHHCell']))
                def page_footer(canvas, document):
                    canvas.saveState(); canvas.setFont('Helvetica',7); canvas.setFillColor(colors.HexColor('#667788'))
                    canvas.drawString(16*mm, 9*mm, f"{r['assessment_ref']} | Uncontrolled when printed")
                    canvas.drawRightString(194*mm, 9*mm, f"Page {document.page}")
                    canvas.restoreState()
                SimpleDocTemplate(path, pagesize=A4, rightMargin=16*mm, leftMargin=16*mm, topMargin=15*mm, bottomMargin=16*mm).build(story, onFirstPage=page_footer, onLaterPages=page_footer)
            QMessageBox.information(self, "Exported", f"COSHH assessment exported to:\n{path}")
        except Exception as exc:
            logging.exception("COSHH export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))

    # ---------- UI ----------
    def _build_ui(self):
        root = QVBoxLayout(self)
        head = QLabel("CHEMICAL REGISTER & SDS MANAGEMENT")
        head.setStyleSheet("font-size:22px;font-weight:bold;color:#17365D;padding:7px;")
        root.addWidget(head)
        note = QLabel("Go to tab 2 and upload an SDS (PDF/DOCX): the system reads it and pre-fills the register for your review. Every chemical on site needs a current SDS. SDS review interval defaults to "
                      f"{CHEM_SDS_REVIEW_YEARS} years from issue date - align with your site/client/regulatory rule. "
                      "Compatibility check is indicative only; always confirm against SDS Sections 7 and 10.")
        note.setWordWrap(True)
        note.setStyleSheet("padding:8px;background:#FFF4D6;border:1px solid #E6D18A;border-radius:4px;color:#5B4B16;")
        root.addWidget(note)
        self.tabs = QTabWidget()
        root.addWidget(self.tabs, 1)
        self._build_register_tab()
        self._build_sds_tab()
        self._build_sds_sections_tab()
        self._build_coshh_tab()

    def _mk_table(self, headers):
        t = QTableWidget(0, len(headers))
        t.setHorizontalHeaderLabels(headers)
        t.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        t.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        t.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        t.setAlternatingRowColors(True)
        t.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Interactive)
        t.horizontalHeader().setStretchLastSection(True)
        return t

    def _fill(self, table, rows, state_col=None):
        """rows: list of (record_id, [cell values]). Record id is kept on column 0."""
        table.setRowCount(0)
        for rid, vals in rows:
            r = table.rowCount()
            table.insertRow(r)
            for c, v in enumerate(vals):
                it = QTableWidgetItem(_s(v))
                if c == 0:
                    it.setData(Qt.ItemDataRole.UserRole, rid)
                if state_col is not None and c == state_col:
                    colour = {"Missing": "#F8CBAD", "Expired": "#F8CBAD", "Due Soon": "#FFE699",
                              "Current": "#C6E0B4"}.get(_s(v))
                    if colour:
                        it.setBackground(QBrush(QColor(colour)))
                table.setItem(r, c, it)
        table.resizeColumnsToContents()

    def _sel_id(self, table, what="record"):
        r = table.currentRow()
        if r < 0 or not table.item(r, 0):
            QMessageBox.information(self, "Select", f"Select a {what} row first.")
            return None
        return table.item(r, 0).data(Qt.ItemDataRole.UserRole)

    # ----- register tab -----
    def _build_register_tab(self):
        w = QWidget(); self.tabs.addTab(w, "1. Chemical Register")
        lay = QVBoxLayout(w)
        bar = QHBoxLayout()
        self.search = QLineEdit(); self.search.setPlaceholderText("Search name, supplier, CAS, location...")
        self.search.textChanged.connect(self.refresh_register)
        self.status_filter = QComboBox(); self.status_filter.addItems(["All", "Active", "Phased Out", "Disposed"])
        self.status_filter.currentTextChanged.connect(self.refresh_register)
        bar.addWidget(self.search, 2); bar.addWidget(QLabel("Status:")); bar.addWidget(self.status_filter)
        for text, fn in [("Add Chemical", self._add_product), ("Edit", self._edit_product),
                         ("New Revision for Selected Chemical", self._new_revision),
                         ("Delete", self._delete_product), ("Export Excel", self._export_excel)]:
            b = QPushButton(text); b.clicked.connect(fn); bar.addWidget(b)
        lay.addLayout(bar)
        self.reg_headers = ["ID", "Product", "Supplier", "CAS No.", "UN No.", "Storage Group", "Location",
                            "Qty", "Unit", "GHS Classes", "Signal Word", "Project", "Status", "SDS Status", "SDS Review Due"]
        self.reg_table = self._mk_table(self.reg_headers)
        self.reg_table.doubleClicked.connect(lambda *_: self._edit_product())
        lay.addWidget(self.reg_table, 1)

    def _latest_sds_map(self):
        m = {}
        for s in self.db.fetchall("SELECT * FROM chem_sds WHERE status='Current' ORDER BY issue_date, id"):
            m[s["product_id"]] = s
        return m

    def refresh_register(self, *_):
        q = self.search.text().strip().lower(); st = self.status_filter.currentText()
        sds = self._latest_sds_map(); today_iso = today(); rows = []
        for p in self.db.fetchall("SELECT * FROM chem_products ORDER BY product_name"):
            if st != "All" and p["status"] != st:
                continue
            blob = " ".join(_s(p[k]) for k in ("product_name", "supplier", "cas_number", "storage_location", "un_number")).lower()
            if q and q not in blob:
                continue
            s = sds.get(p["id"])
            state = chem_sds_state(s, today_iso) if p["status"] == "Active" else "-"
            rows.append((p["id"], [p["id"], p["product_name"], p["supplier"], p["cas_number"], p["un_number"],
                                   p["storage_group"], p["storage_location"], p["quantity"], p["unit"], p["ghs_classes"],
                                   p["signal_word"], p["project"], p["status"], state, s["review_due_date"] if s else ""]))
        self._fill(self.reg_table, rows, state_col=13)

    # ----- product dialog -----
    def _product_dialog(self, rec=None, sds=None, banner=None):
        rec = dict(rec) if rec else {}
        dlg = QDialog(self); dlg.setWindowTitle("Chemical Details")
        screen = self.screen() or QApplication.primaryScreen()
        available = screen.availableGeometry() if screen else None
        max_w = max(520, int(available.width() * 0.92)) if available else 760
        max_h = max(420, int(available.height() * 0.90)) if available else 760
        dlg.resize(min(760, max_w), min(760, max_h))
        dlg.setMinimumSize(min(520, max_w), min(420, max_h))
        if available:
            dlg.setMaximumSize(max_w, max_h)
        outer = QVBoxLayout(dlg)
        if banner:
            bl = QLabel(banner); bl.setWordWrap(True)
            bl.setStyleSheet("padding:8px;background:#E8F3FF;border:1px solid #9CC3E6;border-radius:4px;color:#17365D;")
            outer.addWidget(bl)
        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        body = QWidget(); form = QFormLayout(body); scroll.setWidget(body); outer.addWidget(scroll)
        le = lambda k: QLineEdit(_s(rec.get(k)))
        f = {}
        f["product_name"] = le("product_name"); f["supplier"] = le("supplier"); f["supplier_contact"] = le("supplier_contact")
        f["cas_number"] = le("cas_number"); f["un_number"] = le("un_number"); f["product_use"] = le("product_use")
        f["physical_state"] = QComboBox(); f["physical_state"].addItems(["", "Liquid", "Solid", "Gas", "Powder", "Paste/Gel", "Aerosol"])
        f["physical_state"].setCurrentText(_s(rec.get("physical_state")))
        f["storage_group"] = QComboBox(); f["storage_group"].addItems([""] + CHEM_STORAGE_GROUPS)
        f["storage_group"].setCurrentText(_s(rec.get("storage_group")))
        f["storage_location"] = le("storage_location")
        f["signal_word"] = QComboBox(); f["signal_word"].addItems(["", "Danger", "Warning", "None"])
        f["signal_word"].setCurrentText(_s(rec.get("signal_word")))
        f["quantity"] = QDoubleSpinBox(); f["quantity"].setRange(0, 10000000); f["quantity"].setDecimals(2)
        f["quantity"].setValue(float(rec.get("quantity") or 0))
        f["unit"] = QComboBox(); f["unit"].addItems(["L", "mL", "kg", "g", "drum", "cylinder", "pail", "can", "pcs"])
        f["unit"].setCurrentText(_s(rec.get("unit")) or "L")
        f["project"] = QComboBox(); f["project"].setEditable(True)
        try:
            f["project"].addItems([""] + [r["project"] for r in self.db.fetchall("SELECT project FROM projects WHERE active=1 ORDER BY project")])
        except Exception:
            pass
        f["project"].setCurrentText(_s(rec.get("project")))
        f["department"] = le("department")
        f["status"] = QComboBox(); f["status"].addItems(["Active", "Phased Out", "Disposed"])
        f["status"].setCurrentText(_s(rec.get("status")) or "Active")
        f["approved_by"] = le("approved_by"); f["approval_date"] = le("approval_date")
        f["approval_date"].setPlaceholderText("YYYY-MM-DD")
        txt = lambda k: QTextEdit(_s(rec.get(k)))
        for k in ("h_statements", "p_statements", "ppe_required", "first_aid", "spill_response", "fire_fighting", "disposal", "remarks"):
            f[k] = txt(k); f[k].setFixedHeight(62)
        ghs_have = {x.strip() for x in _s(rec.get("ghs_classes")).split(",") if x.strip()}
        ghs_boxes = []; ghs_wrap = QWidget(); gl = QGridLayout(ghs_wrap)
        for i, g in enumerate(CHEM_GHS):
            cb = QCheckBox(g); cb.setChecked(g in ghs_have); ghs_boxes.append(cb); gl.addWidget(cb, i // 3, i % 3)
        form.addRow("Product Name *", f["product_name"]); form.addRow("Supplier / Manufacturer", f["supplier"])
        form.addRow("Supplier Emergency Contact", f["supplier_contact"]); form.addRow("CAS Number", f["cas_number"])
        form.addRow("UN Number", f["un_number"]); form.addRow("Intended Use", f["product_use"])
        form.addRow("Physical State", f["physical_state"]); form.addRow("Storage Group", f["storage_group"])
        form.addRow("Storage Location", f["storage_location"]); form.addRow("GHS Hazard Classes", ghs_wrap)
        form.addRow("Signal Word", f["signal_word"]); form.addRow("H-Statements", f["h_statements"])
        form.addRow("P-Statements", f["p_statements"]); form.addRow("Quantity on Site", f["quantity"])
        form.addRow("Unit", f["unit"]); form.addRow("Project", f["project"]); form.addRow("Department", f["department"])
        form.addRow("PPE Required", f["ppe_required"]); form.addRow("First Aid", f["first_aid"])
        form.addRow("Spill Response", f["spill_response"]); form.addRow("Fire Fighting", f["fire_fighting"])
        form.addRow("Disposal", f["disposal"]); form.addRow("Status", f["status"])
        form.addRow("Approved For Use By", f["approved_by"]); form.addRow("Approval Date", f["approval_date"])
        form.addRow("Remarks", f["remarks"])
        sw = {}
        if sds is not None:
            form.addRow(QLabel("<b>SDS document details</b>"))
            sw["sds_number"] = QLineEdit(_s(sds.get("sds_number"))); sw["sds_revision"] = QLineEdit(_s(sds.get("sds_revision")))
            sw["sds_language"] = QLineEdit(_s(sds.get("sds_language")) or "English")
            d0 = QDate.fromString(_s(sds.get("sds_issue")), "yyyy-MM-dd")
            if not d0.isValid(): d0 = QDate.currentDate()
            sw["issue"] = QDateEdit(d0); sw["due"] = QDateEdit(d0.addYears(CHEM_SDS_REVIEW_YEARS))
            for k in ("issue", "due"):
                sw[k].setCalendarPopup(True); sw[k].setDisplayFormat("yyyy-MM-dd")
            sw["issue"].dateChanged.connect(lambda d: sw["due"].setDate(d.addYears(CHEM_SDS_REVIEW_YEARS)))
            form.addRow("SDS Number", sw["sds_number"]); form.addRow("Revision", sw["sds_revision"])
            form.addRow("SDS Issue Date", sw["issue"]); form.addRow("SDS Review Due", sw["due"]); form.addRow("Language", sw["sds_language"])
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        if sds is not None:
            bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Skip this SDS")
        bb.accepted.connect(dlg.accept); bb.rejected.connect(dlg.reject); outer.addWidget(bb)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None
        val = {}
        for k, wdg in f.items():
            if isinstance(wdg, QLineEdit): val[k] = wdg.text().strip()
            elif isinstance(wdg, QComboBox): val[k] = wdg.currentText().strip()
            elif isinstance(wdg, QTextEdit): val[k] = wdg.toPlainText().strip()
            else: val[k] = wdg.value()
        val["ghs_classes"] = ", ".join(cb.text() for cb in ghs_boxes if cb.isChecked())
        if sds is not None:
            val["sds_number"] = sw["sds_number"].text().strip(); val["sds_revision"] = sw["sds_revision"].text().strip()
            val["sds_language"] = sw["sds_language"].text().strip() or "English"
            val["sds_issue"] = sw["issue"].date().toString("yyyy-MM-dd"); val["sds_due"] = sw["due"].date().toString("yyyy-MM-dd")
        if not val["product_name"]:
            QMessageBox.warning(self, "Required", "Product name is required.")
            return None
        return val

    _PCOLS = ["product_name", "supplier", "supplier_contact", "cas_number", "un_number", "product_use", "physical_state",
              "storage_group", "storage_location", "ghs_classes", "signal_word", "h_statements", "p_statements", "quantity",
              "unit", "project", "department", "ppe_required", "first_aid", "spill_response", "fire_fighting", "disposal",
              "status", "approved_by", "approval_date", "remarks"]

    def _add_product(self):
        v = self._product_dialog()
        if not v: return
        cols = self._PCOLS
        cur = self.db.execute(f"INSERT INTO chem_products({','.join(cols)},created_at,updated_at) VALUES({','.join('?'*len(cols))},?,?)",
                              [v[c] for c in cols] + [_now(), _now()])
        self._event(cur.lastrowid, "Chemical added", v["product_name"])
        self.refresh_all()
        QMessageBox.information(self, "Saved", "Chemical added. Attach its SDS in tab 2 - it shows as 'Missing' until then.")

    def _edit_product(self):
        pid = self._sel_id(self.reg_table, "chemical")
        if pid is None: return
        rec = self.db.fetchone("SELECT * FROM chem_products WHERE id=?", (pid,))
        v = self._product_dialog(rec)
        if not v: return
        cols = self._PCOLS
        self.db.execute(f"UPDATE chem_products SET {','.join(c+'=?' for c in cols)},updated_at=? WHERE id=?",
                        [v[c] for c in cols] + [_now(), pid])
        changed = [c for c in cols if _s(rec[c]) != _s(v[c])]
        self._event(pid, "Chemical updated", "Changed: " + ", ".join(changed) if changed else "No field changes")
        self.refresh_all()

    def _delete_product(self):
        pid = self._sel_id(self.reg_table, "chemical")
        if pid is None: return
        rec = self.db.fetchone("SELECT product_name FROM chem_products WHERE id=?", (pid,))
        if QMessageBox.question(self, "Delete Chemical",
                                f"Delete '{rec['product_name']}' and all its SDS records?\n(Tip: set Status to 'Disposed' instead to keep history.)",
                                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        self.db.execute("DELETE FROM chem_products WHERE id=?", (pid,))
        self._event(pid, "Chemical deleted", rec["product_name"])
        self.refresh_all()

    # ----- SDS tab -----
    def _build_sds_tab(self):
        w = QWidget(); self.tabs.addTab(w, "2. SDS Library")
        lay = QVBoxLayout(w)
        bar = QHBoxLayout()
        for text, fn in [("Upload SDS (auto-register)", self._upload_sds), ("Open SDS File", self._open_sds),
                         ("Mark Superseded", self._supersede_sds), ("Delete SDS Record", self._delete_sds)]:
            b = QPushButton(text)
            if fn == self._upload_sds:
                b.clicked.connect(lambda checked=False: self._upload_sds())
            else:
                b.clicked.connect(fn)
            bar.addWidget(b)
        bar.addStretch(1); lay.addLayout(bar)
        self.sds_table = self._mk_table(["ID", "Product", "SDS No.", "Revision", "Issue Date", "Review Due", "Language",
                                         "Status", "Review State", "File"])
        lay.addWidget(self.sds_table, 1)

    def refresh_sds(self):
        today_iso = today(); rows = []
        for s in self.db.fetchall("SELECT s.*, p.product_name FROM chem_sds s JOIN chem_products p ON p.id=s.product_id "
                                  "ORDER BY p.product_name, s.issue_date DESC"):
            state = chem_sds_state(s, today_iso) if s["status"] == "Current" else "Superseded"
            rows.append((s["id"], [s["id"], s["product_name"], s["sds_number"], s["revision"], s["issue_date"],
                                   s["review_due_date"], s["language"], s["status"], state, s["file_path"]]))
        self._fill(self.sds_table, rows, state_col=8)

    def _upload_sds(self, pid=None):
        """Pick SDS file(s) -> read text -> pre-fill review dialog -> save chemical + SDS in one step."""
        # QPushButton.clicked(bool) can pass False into this optional argument.
        # Only an actual positive integer database key means "attach to existing".
        if isinstance(pid, bool) or pid in (None, 0, ""):
            pid = None
        else:
            try:
                pid = int(pid)
            except (TypeError, ValueError):
                raise RuntimeError(f"Invalid Chemical Register record ID: {pid!r}")
        paths, _ = QFileDialog.getOpenFileNames(self, "Select SDS file(s)", "", "SDS Files (*.pdf *.docx);;All Files (*)")
        for i, path in enumerate(paths):
            try:
                result = self._import_one(path, pid)
            except Exception as exc:
                logging.exception("SDS import/save failed for %s", path)
                QMessageBox.critical(self, "SDS Import Failed",
                                     f"The SDS could not be saved:\n{Path(path).name}\n\n{exc}")
                result = "skip"
            if result == "stop":
                break
            if pid is not None:
                break
        self.refresh_all()

    def _new_revision(self):
        pid = self._sel_id(self.reg_table, "chemical (select it in tab 1 first)")
        if pid is not None:
            self._upload_sds(pid)

    def _import_one(self, path, pid=None):
        # Defensive normalization for callers other than the upload button.
        if isinstance(pid, bool) or pid in (None, 0, ""):
            pid = None
        else:
            try:
                pid = int(pid)
            except (TypeError, ValueError):
                raise RuntimeError(f"Invalid Chemical Register record ID: {pid!r}")
        fname = Path(path).name
        text = ""
        problem = ""
        try:
            text = chem_file_text(path)
        except Exception as exc:
            logging.exception("SDS read failed for %s", path)
            problem = str(exc) or f"Could not read the file: {type(exc).__name__}"

        if not problem and len(re.sub(r"\s+", "", text or "")) < 40:
            problem = ("The PDF/Word file opened, but it contains too little selectable text to identify the SDS details. "
                       "If it is a scanned PDF, OCR is needed. You can still continue and enter the chemical details manually.")
        parsed = chem_parse_sds(text) if not problem else {}
        existing = self.db.fetchone("SELECT * FROM chem_products WHERE id=?", (pid,)) if pid is not None else None
        if pid is not None and existing is None:
            # Never attempt an SDS insert against a stale register row id.
            raise RuntimeError(f"The selected chemical (ID {pid}) no longer exists in the Chemical Register. Refresh the register and try again.")
        rec = dict(parsed)
        if existing:
            ex = dict(existing)
            rec = {k: (ex[k] if ex.get(k) not in ("", None, 0) else parsed.get(k, ex.get(k, ""))) for k in self._PCOLS}
            for k in ("sds_number", "sds_revision", "sds_issue", "sds_language"):
                rec[k] = parsed.get(k, "")
        if problem:
            banner = f"<b>{html.escape(fname)}</b><br>{html.escape(problem)}"
        else:
            miss = chem_missing_fields(parsed)
            banner = (f"<b>Auto-read from {html.escape(fname)}</b> - check every field against the SDS before saving. "
                      "Quantity, storage location, project and approval are site data: enter them yourself."
                      + (f"<br><b>Not found:</b> {', '.join(miss)}" if miss else "")
                      + "<br>Storage group and GHS classes are <i>suggested</i> from the H-statements.")
        v = self._product_dialog(rec, sds=rec, banner=banner)
        if not v:
            return "skip"

        if pid is None:
            dup = self.db.fetchone(
                "SELECT id FROM chem_products WHERE lower(product_name)=lower(?) AND status!='Disposed'",
                (v["product_name"],)
            )
            if dup:
                ans = QMessageBox.question(
                    self, "Chemical Already Registered",
                    f"'{v['product_name']}' is already in the register.\n\n"
                    "Yes = add this as the NEW SDS REVISION of that chemical.\n"
                    "No = register it as a separate chemical.",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No | QMessageBox.StandardButton.Cancel
                )
                if ans == QMessageBox.StandardButton.Cancel:
                    return "skip"
                if ans == QMessageBox.StandardButton.Yes:
                    pid = int(dup["id"])

        folder = ATTACH_DIR / "sds" / (str(pid) if pid is not None else "pending")
        folder.mkdir(parents=True, exist_ok=True)
        dest = folder / f"{_stamp()}_{fname}"
        shutil.copy2(path, dest)
        conn = self.db.conn
        try:
            conn.execute("BEGIN IMMEDIATE")
            cols = self._PCOLS
            if pid is None:
                cur = conn.execute(
                    f"INSERT INTO chem_products({','.join(cols)},created_at,updated_at) "
                    f"VALUES({','.join('?' * len(cols))},?,?)",
                    [v[c] for c in cols] + [_now(), _now()]
                )
                pid = int(cur.lastrowid)
                event_type = "Chemical auto-registered from SDS"
            else:
                parent = conn.execute("SELECT id FROM chem_products WHERE id=?", (pid,)).fetchone()
                if parent is None:
                    raise RuntimeError(f"Chemical Register record {pid} was not found; the SDS was not attached.")
                conn.execute(
                    f"UPDATE chem_products SET {','.join(c+'=?' for c in cols)},updated_at=? WHERE id=?",
                    [v[c] for c in cols] + [_now(), pid]
                )
                event_type = "Chemical updated from new SDS"

            # Confirm the parent exists in the same transaction before adding the SDS.
            if conn.execute("SELECT 1 FROM chem_products WHERE id=?", (pid,)).fetchone() is None:
                raise RuntimeError("Chemical details were not saved, so the SDS attachment was cancelled.")
            # Store the attachment under the final chemical ID (not a temporary folder).
            final_folder = ATTACH_DIR / "sds" / str(pid)
            final_folder.mkdir(parents=True, exist_ok=True)
            final_dest = final_folder / dest.name
            if dest.parent != final_folder:
                shutil.move(str(dest), str(final_dest))
                dest = final_dest
            conn.execute("UPDATE chem_sds SET status='Superseded' WHERE product_id=? AND status='Current'", (pid,))
            conn.execute(
                "INSERT INTO chem_sds(product_id,sds_number,revision,issue_date,review_due_date,language,file_path,status,uploaded_by,uploaded_at) "
                "VALUES(?,?,?,?,?,?,?,'Current',?,?)",
                (pid, v["sds_number"], v["sds_revision"], v["sds_issue"], v["sds_due"],
                 v["sds_language"], str(dest), self._actor(), _now())
            )
            new_sds_id = int(conn.execute("SELECT last_insert_rowid()").fetchone()[0])
            for sec_no, sec_title, sec_text in chem_extract_sds_sections(text):
                conn.execute(
                    "INSERT OR REPLACE INTO chem_sds_sections(sds_id,section_no,section_title,section_content) VALUES(?,?,?,?)",
                    (new_sds_id, sec_no, sec_title, sec_text)
                )
            conn.execute(
                "INSERT INTO chem_events(product_id,event_type,details,actor,created_at) VALUES(?,?,?,?,?)",
                (pid, event_type, fname, self._actor(), _now())
            )
            conn.execute(
                "INSERT INTO chem_events(product_id,event_type,details,actor,created_at) VALUES(?,?,?,?,?)",
                (pid, "SDS attached", f"Rev {v['sds_revision']} issued {v['sds_issue']}; previous SDS superseded",
                 self._actor(), _now())
            )
            conn.commit()
        except Exception:
            conn.rollback()
            try:
                if dest.is_file():
                    dest.unlink()
            except Exception:
                logging.exception("Could not remove incomplete SDS copy: %s", dest)
            raise

        # Refresh every visible SDS view after the committed transaction.
        self.refresh_all()
        return "saved"

    def _open_sds(self):
        sid = self._sel_id(self.sds_table, "SDS")
        if sid is None: return
        s = self.db.fetchone("SELECT file_path FROM chem_sds WHERE id=?", (sid,))
        if not s or not Path(s["file_path"]).is_file():
            return QMessageBox.warning(self, "File Missing", "The stored SDS file cannot be found.")
        QDesktopServices.openUrl(QUrl.fromLocalFile(s["file_path"]))

    def _supersede_sds(self):
        sid = self._sel_id(self.sds_table, "SDS")
        if sid is None: return
        s = self.db.fetchone("SELECT product_id FROM chem_sds WHERE id=?", (sid,))
        self.db.execute("UPDATE chem_sds SET status='Superseded' WHERE id=?", (sid,))
        self._event(s["product_id"], "SDS marked superseded", f"SDS record {sid}")
        self.refresh_all()

    def _delete_sds(self):
        sid = self._sel_id(self.sds_table, "SDS")
        if sid is None: return
        if QMessageBox.question(self, "Delete SDS Record", "Delete this SDS record? (The stored file is kept on disk.)",
                                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                                QMessageBox.StandardButton.No) != QMessageBox.StandardButton.Yes:
            return
        s = self.db.fetchone("SELECT product_id FROM chem_sds WHERE id=?", (sid,))
        self.db.execute("DELETE FROM chem_sds WHERE id=?", (sid,))
        self._event(s["product_id"], "SDS record deleted", f"SDS record {sid}")
        self.refresh_all()

    # ----- alerts tab -----
    def _build_alerts_tab(self):
        w = QWidget(); self.tabs.addTab(w, "3. Compliance Alerts")
        lay = QVBoxLayout(w)
        self.kpi = QLabel(); self.kpi.setStyleSheet("font-size:15px;font-weight:bold;color:#17365D;padding:6px;")
        self.kpi.setWordWrap(True); lay.addWidget(self.kpi)
        lay.addWidget(QLabel("SDS gaps (active chemicals):"))
        self.gap_table = self._mk_table(["ID", "Product", "Location", "Issue", "Review Due"])
        lay.addWidget(self.gap_table, 1)
        lay.addWidget(QLabel("Incompatible chemicals stored in the same location:"))
        self.conf_table = self._mk_table(["Location", "Chemical A", "Group A", "Chemical B", "Group B", "Reason"])
        lay.addWidget(self.conf_table, 1)

    def refresh_alerts(self):
        today_iso = today(); sds = self._latest_sds_map()
        active = self.db.fetchall("SELECT * FROM chem_products WHERE status='Active' ORDER BY product_name")
        gaps = []; counts = {"Missing": 0, "Expired": 0, "Due Soon": 0}
        for p in active:
            s = sds.get(p["id"]); st = chem_sds_state(s, today_iso)
            if st in counts:
                counts[st] += 1
                gaps.append((p["id"], [p["id"], p["product_name"], p["storage_location"], f"SDS {st}", s["review_due_date"] if s else ""]))
        self._fill(self.gap_table, gaps, state_col=None)
        conf = chem_conflicts([{"name": p["product_name"], "storage_location": p["storage_location"],
                                "storage_group": p["storage_group"]} for p in active])
        self.conf_table.setRowCount(0)
        for row in conf:
            r = self.conf_table.rowCount(); self.conf_table.insertRow(r)
            for c, v in enumerate(row):
                it = QTableWidgetItem(_s(v)); it.setBackground(QBrush(QColor("#F8CBAD"))); self.conf_table.setItem(r, c, it)
        self.conf_table.resizeColumnsToContents()
        self.kpi.setText(f"Active chemicals: {len(active)}   |   SDS missing: {counts['Missing']}   |   "
                         f"SDS expired: {counts['Expired']}   |   Review due ≤{CHEM_DUE_SOON_DAYS} days: {counts['Due Soon']}   |   "
                         f"Storage conflicts: {len(conf)}")

    # ----- history tab -----
    def _build_history_tab(self):
        w = QWidget(); self.tabs.addTab(w, "4. Change History")
        lay = QVBoxLayout(w)
        bar = QHBoxLayout()
        bar.addWidget(QLabel("Double-click a history entry or select it and choose View Full Details."))
        bar.addStretch(1)
        view_btn = QPushButton("View Full Details")
        view_btn.clicked.connect(self._view_history_details)
        bar.addWidget(view_btn)
        lay.addLayout(bar)
        self.hist_table = self._mk_table(["When", "Who", "Event", "Details"])
        self.hist_table.setWordWrap(True)
        self.hist_table.setColumnWidth(0, 150)
        self.hist_table.setColumnWidth(1, 120)
        self.hist_table.setColumnWidth(2, 220)
        self.hist_table.setColumnWidth(3, 420)
        self.hist_table.doubleClicked.connect(lambda *_: self._view_history_details())
        lay.addWidget(self.hist_table, 1)

    def refresh_history(self):
        rows = [(r["id"], [r["created_at"], r["actor"], r["event_type"], r["details"]])
                for r in self.db.fetchall("SELECT * FROM chem_events ORDER BY id DESC LIMIT 1000")]
        self._fill(self.hist_table, rows)
        self.hist_table.resizeRowsToContents()

    def _view_history_details(self):
        event_id = self._sel_id(self.hist_table, "change history entry")
        if event_id is None:
            return
        row = self.db.fetchone("SELECT * FROM chem_events WHERE id=?", (event_id,))
        if not row:
            QMessageBox.warning(self, "History Entry", "The selected history entry is no longer available.")
            return
        dlg = QDialog(self)
        dlg.setWindowTitle("Change History - Full Details")
        screen = self.screen() or QApplication.primaryScreen()
        available = screen.availableGeometry() if screen else None
        width = min(760, int(available.width() * 0.90)) if available else 760
        height = min(620, int(available.height() * 0.85)) if available else 620
        dlg.resize(max(440, width), max(320, height))
        layout = QVBoxLayout(dlg)
        for label, value in (("Date / Time", row["created_at"]), ("User", row["actor"]),
                             ("Event", row["event_type"]), ("Chemical ID", row["product_id"])):
            line = QLabel(f"<b>{html.escape(_s(label))}:</b> {html.escape(_s(value))}")
            line.setTextFormat(Qt.TextFormat.RichText)
            line.setWordWrap(True)
            layout.addWidget(line)
        details = QTextEdit()
        details.setReadOnly(True)
        details.setPlainText(_s(row["details"]))
        layout.addWidget(details, 1)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        buttons.rejected.connect(dlg.reject)
        buttons.accepted.connect(dlg.accept)
        layout.addWidget(buttons)
        dlg.exec()

    # ----- export -----
    def _export_excel(self):
        path, _ = QFileDialog.getSaveFileName(self, "Export Chemical Register", "chemical_register.xlsx", "Excel Workbook (*.xlsx)")
        if not path: return
        if not path.lower().endswith(".xlsx"): path += ".xlsx"
        try:
            wb = Workbook(); ws = wb.active; ws.title = "Chemical Register"
            sds = self._latest_sds_map(); today_iso = today()
            heads = ["Product", "Supplier", "Supplier Contact", "CAS", "UN", "Use", "State", "Storage Group", "Location",
                     "GHS Classes", "Signal Word", "H-Statements", "P-Statements", "Qty", "Unit", "Project", "Department",
                     "PPE", "First Aid", "Spill Response", "Fire Fighting", "Disposal", "Status", "SDS Status", "SDS Rev", "SDS Review Due"]
            ws.append(["CHEMICAL REGISTER"]); ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(heads))
            ws["A1"].font = Font(size=16, bold=True, color="FFFFFF"); ws["A1"].fill = PatternFill("solid", fgColor="17365D")
            ws["A1"].alignment = Alignment(horizontal="center"); ws.append(heads)
            for c in ws[2]:
                c.font = Font(bold=True, color="17365D"); c.fill = PatternFill("solid", fgColor="D9EAF7")
                c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            for p in self.db.fetchall("SELECT * FROM chem_products ORDER BY product_name"):
                s = sds.get(p["id"])
                ws.append([p["product_name"], p["supplier"], p["supplier_contact"], p["cas_number"], p["un_number"], p["product_use"],
                           p["physical_state"], p["storage_group"], p["storage_location"], p["ghs_classes"], p["signal_word"],
                           p["h_statements"], p["p_statements"], p["quantity"], p["unit"], p["project"], p["department"],
                           p["ppe_required"], p["first_aid"], p["spill_response"], p["fire_fighting"], p["disposal"], p["status"],
                           chem_sds_state(s, today_iso) if p["status"] == "Active" else "-",
                           s["revision"] if s else "", s["review_due_date"] if s else ""])
            ws.freeze_panes = "A3"
            for col in ws.columns:
                from openpyxl.utils import get_column_letter
                ws.column_dimensions[get_column_letter(col[0].column)].width = min(max(max(len(_s(c.value)) for c in col) + 2, 12), 34)
            wb.save(path)
            QMessageBox.information(self, "Exported", f"Chemical register saved.\n{path}")
        except Exception as exc:
            logging.exception("Chemical register export failed")
            QMessageBox.critical(self, "Export Failed", str(exc))

    def refresh_all(self):
        self.refresh_register(); self.refresh_sds()
        if hasattr(self, "sds_sections_table"):
            self.refresh_sds_sections()
        if hasattr(self, "coshh_table"):
            self.refresh_coshh()


