def main():

    app = QApplication(sys.argv)

    app.setApplicationName(
        APP_NAME
    )

    app.setOrganizationName(
        "HSE"
    )

    window = MainWindow()

    window.showMaximized()

    sys.exit(
        app.exec()
    )


if __name__ == "__main__":
    main()

